window.DEEP = {"ar.law.defs":{"k":"نظام التعليم العام","t":"التعريفات والمراحل (المادة 1)","body":["**التعليم العام** في النظام يمتد **حتى نهاية الصف الثاني عشر**، ومراحله: **الحضانة، ورياض الأطفال، والصفوف 1–12**. ويعرّف النظام مصطلحات يكثر السؤال عنها."],"pts":["**النطاق ضاق وتحدّد:** السياسة شملت التعليم كله ومنه **التعليم العالي والجامعات** (المواد 108–149 منها)، والنظام خاص **بالتعليم العام حتى نهاية الصف الثاني عشر**.","**الطفولة المبكرة**: من **بداية الحضانة** حتى **نهاية الصف الثالث**.","**المعلم**: من **يُرخَّص له** بالعمل في مهنة التعليم العام.","**المنهج**: أهداف ونواتج تعلم مخطط لها يُتأكد منها **بالتقويم**.","**البرنامج**: نشاط داخل المنهج لهدف محدد؛ و**المقرر**: المحتوى الذي تتضمنه الخطة ويدرسه الطلاب."],"traps":["الطفولة المبكرة تنتهي **بنهاية الصف الثالث**، لا بنهاية رياض الأطفال؛ والإلزام (6–15) حدّ آخر."],"src":"نظام التعليم العام، المادة 1"},"ar.law.general":{"k":"نظام التعليم العام","t":"أحكام عامة يكثر السؤال عنها","body":["مواد قصيرة في النظام تتكرر في الأسئلة لأنها تحسم مواقف يومية في المدرسة."],"pts":["**اللغة** (المادة 5): العربية **اللغة الأساس**، ويجوز التعليم **بلغة إضافية** وفق ضوابط يقرها المجلس.","**تعليم البنات** (المادة 6): مدارس البنات مستقلة عن البنين **بعد الطفولة المبكرة**، مع جواز استثناء الخاص بضوابط يعتمدها مجلس الوزراء.","**التعليم حضوري** في جميع المراحل، والتقنية **جزء منه** لا بديل عنه (المادة 24).","للوزارة تكليف معلمي الحكومي **بتدريس مقررات خارج تخصصهم** وفق قواعد يقرها المجلس (المادة 46).","**الأسرة شريك**: الوزارة تضع ضوابط تمكّن أولياء الأمور من المشاركة في تحقيق أهداف التعليم (المادة 50).","**اللوائح التنفيذية** تضعها الوزارة بالتنسيق مع الجهات ذات العلاقة، وتصدر **بقرار الوزير** (المادة 67)."],"traps":["طلب الدراسة عن بُعد طوال العام بحجة التقنية لا يستقيم: التعليم **حضوري** والتقنية جزء منه."],"src":"نظام التعليم العام، المواد 5 و6 و24 و46 و50 و67"},"ar.law.effective":{"k":"نظام التعليم العام","t":"الصدور والنشر والنفاذ","body":["النظام **صدر ونُشر ولم يُطبَّق بعد**: نُشر في أم القرى **1448/2/10هـ** (24 يوليو 2026) ويُعمل به **بعد 180 يوماً من نشره** (المادة 68)، أي في حدود 20 يناير 2027."],"pts":["قرار مجلس الوزراء بالموافقة: **رقم 103 وتاريخ 1448/1/22هـ**.","المرسوم الملكي: **م/36 وتاريخ 1448/1/27هـ**.","**مجلس شؤون التعليم العام** يمارس اختصاصاته **من تاريخ النشر** (البند 2 من القرار).","يلغي النظام **كل ما يتعارض معه** (المادة 68)، وألغى القرار وثائق محددة [[مع فترة انتقالية|ar.law.repeal]]."],"traps":["مدة النفاذ تُحسب **من تاريخ النشر**، لا من تاريخ المرسوم ولا قرار مجلس الوزراء."],"src":"نظام التعليم العام، المادة 68؛ قرار مجلس الوزراء رقم 103 (1448/1/22هـ)؛ المرسوم الملكي م/36 (1448/1/27هـ)"},"ar.law.repeal":{"k":"نظام التعليم العام","t":"ما ألغاه قرار الموافقة على النظام","body":["قرار مجلس الوزراء 103 ألغى وثائق محددة مع **استمرار العمل بأحكامها** حتى يقر **مجلس شؤون التعليم العام** البديل **خلال سنة من نفاذ النظام**."],"pts":["**سياسة التعليم في المملكة** (قرار مجلس الوزراء 779 وتاريخ 1389/9/16هـ).","**لائحة تنظيم المدارس الأهلية** (1395هـ) و**لائحة المدارس الأجنبية** (1418هـ).","ضوابط إحداث مدارس التعليم العام، وضوابط تعيين مديري المدارس الأهلية، وضوابط مدارس تحفيظ القرآن الصيفية، وأحكام مدارس الثغر النموذجية.","و**نظام تعليم الكبار ومحو الأمية** (م/22 وتاريخ 1392/6/9هـ) بالشرط الانتقالي نفسه."],"traps":["الإلغاء **لا يوقف العمل فوراً**: الأحكام سارية حتى يصدر البديل خلال سنة من **النفاذ** (لا من النشر)."],"src":"قرار مجلس الوزراء رقم 103 وتاريخ 1448/1/22هـ، البنود 3–5 (أم القرى)"},"ar.law.council":{"k":"نظام التعليم العام","t":"مجلس شؤون التعليم العام","body":["مجلس ينشئه النظام **برئاسة وزير التعليم**، ونائبه **نائب الوزير للتعليم العام**. أما سياسة التعليم فنصت على «مجلس أعلى للتعليم» يشرف على شؤون التعليم بكافة أنواعه ومراحله (م231 منها)."],"pts":["أعضاؤه نواب وزراء (منهم المالية والصحة والموارد البشرية)، و**رئيس هيئة تقويم التعليم والتدريب**، و**4 مختصين** يعيَّنون 3 سنوات (المادة 7).","من اختصاصه: الخطط والسياسات، و**تحديد سن القبول**، وشروط التعاقد مع المعلمين، ولوائح الخاص وذوي الإعاقة والموهوبين ورياض الأطفال (المادة 8).","**التقويم الدراسي**: الوزارة تعدّه، والمجلس يرفعه موصياً، ومجلس الوزراء يعتمده (المادة 8).","يجتمع **كل 90 يوماً على الأقل**، والنصاب **ثلثا الأعضاء** (المادة 9).","و**الوزارة** هي الجهة المشرفة على التعليم العام (المادة 13)."],"traps":["رئيس المجلس **وزير التعليم**؛ رئيس هيئة تقويم التعليم والتدريب **عضو**.","المجلس يعمل **من تاريخ النشر**، قبل نفاذ بقية النظام."],"src":"نظام التعليم العام، المواد 7–9؛ قرار مجلس الوزراء رقم 103، البند 2؛ سياسة التعليم، المادة 231"},"ar.law.goals":{"k":"نظام التعليم العام","t":"أهداف النظام (المادة 2)","body":["الهدف: **الجودة وحسن الأداء**، وبناء الطلاب **دينياً ووطنياً وقيمياً وعلمياً وثقافياً ومهارياً**، عبر اثني عشر هدفاً."],"pts":["العقيدة الإسلامية، والولاء لولاة الأمر والانتماء للوطن و**الأسرة نواة المجتمع**، و**الهوية الوطنية**.","**إتقان العربية**، وقيم **التسامح والتعايش** وحقوق الإنسان.","**التحصن من التيارات المنحرفة** و**التعامل الواعي مع المحتوى الإعلامي**، و**التفكير الإبداعي والناقد**.","**التعلم مدى الحياة**، والبحث والابتكار و**التقنيات الناشئة**، والعمل التطوعي والصحة والسلامة.","**لغة أجنبية واحدة على الأقل** (الهدف 12)، وكانت السياسة تقول «لغة أخرى من اللغات الحية على الأقل» (م50 منها)."],"traps":["الهدف 12 «لغة أجنبية واحدة **على الأقل**»، لا «لغتان» ولا «الإنجليزية تحديداً»."],"src":"نظام التعليم العام، المادة 2؛ سياسة التعليم، المادة 50"},"ar.law.compulsory":{"k":"نظام التعليم العام","t":"الحق والمجانية والإلزام (المادتان 3 و4)","body":["التعليم العام **حق للجميع** و**مجاني في المؤسسات الحكومية**، وسن الإلزام **من السنة السادسة حتى الخامسة عشرة**. السياسة لم تضع سن إلزام، واكتفت بأن الابتدائي «متاح لكل من بلغ سن التعليم» (م121 منها)."],"pts":["الوزارة تتخذ الإجراءات النظامية تجاه **من يتسبب في حرمان الطفل** من التعليم أو **انقطاعه** خلال سنوات الإلزام (المادة 4/2).","**سن القبول** واقتراح تعديل **حدّي الإلزام** من اختصاص **المجلس** (المادة 8).","ومن الجديد الذي لم تعرفه السياسة: **سن إلزام من 6 إلى 15** (المادة 4)، و**قائمة حقوق للطالب** (المادة 38)، و**واجب الإبلاغ** عن الإيذاء (المادة 65)."],"ex":["طالب في الحادية عشرة انقطع لأن والده يشغّله في متجره. هو في سن الإلزام، فتتخذ الوزارة الإجراءات النظامية تجاه من تسبب في انقطاعه بالتنسيق مع الجهات المختصة (المادة 4/2)."],"traps":["سن الإلزام (6–15) غير مدى التعليم العام (حتى نهاية الصف الثاني عشر)."],"src":"نظام التعليم العام، المواد 3 و4 و8؛ سياسة التعليم، المادة 121"},"ar.law.inclusion":{"k":"نظام التعليم العام","t":"الكشف المبكر ودمج ذوي الإعاقة (المواد 19–21)","body":["ثلاث درجات: **كشف مبكر** عن اضطرابات النمو أو السلوك، ثم **دمج** ذوي الإعاقة في المؤسسات التعليمية، ثم **برامج ومراكز متخصصة** لمن يتعذر دمجه. والسياسة كانت تنص على تعليمهم «وفق إمكانياتها» بمناهج خاصة (م188 منها)."],"pts":["الدمج يصحبه **وسائل مناسبة** و**تقويم يراعي خصائصهم واحتياجاتهم وقدراتهم** و**تقنيات مساعدة وتكيفية** (المادة 20).","لمن يتعذر دمجه: برامج ومراكز متخصصة، وبرامج **رقمية وعن بُعد** (المادة 21).","لوائح ذوي الإعاقة والموهوبين يقرها **المجلس** (المادة 8)."],"ex":["طالب ضعيف بصر في فصل عادي: يبقى مدموجاً، وتُوفَّر له تقنيات مساعدة، ويُقوَّم بأساليب تراعي قدراته (المادة 20)."],"traps":["المركز المتخصص ليس الخيار الأول؛ هو **لمن يتعذر دمجه**."],"src":"نظام التعليم العام، المواد 8 و19–21؛ سياسة التعليم، المادة 188"},"ar.law.gifted":{"k":"نظام التعليم العام","t":"الموهوبون والتسريع (المادتان 22 و23)","body":["رعاية الموهوبين **باقية** من السياسة (م57 و192–194 منها)، والنظام يفصّلها ويضيف **ضوابط التسريع**."],"pts":["برامج **بفصول أو مدارس مخصصة**، و**مراكز إثرائية**، و**معايير واضحة** لتحديدهم، وتدريب المعلمين، وشراكات مع الجامعات (المادة 22).","**التسريع**: معايير للمؤهلين، و**تقويم شامل**، و**تنسيق مع أولياء الأمور**، بما يضمن استمرار التفوق والتكيف (المادة 23).","ومن واجب المعلم **اكتشاف الموهوبين والمبدعين** (المادة 49/2)."],"traps":["التسريع ليس قراراً بالدرجات وحدها؛ فيه **تقويم شامل** و**تنسيق مع ولي الأمر**."],"src":"نظام التعليم العام، المواد 22 و23 و49؛ سياسة التعليم، المواد 57 و192–194"},"ar.law.curriculum":{"k":"نظام التعليم العام","t":"المناهج والاختبارات الوطنية والاعتماد (المواد 27–30)","body":["ثلاث جهات: **المركز الوطني للمناهج** و**الوزارة** و**هيئة تقويم التعليم والتدريب**."],"pts":["**الإطار الوطني لمناهج التعليم العام**: تعدّه الوزارة والهيئة مع المركز الوطني للمناهج (المادة 27).","**الكتب الدراسية دون مقابل** لمن يطبق المنهج الحكومي (المادة 29).","المؤسسات تطبق **الاختبارات والمقاييس الوطنية والدولية** التي تنفذها الهيئة (المادة 30/1).","الخاص يلتزم **بالاعتماد المدرسي** من الهيئة أو هيئة دولية **تعتمدها الهيئة** (المادة 30/2)."],"traps":["الإطار الوطني للمناهج عمل **مشترك** بين ثلاث جهات، لا تنفرد به الوزارة."],"src":"نظام التعليم العام، المواد 27–30"},"ar.law.license":{"k":"نظام التعليم العام","t":"المؤسسات التعليمية الخاصة: الترخيص والرسوم (المواد 31–36)","body":["الترخيص **اختصاص الوزارة**، والقطاع الخاص يشمل **المستثمر الأجنبي** والقطاع غير الربحي. وكانت السياسة لا تسمح بترخيص المدارس الأهلية **لغير السعوديين** (م176 منها)."],"pts":["قرار الوزارة **كتابي خلال 30 يوماً**، والرفض **مسبَّب** مع **حق التظلم** (المادة 32).","لا يجوز **قبل موافقة الوزارة**: فتح المؤسسة، أو نقل ملكيتها، أو تغيير **اسمها أو موقعها أو مرحلتها** (المادة 33).","الالتزام **بتدريس مواد الهوية الوطنية** التي يعتمدها المركز الوطني للمناهج (المادة 31).","الرسوم: الوزارة تضع **معايير تعديلها** ويعتمدها **المجلس**، والمؤسسة تحدد رسومها وفقها (المادة 35)."],"traps":["مهلة الرد على الترخيص **30 يوماً**، لا 60 (التظلم من الجزاء) ولا 90 (اجتماع المجلس)."],"src":"نظام التعليم العام، المواد 31–36؛ سياسة التعليم، المادة 176"},"ar.law.srights":{"k":"نظام التعليم العام","t":"حقوق الطالب وواجباته (المادة 38)","body":["للطالب، إضافة إلى حقوقه في الأنظمة الأخرى والاتفاقيات الدولية، **سبعة حقوق**، وعليه **خمسة التزامات**. ولم تضع السياسة قائمة حقوق كهذه."],"pts":["(أ) بيئة تمكّنه من التحصيل. (ب) بيئة **آمنة نفسياً وجسدياً وفكرياً** وحمايته من **جميع أشكال الإيذاء**.","(ج) **سماع شكواه وقيدها واتخاذ الإجراء** حيالها. (د) **ألا يُكلَّف بعمل ناتج عن اجتهاد فردي** يخالف النظام واللوائح.","(هـ) **الرعاية الصحية الأولية**. (و) **جوائز وحوافز** عند تميزه. (ز) **تسلّم شهادة النجاح دون قيد أو شرط**.","الالتزامات: الاحترام، والحضور في الوقت، وبذل الجهد، **وعدم الإضرار بالمدرسة**، و**قواعد السلوك والمواظبة**."],"ex":["معلم ألزم طلابه بشراء أدوات غالية لمشروع لم يرد في الخطة ولا التعليمات. هذا تكليف ناتج عن اجتهاد فردي، ومن حق الطالب ألا يُكلَّف به (المادة 38/1/د)."],"traps":["الشكوى ثلاث خطوات: **سماع ثم قيد ثم إجراء**؛ الاكتفاء بالسماع ناقص.","الأمان في النظام ثلاثي: **نفسي وجسدي وفكري**."],"src":"نظام التعليم العام، المادة 38"},"ar.law.teacher":{"k":"نظام التعليم العام","t":"حقوق المعلم وواجباته (المادتان 48 و49)","body":["السياسة ركزت على **إعداد المعلم وتدريبه** (م163–172 منها)، والنظام يضع للمعلم **حقوقاً وواجبات** منصوصة."],"pts":["حقوقه في الحكومي: بيئة مناسبة، و**التدريب والتطوير المهني**، وفرص الإسهام في تطوير التعليم، وجوائز وحوافز (المادة 48).","التدريس **وفق الأهداف والبرامج المعتمدة** (المادة 49/1).","مراعاة **الفروق الفردية** و**أعلى مستويات العدالة** واكتشاف الموهوبين (المادة 49/2).","[[القدوة الحسنة والالتزام بالميثاق|ar.law.ethics]] (المادة 49/3)، واستثمار اليوم الدراسي (49/4)، والإسهام في التطوير المهني والبحوث (49/5)."],"traps":["التطوير المهني في النظام **حق** (المادة 48) و**واجب** (المادة 49/5) معاً."],"src":"نظام التعليم العام، المادتان 48 و49؛ سياسة التعليم، المواد 163–172"},"ar.law.ethics":{"k":"نظام التعليم العام","t":"القدوة وميثاق أخلاقيات مهنة التعليم (المادة 49/3)","body":["من واجبات المعلم: **تمثيل القدوة الحسنة** خُلقاً، و**الالتزام بقيم الهوية الوطنية**، و**الابتعاد عن كل ما يمس شرف المهنة داخل المدرسة وخارجها**، و**الالتزام بميثاق أخلاقيات مهنة التعليم**.","بذلك صار الالتزام بالميثاق **نصاً في نظام** صادر بمرسوم ملكي (يُعمل به بعد نفاذ النظام)، لا توجيهاً إدارياً فقط."],"pts":["عبارة **«داخل المدرسة وخارجها»** تُدخل سلوك المعلم العام، ومنه حضوره الرقمي، في واجب القدوة.","عند وجود **قرائن** على الإخلال بالنظام العام أو اللحمة الوطنية: تدابير عاجلة (المادة 58)، وعند **الثبوت**: جزاءات (المادة 59)."],"ex":["معلم ينشر في حسابه الشخصي محتوى ساخراً يمس زملاءه وطلابه ويقول: «هذا خارج الدوام». المادة 49/3 تجعل القدوة واجباً **داخل المدرسة وخارجها**."],"traps":["«ما يفعله المعلم خارج الدوام لا يخص المدرسة» يناقض نص المادة 49/3."],"src":"نظام التعليم العام، المادة 49 (الفقرة 3)"},"ar.law.penalties":{"k":"نظام التعليم العام","t":"المخالفات والجزاءات (المواد 57–64)","body":["لم تتضمن سياسة التعليم جزاءات. النظام يطبق على المعلمين والإداريين في الحكومي إجراءات **نظام الانضباط الوظيفي** عبر **لجنة المادة 62**، ويضع جزاءات بحسب الجسامة."],"pts":["**تدابير عاجلة** عند **قرائن** الإخلال بالنظام العام أو اللحمة الوطنية: منع من العمل داخل المؤسسة، أو **كف اليد مؤقتاً**؛ يتخذها الوزير أو من يفوضه (المادة 58).","بعد **الثبوت**: غير الجسيمة = أي جزاء عدا إنهاء الخدمة (ويجوز عند **التكرار**)؛ الجسيمة = **إنهاء الخدمة والمنع من العودة للتعليم العام والخاص** (المادة 59).","المدرسة الخاصة: إنذار، إيقاف تسجيل، **غرامة 5,000–50,000 ريال**، إلغاء الترخيص مع إكمال العام **على نفقة المالك** (المادة 60).","اللجنة **3 أعضاء على الأقل** (المادة 62)، والتظلم أمام **الجهة القضائية خلال 60 يوماً** (المادة 63).","**حكم قضائي نهائي** بجريمة مخلة بالأمانة أو الشرف = إجراءات **إنهاء خدماته** (المادة 64)."],"traps":["التدبير العاجل يكفيه **وجود قرائن**، والجزاء يشترط **الثبوت**.","المنع من العودة بعد الجسيمة يشمل **القطاع الخاص** أيضاً."],"src":"نظام التعليم العام، المواد 57–64"},"ar.law.report":{"k":"نظام التعليم العام","t":"واجب الإبلاغ عن الاعتداء والإيذاء (المادة 65)","body":["**على إدارة المؤسسة التعليمية إبلاغ الجهة المختصة** عن أي **اعتداء أو إيذاء** يقع **داخل المؤسسة أو في محيطها** على **أي من طلابها أو منسوبيها**، لاستكمال الإجراءات النظامية."],"pts":["المُلزَم: **إدارة المؤسسة**. المكان: **داخلها أو في محيطها**. المتضرر: **الطلاب أو المنسوبون**.","الغرض: **استكمال الإجراءات النظامية** لدى الجهة المختصة، لا إنهاء الموضوع داخلياً.","ويقابله حق الطالب في **بيئة آمنة وحمايته من جميع أشكال الإيذاء** (المادة 38/1/ب)."],"ex":["مشاجرة عنيفة أمام بوابة المدرسة بعد الانصراف أُصيب فيها طالب: المادة 65 تشمل **محيط المؤسسة**، فتبلغ الإدارة الجهة المختصة ولا تكتفي بالصلح."],"traps":["الاكتفاء بالصلح أو بإبلاغ ولي الأمر لا يحقق الإبلاغ إلى **الجهة المختصة**.","الاعتداء على **معلم** داخل المدرسة مشمول أيضاً."],"src":"نظام التعليم العام، المادة 65"},"ar.l05.mainidea":{"k":"استيعاب المقروء","t":["Main Idea","الفكرة الرئيسة والعنوان"],"body":["الفكرة الرئيسة هي ما تدور حوله جمل النص كلها، والأفكار الفرعية تخدمها بالشرح أو المثال أو التعليل. والعنوان المناسب صياغة مختصرة لها. طريقة عملية: اسأل «عمّ يتحدث النص كله؟» ثم «ماذا يقول عنه؟»."],"pts":["البديل الصحيح يشمل النص كله؛ ما يغطي جزءاً منه أضيق من المطلوب.","البديل الذي يذكر ما لم يرد في النص أوسع من المطلوب، فيُرفض أيضاً.","الغرض يُعرف من نوع الجمل: أخبار = إخبار، أدلة = إقناع، أمر ورجاء = حث، نهي وعواقب = تحذير."],"ex":["«تقلل القراءة اليومية التوتر، وتوسع المفردات، وتقوي الذاكرة؛ لذلك يوصي المختصون بعشرين دقيقة يومياً»: الفكرة الرئيسة فوائد القراءة اليومية والحث عليها، و«توسع المفردات» فكرة فرعية."],"traps":["البديل الذي ينقل جملة من النص حرفياً يغري لكنه غالباً تفصيل.","إذا كان النص يفسر سبب ظاهرة فالفكرة الرئيسة هي السبب لا مجرد وجود الظاهرة."],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 4.1: استيعاب المقروء","aka":["الفكرة الرئيسة","العنوان المناسب"]},"ar.l05.context":{"k":"استيعاب المقروء","t":["Meaning from Context & Inference","معنى الكلمة من السياق والاستنتاج"],"body":["معنى الكلمة يحدده موقعها: ضع كل بديل مكانها، والبديل الذي يستقيم به المعنى هو الصحيح. والاستنتاج معنى لم يُصرَّح به تدل عليه معطيات النص؛ فما ورد نصاً ليس استنتاجاً، وما لا تدل عليه القرائن ليس استنتاجاً كذلك."],"pts":["الضمير يعود على أقرب اسم يستقيم به المعنى، لا على أقرب اسم في اللفظ فقط.","طردية: يزيد الأول فيزيد الثاني؛ عكسية: يزيد الأول فينقص الثاني.","الاستفهام المنفي «ألم…؟» يُجاب في الإثبات بـ«بلى» وفي النفي بـ«نعم»."],"ex":["«أسدل الليل ستاره»: بتجربة البدائل (رفع، أرخى، مزّق) يستقيم «أرخى»."],"traps":["المعنى المعجمي الأشهر ليس دائماً المقصود في السياق."],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 4.1: استيعاب المقروء","aka":["معنى الكلمة من السياق","الاستنتاج","عود الضمير"]},"ar.l07.maturation":{"k":"مبادئ النمو","t":["Maturation, Learning & Readiness","النضج والتعلم والاستعداد"],"body":["النضج تغيرات داخلية بيولوجية تحدث تلقائياً دون تدريب، والتعلم تغير شبه دائم ينتج عن الخبرة والممارسة. والنضج **شرط** للتعلم؛ و**الاستعداد** بلوغ مستوى النضج والخبرة الذي يسمح بتعلم مهارة معينة."],"pts":["التعليم قبل الاستعداد يضيع الجهد ويولد الإحباط.","المشي يعتمد على النضج أساساً، والقراءة على النضج والتعلم معاً."],"ex":["طفل في الرابعة لم تنضج عضلاته الدقيقة: تبدأ المعلمة بأنشطة تهيئة (قص، تتبع خطوط كبيرة) قبل الكتابة الصغيرة."],"traps":["«التعلم شرط للنضج» عكس الصحيح."],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.1؛ أدبيات علم نفس النمو","aka":["النضج","الاستعداد"]},"ar.l07.havighurst":{"k":"النظريات","t":["Havighurst — Developmental Tasks","هافجهرست: مطالب النمو"],"body":["لكل مرحلة عمرية **مطالب نمو**: مهام ينبغي إتقانها في وقتها، تنشأ من النضج وتوقعات المجتمع وقيم الفرد؛ إنجازها يقود إلى النجاح في المطالب التالية، والإخفاق يصعّبها. وهو صاحب فكرة **اللحظة القابلة للتعلم**.","الفرق الحاسم: بياجيه **معرفي**، إريكسون **نفسي اجتماعي**، كولبرج **أخلاقي**، فرويد **نفسي جنسي**، هافجهرست **مطالب نمو**."],"pts":["الطفولة المتوسطة: القراءة والكتابة والحساب، ومهارات الألعاب، والتعامل مع الأقران، وتكوين الضمير والقيم.","المراهقة: تقبل الجسم، والاستقلال الانفعالي عن الوالدين، واختيار مهنة والاستعداد لها."],"traps":["«مهام ينبغي إنجازها في مرحلة» = هافجهرست، و«أزمة بين قطبين» = إريكسون."],"src":"Havighurst, Developmental Tasks and Education؛ المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.1","aka":["هافجهرست","مطالب النمو"]},"ar.l07.piaget":{"k":"النظريات","t":["Piaget — Cognitive Development","بياجيه: مراحل النمو المعرفي"],"body":["الطفل عند جان بياجيه **يبني معرفته بنفسه** من تفاعله مع البيئة، وتفكيره يختلف عن تفكير الراشد في النوع. ويمر الجميع بأربع مراحل **ثابتة الترتيب**، وعوامل الانتقال: النضج والخبرة والتفاعل الاجتماعي و[[الموازنة|ar.l09.adapt]]."],"pts":["**الحس-حركية (0–2)**: الحواس والحركة، وتنتهي بإدراك دوام الشيء.","**ما قبل العمليات (2–7)**: لغة ورموز ولعب إيهامي، مع التمركز حول الذات والإحيائية وغياب الاحتفاظ.","**العمليات المحسوسة (7–11)**: الاحتفاظ والمعكوسية والتصنيف، ومنطق على المحسوس فقط.","**العمليات المجردة (11+)**: تفكير افتراضي استنباطي واختبار فروض.","درس **المفاهيم الأساسية** (الزمن، المكان، العدد، السببية)؛ والتطبيق: **تعليم يناسب مرحلة النمو**، وطالب **المتوسطة والثانوية** تناسبه المناقشة والفروض.","تجربة الكرات الخشبية: طفل ما قبل العمليات لا يدرك **علاقة الجزء بالكل** (تضمين الفئات)؛ و**العمليات المحسوسة/المادية (7–11)** و**العمليات المجردة/الصورية (11 فأكثر)**."],"ex":["طالب الصف الثالث يحل «5 + 3» بالمكعبات ويتعثر في «س + 3 = 8»؛ لأنه في المحسوسات، فيمثل المعلم المجهول بصندوق مغلق قبل الرمز."],"traps":["الصف الرابع = العمليات المحسوسة حتى لو كان الطالب ذكياً.","التمركز حول الذات حدّ معرفي وليس أنانية."],"src":"Piaget & Inhelder, The Psychology of the Child؛ المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.1","aka":["بياجيه","مراحل بياجيه","النمو المعرفي","التمركز حول الذات"]},"ar.l07.conservation":{"k":"بياجيه","t":["Conservation vs. Object Permanence","الاحتفاظ ودوام الشيء"],"body":["**دوام الشيء** إدراك أن الشيء موجود وإن غاب عن الحواس، ويكتمل في نهاية الحس-حركية. و**الاحتفاظ** إدراك أن الكمية ثابتة رغم تغير الشكل، ويظهر في العمليات المحسوسة مع **المعكوسية** (إرجاع العملية ذهنياً)."],"pts":["يُكتسب الاحتفاظ تدريجياً: العدد أولاً، ثم الكتلة والسائل، ثم الوزن، ثم الحجم آخرها.","غياب الاحتفاظ سببه التمركز على بُعد واحد (الطول دون العرض)."],"ex":["تُباعد أزرار أحد صفين متساويين فيقول طالب الصف الثاني «ما زالت 7»: احتفاظ العدد."],"traps":["دوام الشيء عن **وجود** الشيء (نهاية الحس-حركية)، والاحتفاظ عن **ثبات الكمية** (بداية المحسوسة)."],"src":"Piaget & Inhelder, The Psychology of the Child","aka":["الاحتفاظ","دوام الشيء","المعكوسية"]},"ar.l07.erikson":{"k":"النظريات","t":["Erikson — Psychosocial Development","إريكسون: النمو النفسي الاجتماعي"],"body":["النمو عند إريك إريكسون **ثماني أزمات** نفسية اجتماعية من المهد إلى الشيخوخة؛ كل أزمة صراع بين قطبين، وحلها الإيجابي يمهد لما بعدها. ويركز على الأنا والمجتمع بدل الدوافع الجنسية، ويمد النمو طوال العمر."],"pts":["**الثقة مقابل عدم الثقة (0–1)** ← **الاستقلال مقابل الخجل والشك (1–3)** ← **المبادرة مقابل الذنب (3–6)**.","**الاجتهاد (الكفاءة) مقابل الدونية (6–12 = الابتدائية)**: إنجاز يُقدَّر؛ وتسمى **الكفاية (الإنجاز) مقابل الشعور بالنقص**.","**الهوية مقابل تشتت الهوية (12–18 = المراهقة)**: «من أنا؟».","**الألفة مقابل العزلة** ← **الإنتاجية مقابل الركود** ← **التكامل مقابل اليأس**."],"ex":["مهام قصيرة متدرجة ومدح للجهد المحدد وعرض أعمال الجميع في الصف الخامس تبني الاجتهاد وتقي من الدونية."],"traps":["المبادرة/الذنب لما قبل المدرسة لا للابتدائية.","إريكسون أزمات، وهافجهرست مطالب."],"src":"Erikson, Childhood and Society؛ المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.1","aka":["إريكسون","الاجتهاد مقابل الدونية","الهوية مقابل تشتت الهوية"]},"ar.l07.marcia":{"k":"النظريات","t":["Marcia — Identity Statuses","مارسيا: حالات الهوية"],"body":["جيمس مارسيا فصّل أزمة الهوية بمعيارين: هل **استكشف** المراهق البدائل؟ وهل **التزم** بخيار؟","حالاته الأربع: **التشتت**، **التبني المبكر/الانغلاق**، **التعليق/التأجيل**، **تحقيق الهوية**."],"pts":["**التشتت**: لا استكشاف ولا التزام.","**الانغلاق (التبني المبكر)**: التزام بلا استكشاف؛ هوية فرضها الوالدان.","**التعليق**: استكشاف بلا التزام بعد.","**التحقيق**: استكشاف ثم التزام عن قناعة."],"ex":["«سأدرس الطب لأن أبي قرر ذلك» دون بحث في غيره: انغلاق."],"traps":["الانغلاق ليس تحقيقاً للهوية رغم الالتزام؛ ينقصه الاستكشاف."],"src":"Marcia, Ego Identity Status (1966)","aka":["مارسيا","تعليق الهوية","الهوية المنغلقة"]},"ar.l07.kohlberg":{"k":"النظريات","t":["Kohlberg — Moral Development","كولبرج: مراحل النمو الأخلاقي"],"body":["لورنس كولبرج عرض **معضلات أخلاقية** (أشهرها معضلة هاينز) وصنّف **التبرير** لا الاختيار؛ فاثنان يختاران الشيء نفسه قد يكونان في مرحلتين مختلفتين. وانتهى إلى ثلاثة مستويات في كل منها مرحلتان بترتيب ثابت.","**ما قبل التقليدي** (الطفولة): **العقاب** (1) أو **المصلحة والمنفعة المتبادلة** (2)؛ **التقليدي**: «الولد الطيب» (3) و**القانون والنظام** (4)؛ **ما بعد التقليدي**: **العقد الاجتماعي** (5) و**المبادئ الأخلاقية العالمية** (6)."],"pts":["**ما قبل التقليدي**: (1) تجنب العقاب، (2) المصلحة المتبادلة.","**التقليدي**: (3) إرضاء الآخرين «الولد الطيب»، (4) القانون والنظام.","**ما بعد التقليدي**: (5) العقد الاجتماعي، (6) المبادئ الأخلاقية العالمية.","مناقشة المعضلات ترفع مستوى التبرير."],"traps":["«الولد الطيب» 3 و«القانون والنظام» 4، وكلاهما تقليدي.","الحكم وحده لا يحدد المرحلة."],"src":"Kohlberg, Essays on Moral Development؛ المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.1","aka":["كولبرج","المعضلة الأخلاقية"],"ex":["لماذا لا نغش؟ «حتى لا يُخصم مني» (1)، «حتى لا يزعل أبي» (3)، «لأن نظام المدرسة يمنعه» (4)، «لأن الغش ظلم لمن اجتهد» (مبدأ العدل)."]},"ar.l07.freud":{"k":"النظريات","t":["Freud — Psychosexual Stages","فرويد: المراحل النفسية الجنسية"],"body":["سيجموند فرويد مؤسس التحليل النفسي: الشخصية تتشكل مبكراً عبر مراحل نفسية جنسية، وتتكون من **الهو** (اللذة) و**الأنا** (الواقع، المنظم) و**الأنا الأعلى** (الضمير).","مراحله: **الفمية** (0–1)، **الشرجية** (1–3)، **القضيبية** (3–6)، **الكمون** (6–12 = الابتدائية)، **التناسلية** (المراهقة)؛ والشخصية **الهو** و**الأنا** و**الأنا الأعلى**."],"pts":["الفمية (0–1) ← الشرجية (1–3) ← القضيبية (3–6) ← **الكمون (6–12)** ← التناسلية.","الكمون: تهدأ الدوافع ويتجه الطفل إلى التعلم والمهارات والأقران."],"traps":["الكمون ليس سكوناً عن التعلم بل من أنشط مراحله.","الابتدائية: كمون عند فرويد، واجتهاد/دونية عند إريكسون."],"src":"Freud, Three Essays on the Theory of Sexuality","aka":["فرويد","مرحلة الكمون","الأنا الأعلى"]},"ar.l07.abuse":{"k":"الحماية","t":["Abuse & Neglect — Reporting","الإيذاء والإهمال: إجراء الإبلاغ"],"body":["تنص المادة 29 من قواعد السلوك والمواظبة على أن إجراءات حالات الإيذاء أو الإهمال تُتخذ **بشكل عاجل وسري** و**لا تتطلب التدرج**، بل بحسب خطورة الحالة. والعلامة الواحدة ليست دليلاً قاطعاً؛ المعلم يلاحظ ويوثق ويبلغ."],"pts":["إبلاغ **مدير المدرسة فوراً وبسرية**.","إحالة إلى **لجنة التوجيه الطلابي** لتقدير الخطورة (شديدة/متوسطة/بسيطة) ومستوى الخدمة (عاجلة/غير عاجلة)، ثم محضر رسمي واستدعاء ولي الأمر (ويُراعى اختيار الطالب لشخص مناسب إذا كان ولي الأمر هو المتسبب).","إبلاغ **مركز بلاغات وزارة الموارد البشرية والتنمية الاجتماعية (1919)** فوراً إذا تطلبت الحالة تدخلاً عاجلاً.","إذا كان المصدر أحد منسوبي المدرسة تُرفع الحالة إلى **إدارة التعليم**؛ ولمنسوبي المدرسة التبليغ إلى 1919 مباشرة عند تراخي الإدارة."],"traps":["المعلم لا يحقق بنفسه ولا يواجه الأسرة ولا يعد الطالب بالكتمان.","إجراءات الإيذاء لا تتدرج كالمخالفات السلوكية."],"src":"قواعد السلوك والمواظبة لطلبة التعليم العام، الإصدار الخامس 1447هـ، المادة 29","aka":["الإيذاء","الإهمال","مركز البلاغات"]},"ar.l08.gardner":{"k":"النظريات","t":["Gardner — Multiple Intelligences","جاردنر: الذكاءات المتعددة"],"body":["هوارد جاردنر رفض أن يكون الذكاء قدرة واحدة يقيسها اختبار واحد، ورأى أنه **أنواع مستقلة نسبياً** (ثمانية بعد إضافة الطبيعي)، يملك كل طالب خليطاً منها بدرجات مختلفة؛ فينوّع المعلم مداخل الدرس."],"pts":["لغوي، منطقي رياضي، مكاني (بصري)، جسمي حركي، موسيقي.","**اجتماعي (بين شخصي)**: فهم الآخرين؛ **ذاتي (ضمن شخصي)**: فهم الذات والتأمل.","**طبيعي**: تصنيف الكائنات والظواهر الطبيعية."],"ex":["طالبة تكتب مذكرات تحلل فيها مشاعرها وأهدافها: ذكاء ذاتي."],"traps":["فهم الذات = ذاتي، وفهم الآخرين = اجتماعي.","بصري/سمعي/حسي تصنيف أنماط تعلم لا ذكاءات."],"src":"Gardner, Frames of Mind؛ المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.2","aka":["جاردنر","الذكاءات المتعددة","الذكاء الذاتي","الذكاء الاجتماعي"]},"ar.l08.ld":{"k":"الفئات الخاصة","t":["Learning Disabilities","صعوبات التعلم"],"body":["اضطراب في عملية نفسية أساسية (الانتباه، الإدراك، الذاكرة، التفكير، اللغة) يظهر في تدنٍّ أكاديمي مع ذكاء عادي أو فوق العادي. ويحدد الدليل التنظيمي للتربية الخاصة الأهلية بـ**تباين واضح بين قدرات الطالب وتحصيله** في جانب أكاديمي (كالقراءة والكتابة والعد والاستدلال الرياضي) أو اضطراب في عملية نفسية، و**ألا تكون ناتجة** عن عوق عقلي أو اضطراب سلوكي أو أسباب حسية أو ظروف التعلم أو الرعاية الأسرية."],"pts":["نمائية (العمليات نفسها) وأكاديمية: الديسلكسيا قراءة، والديسغرافيا كتابة، والديسكالكوليا حساب.","بطء التعلم: ذكاء حدّي 70–85 وتدنٍّ في كل المواد؛ والتأخر الدراسي: ذكاء عادي وسبب خارجي.","يبقى الطالب في الفصل العادي ويتلقى دعماً في غرفة المصادر وفق خطة فردية."],"traps":["سبب تدني ذي الصعوبات اضطراب العمليات، لا انخفاض الذكاء ولا ضعف الدافعية."],"src":"الدليل التنظيمي للتربية الخاصة (وزارة التعليم)، أهلية ذوي صعوبات التعلم","aka":["صعوبات التعلم","محك التباين","محك الاستبعاد","بطء التعلم","التأخر الدراسي"]},"ar.l08.id":{"k":"الفئات الخاصة","t":["Intellectual Disability","الإعاقة الفكرية"],"body":["في الأدبيات: انخفاض ملحوظ في الأداء العقلي العام (دون 70 تقريباً) **مع قصور في السلوك التكيفي** في فترة النمو. ويحدد الدليل التنظيمي للتربية الخاصة الأهلية بألا تزيد درجة الذكاء على **75 على مقياس وكسلر أو 69 على ستانفورد بينيه (الصورة الخامسة)** أو ما يعادلهما، مع **قصور في مجالين على الأقل** من المهارات التكيفية.","**الإعاقة الفكرية (العقلية)**: ذكاء **أقل من 70** مع قصور في **السلوك التكيفي** قبل سن 18."],"pts":["الشرطان معاً: انخفاض الذكاء وقصور التكيف.","التدريس: أهداف وظيفية وخطوات صغيرة وتكرار وتعزيز فوري."],"traps":["لا يُحكم بالإعاقة من اختبار ذكاء وحده؛ الدليل يمنع الاكتفاء بمقياس واحد."],"src":"الدليل التنظيمي للتربية الخاصة (وزارة التعليم)، أهلية ذوي العوق العقلي","aka":["الإعاقة الفكرية","الإعاقة العقلية","السلوك التكيفي"]},"ar.l08.autism":{"k":"الفئات الخاصة","t":["Autism Spectrum Disorder","اضطراب طيف التوحد"],"body":["قصور مستمر في التواصل والتفاعل الاجتماعي مع سلوكيات نمطية تتكرر ومقاومة لتغيير الروتين. ويوزع الدليل التنظيمي الخدمات بالشدة: البسيط يُدمج في مدارس التعليم العام مع **غرفة المصادر**، وما لا يمكن دمجه في الصف العام يُخدم في **فصول خاصة ملحقة** بمدارس التعليم العام، والمتوسط والشديد المصاحب لإعاقات أخرى في **مراكز التوحد ومعاهد التربية الفكرية**."],"pts":["بيئة منظمة ثابتة: روتين وجداول بصرية وحدود واضحة (التعلم المنظم).","تعليمات قصيرة من خطوة واحدة، وتنبيه مسبق قبل أي تغيير.","أفضل أسلوب لترتيب بيئته **التعلم المنظم** (TEACCH).","**التوحد (اضطراب طيف التوحد)**: قصور في **التواصل والتفاعل الاجتماعي**، وسلوكيات **نمطية متكررة**، و**مقاومة التغيير**، ويظهر قبل الثالثة."],"traps":["البيئة المناسبة منظمة ثابتة لا «غنية بالمثيرات المتغيرة»."],"src":"الدليل التنظيمي للتربية الخاصة (وزارة التعليم)، أهلية ذوي اضطراب طيف التوحد","aka":["التوحد","اضطراب طيف التوحد","التعلم المنظم"]},"ar.l08.iep":{"k":"التربية الخاصة","t":["Assessment & the IEP","التشخيص والخطة التربوية الفردية"],"body":["القياس والتشخيص يجمع المعلومات بأدوات رسمية وغير رسمية من مصادر متعددة بفريق متعدد التخصصات. والخطة التربوية الفردية وثيقة تصف الخدمات التربوية والمساندة التي يحتاجها الطالب، يعدها فريق في المدرسة ويراجعها دورياً."],"pts":["التشخيص **بعد موافقة ولي الأمر خطياً**، ويرد ولي الأمر خلال مدة لا تتجاوز **14 يوماً** من الإشعار الخطي.","**عدم الاكتفاء بنتائج مقياس واحد**، وحفظ سرية المعلومات، والملاحظة عند الحاجة لمدة فصل دراسي كامل.","عناصر الخطة: الأداء الحالي ← أهداف طويلة وقصيرة قابلة للقياس ← الخدمات ومسؤولوها ← المواعيد ← التقويم.","الفريق: قائد المدرسة، ومعلما التربية الخاصة والتعليم العام، والموجه الطلابي، والمختصون، وولي الأمر، والطالب قدر الإمكان."],"ex":["هدف قصير جيد: «يقرأ 20 كلمة من كلمات الصف بدقة 90% خلال 6 أسابيع»؛ و«يتحسن في القراءة» غير قابل للقياس."],"traps":["معلم الصف يلاحظ ويحيل ويشارك، ولا يشخص."],"src":"الدليل التنظيمي للتربية الخاصة (وزارة التعليم)، القياس والتشخيص","aka":["الخطة التربوية الفردية","الإحالة","لجنة الخطط التعليمية"]},"ar.l08.inclusion":{"k":"التربية الخاصة","t":["Inclusion & Universal Access","الدمج والبيئة الأقل تقييداً والمواءمات"],"body":["الدمج تعليم ذوي الإعاقة في مدارس التعليم العام مع الخدمات الخاصة، في **البيئة الأقل تقييداً**: أقرب مكان إلى الفصل العام يحقق احتياج الطالب (فصل عام مع معلم مستشار أو متجول ← غرفة المصادر ← فصل خاص ← معهد).","ويحدد **دليل الوصول الشامل 1444** أساليب تعديل المنهج: الحجم، والوقت، والمدخل، والمخرج، وصعوبة المفهوم، والدعم، والتوقعات، والمنهج البديل."],"pts":["**مواءمات الاختبار**: تغيير آلية التطبيق دون تغيير بنيته (مكان منفرد، خط عريض، وقت إضافي).","**تعديلات الاختبار**: تغيير بنيته نفسها (تبسيط الأسئلة، شروح إضافية، آلة حاسبة).","أنواع الدمج: **مكاني**، **اجتماعي**، **أكاديمي (جزئي أو كلي)**، و**شامل**."],"traps":["المواءمة تغير طريقة التطبيق، والتعديل يغير الاختبار."],"src":"دليل ومعايير الوصول الشامل لذوي الإعاقة في المنشآت التعليمية 1444هـ؛ الدليل التنظيمي للتربية الخاصة (وزارة التعليم)","aka":["الدمج","البيئة الأقل تقييداً","الوصول الشامل","غرفة المصادر"]},"ar.l08.gifted":{"k":"الموهوبون","t":["Gifted Students — 1447 Rules","الموهوبون: التعريف وفصولهم"],"body":["تعرّف **القواعد التنظيمية لفصول ومدارس الموهوبين 1447هـ** الموهوبين بأنهم من لديهم **استعدادات وقدرات فوق عادية أو أداء متميز عن أقرانهم** في مجال أو أكثر يقدره المجتمع، ويحتاجون رعاية لا يوفرها المنهج العادي. وتعرّف **الإثراء** بخبرات متنوعة متعمقة لا يوفرها المنهج، و**التلمذة** بتواصل الموهوب مع متخصصين وخبراء."],"pts":["فصول الموهوبين **عامة** (إشراف إدارة التعليم) أو **تخصصية** (مع جهة مشاركة).","الفصل من 15 إلى 20 طالباً، ويُغلق إذا قل عن 12 طالباً لسنتين متتاليتين.","القبول باجتياز **مقاييس معتمدة** مع **أكثر من أداة** (سجل المنجزات، المقابلة، استمارات الترشيح، توصية المعلم).","الإثراء رأسي (تعميق) أو أفقي (توسيع)."],"traps":["الكشف لا يكون بالتحصيل وحده.","مزيد من التمارين نفسها ليس إثراءً."],"src":"القواعد التنظيمية لفصول ومدارس الموهوبين 1447هـ (المواد 1، 4، 5، 9)","aka":["الموهبة","الموهوب","الإثراء","التلمذة"]},"ar.l08.renzulli":{"k":"الموهوبون","t":["Renzulli & Gagné","مفهوم الموهبة: رنزولي وجانييه"],"body":["عند **جوزيف رنزولي** ينشأ السلوك الموهوب من تقاطع **ثلاث حلقات**: قدرة فوق المتوسط، وإبداع، والتزام بالمهمة؛ فلا يكفي الذكاء وحده.","وفرّق **فرانسوا جانييه** بين **الموهبة** (قدرة فطرية غير مدربة) و**التفوق** (أداء مكتسب يتحقق حين تُنمّى الموهبة بالتدريب وعوامل الشخص والبيئة)."],"pts":["الالتزام بالمهمة عنصر دافعي: مثابرة طويلة في مجال يحبه.","عند جانييه: كل متفوق موهوب، وليس كل موهوب متفوقاً.","الموهوب أداء **متميز عن أقرانه**: **قدرة فوق المتوسط** + **إبداع** + **التزام بالمهمة**؛ وعند جانييه كل **متفوق موهوب**."],"traps":["التحصيل المرتفع ليس من حلقات رنزولي الثلاث.","جانييه هنا فرانسوا صاحب نموذج الموهبة، لا روبرت صاحب شروط التعلم."],"src":"Renzulli, The Three-Ring Conception of Giftedness؛ Gagné, DMGT","aka":["رنزولي","الحلقات الثلاث","جانييه","التفوق"]},"ar.l08.accel":{"k":"الموهوبون","t":["Acceleration","التسريع (التعجيل)"],"body":["التسريع أسلوب للاستجابة لتفوق الطلبة، وأشكاله: القبول المبكر في الصف الأول، والتسريع في المادة أو المحتوى (ومنه ضغط المنهج)، والترفيع إلى صف أعلى. ويطبقه **الدليل التنظيمي لنظام التسريع** في المرحلتين الابتدائية والمتوسطة."],"pts":["مرتان في المسيرة: من **الرابع إلى السادس الابتدائي**، ومن **الأول إلى الثالث المتوسط**.","الترشيح: درجة القطع في مقياس موهبة، و**97% فأكثر في كل مادة**، و**98% معدلاً عاماً** في المتوسطة، وموافقة ولي الأمر والطالب.","اجتياز اختبار التسريع: **75%** معدلاً عاماً و**50%** في كل مادة.","التسريع يغير مستوى الطالب أو زمنه، والإثراء يبقيه في صفه."],"traps":["التسريع ليس حذف مواد."],"src":"الدليل التنظيمي لنظام التسريع (وزارة التعليم)، البنود 1-6 و1-9","aka":["التسريع","التعجيل","ضغط المنهج"]},"ar.l08.diff":{"k":"التدريس","t":["Tomlinson — Differentiated Instruction","التعليم المتمايز"],"body":["عند **كارول آن توملينسون** يُنوَّع التعليم وفق **استعداد** الطلاب و**اهتماماتهم** و**أنماط تعلمهم** مع بقاء **الهدف واحداً**، فيمايز المعلم في المحتوى أو العملية أو المنتج أو بيئة التعلم، بمجموعات مرنة تتغير بحسب المهمة."],"pts":["الصيغة: هدف واحد + مسارات متعددة = وصول الجميع.","أدواته: المهام المتدرجة، والمراكز، وعقود التعلم، وخيارات المنتج.","يُمايَز **المحتوى** أو **العملية** أو **المنتج** أو **بيئة التعلم** وفق **استعداد** الطالب و**اهتماماته** و**نمطه**؛ و**هدف واحد** + **مسارات متعددة** بـ**مجموعات مرنة**."],"ex":["هدف واحد (شرح أسباب الصيام): مجموعة تلخص نصاً، وأخرى تملأ مخططاً بعد مقطع، وثالثة تعد ملصقاً، ثم يُقوَّم الجميع بالمعيار نفسه."],"traps":["التمايز ليس تصنيفاً دائماً حسب الذكاء ولا أهدافاً مختلفة."],"src":"Tomlinson, The Differentiated Classroom؛ المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.2","aka":["التعليم المتمايز","المجموعات المرنة"]},"ar.l09.pavlov":{"k":"السلوكية","t":["Pavlov — Classical Conditioning","بافلوف: الإشراط الكلاسيكي"],"body":["قرن إيفان بافلوف صوتاً محايداً بالطعام (مثير غير شرطي يستدعي اللعاب) مرات عدة، حتى صار الصوت وحده **مثيراً شرطياً** يستدعي **استجابة شرطية**. وعلى أساسه أثبت **واطسون** في تجربة الطفل ألبرت أن الخوف يُتعلم بالاقتران.","**بافلوف – الإشراط الكلاسيكي**: السلوكية تفسر التعلم بـ**الارتباط بين المثير والاستجابة**، والمتعلم **متلقٍ سلبي**. وفي الكلاسيكي المثير **يسبق** والاستجابة **لا إرادية**، وقلق القاعدة **مكتسبة (مشروطة)**: **مثير محايد** + **غير شرطي** ← **مثيراً شرطياً** ← **استجابة شرطية**."],"pts":["**الانطفاء**: تكرار المثير الشرطي دون غير الشرطي.","**الاسترجاع التلقائي**: عودة الاستجابة المنطفئة بعد راحة.","**التعميم**: الاستجابة لمثيرات مشابهة؛ **التمييز**: للمثير الأصلي فقط."],"ex":["خوف طالبة من قاعة الاختبار المقترنة بالرسوب يضعف حين تُعقد فيها أنشطة ناجحة آمنة مرة بعد مرة."],"traps":["قلق الاختبار استجابة مكتسبة لا فطرية."],"src":"Pavlov, Conditioned Reflexes؛ Watson & Rayner (1920)","aka":["بافلوف","الإشراط الكلاسيكي","المثير الشرطي","واطسون"]},"ar.l09.skinner":{"k":"السلوكية","t":["Skinner — Operant Conditioning","سكنر: الإشراط الإجرائي"],"body":["السلوك الإجرائي عند ب. ف. سكنر يصدر طوعاً ثم **تتحكم فيه نتائجه** (صندوق سكنر). مفتاحه أربع خانات: التعزيز يزيد السلوك والعقاب يقلله، والموجب إضافة والسالب إزالة.","**التعزيز الموجب** إضافة سارّ، و**التعزيز السالب** إزالة منفّر، و**العقاب الموجب** إضافة منفّر، و**العقاب السالب** سحب معزّز؛ و**التعزيز بعد الاستجابة** هو مفتاح التعلم."],"pts":["**تعزيز سالب**: إزالة منفّر فيزيد السلوك (إعفاء من واجب لمن أنجز).","**عقاب سالب**: سحب سار فيقل السلوك؛ ومنه تكلفة الاستجابة والإقصاء.","**الانطفاء الإجرائي**: إيقاف التعزيز فيتلاشى السلوك.","**التشكيل**: تعزيز التقريبات المتتابعة؛ و**مبدأ بريماك**: النشاط المحبب يعزز غير المحبب.","تطبيقاته: التعليم المبرمج، وتعديل السلوك، والاقتصاد الرمزي."],"traps":["التعزيز السالب ليس عقاباً؛ كل تعزيز يزيد السلوك.","إجابات صحيحة بلا تعزيز ثم تراجع المشاركة = انطفاء إجرائي لا إشراط كلاسيكي."],"src":"Skinner, Science and Human Behavior؛ المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.3","aka":["سكنر","الإشراط الإجرائي","التعزيز السالب","العقاب السالب","التشكيل","مبدأ بريماك"]},"ar.l09.schedules":{"k":"السلوكية","t":["Schedules of Reinforcement","جداول التعزيز"],"body":["**المستمر** (بعد كل استجابة) أسرع تعلماً وأسرع انطفاءً، و**المتقطع** أثبت. والمتقطع أربعة: نسبة (عدد استجابات) أو فترة (زمن)، ثابتة أو متغيرة."],"pts":["**نسبة ثابتة**: نجمة كل 5 إجابات صحيحة.","**نسبة متغيرة**: بعد عدد غير منتظم؛ أعلى أداء وأقوى مقاومة للانطفاء.","**فترة ثابتة**: اختبار كل أسبوع؛ يرتفع الأداء قبيل الموعد.","**فترة متغيرة**: اختبارات قصيرة مفاجئة؛ أداء منتظم."],"traps":["الاختبار المفاجئ فترة متغيرة لا نسبة متغيرة؛ المعيار الزمن."],"src":"Ferster & Skinner, Schedules of Reinforcement","aka":["جداول التعزيز","جدول النسبة المتغيرة","التعزيز المتقطع"]},"ar.l09.bandura":{"k":"التعلم الاجتماعي","t":["Bandura — Observational Learning","باندورا: التعلم بالملاحظة"],"body":["أثبت ألبرت باندورا في تجربة **دمية بوبو** أن الأطفال يقلدون نموذجاً شاهدوه دون تعزيز مباشر. وتقوم نظريته على **الحتمية التبادلية** بين الفرد وسلوكه وبيئته، فهي جسر بين السلوكية والمعرفية."],"pts":["المراحل: الانتباه ← الاحتفاظ ← الإنتاج ← الدافعية.","**التعزيز البديل**: رؤية النموذج يُكافأ تزيد السلوك؛ والتعزيز الذاتي رضا الفرد عن أدائه.","النماذج: حية، ورمزية (فيديو، قصة)، ولفظية.","**الانفصال الأخلاقي**: تبرير السلوك المؤذي، كتسمية الاعتداء «مزاحاً» (التهذيب اللفظي)."],"ex":["طالب يرى زميله يُكرَّم لأنه أعاد محفظة وجدها فيزداد حرصه على الأمانة: تعزيز بديل."],"traps":["النمذجة ملاحظة (باندورا)، والتشكيل تعزيز تقريبات (سكنر)."],"src":"Bandura, Social Foundations of Thought and Action","aka":["باندورا","النمذجة","التعزيز البديل","الحتمية التبادلية"]},"ar.l09.gestalt":{"k":"المعرفية","t":["Gestalt — Insight","الجشطلت والاستبصار"],"body":["أسس **فرتهايمر** الجشطلت مع كوفكا وكوهلر، وشعارها: الكل أكبر من مجموع أجزائه. وفي تجربة **كوهلر** ركّب القرد عصوين فجأة ليجلب الموز: **الاستبصار**، أي إدراك مفاجئ للعلاقات بإعادة تنظيم الموقف."],"pts":["قوانين الإدراك: الشكل والأرضية، والتقارب، والتشابه، والإغلاق، والاستمرار.","الاستبصار مفاجئ ويبقى طويلاً وينتقل إلى مواقف مشابهة."],"traps":["الاستبصار مفاجئ، والمحاولة والخطأ (ثورندايك) تدريجي."],"src":"Köhler, The Mentality of Apes","aka":["الجشطلت","الاستبصار","كوهلر"]},"ar.l09.ausubel":{"k":"المعرفية","t":["Ausubel — Meaningful Reception Learning","أوزوبل: التعلم ذو المعنى"],"body":["أهم عامل في التعلم عند ديفيد أوزوبل **ما يعرفه المتعلم مسبقاً**: التعلم ذو المعنى يحدث حين تُربط المعلومة الجديدة بالبنية المعرفية، والحفظ المنفصل تعلم صم. ويمهد للدرس بـ**المنظم المتقدم**: مادة أعم وأشمل تُعرض قبله."],"pts":["المنظم المتقدم **شارح** (لغير المألوف) أو **مقارن** (يربط بالمألوف).","**التمايز التدريجي**: من العام إلى الخاص؛ و**التوفيق التكاملي**: ربط المفاهيم وإزالة التعارض.","أنماط التعلم: (استقبال/اكتشاف) × (ذو معنى/صم)."],"ex":["مقطع عن تجاذب المغناطيس وتنافره قبل درس الشحنات الكهربائية: منظم متقدم مقارن."],"traps":["المنظم المتقدم يربط معرفياً قبل الدرس، والتهيئة الحافزة تثير الانتباه فقط."],"src":"Ausubel, The Psychology of Meaningful Verbal Learning","aka":["أوزوبل","المنظم المتقدم","التعلم ذو المعنى"]},"ar.l09.bruner":{"k":"المعرفية","t":["Bruner — Discovery Learning","برونر: التعلم بالاكتشاف"],"body":["جيروم برونر رأى أن الطالب يتعلم أعمق حين **يكتشف** المبدأ بنفسه، والأنسب صفياً الاكتشاف الموجه. ويمر تمثيل المعرفة بثلاث مراحل: **عملي** (بالأشياء) ← **أيقوني** (بالصور) ← **رمزي** (باللغة والرموز)."],"pts":["**المنهج الحلزوني**: المفاهيم تعود عبر الصفوف بعمق متزايد.","يمكن تعليم أي موضوع لأي طفل بصورة أمينة تناسب تفكيره.","شارك في صياغة مفهوم السقالات مع وود وروس."],"ex":["مكعبات تبني مستطيلات (عملي) ← رسمها على ورق مربعات (أيقوني) ← «المساحة = الطول × العرض» (رمزي)."],"traps":["المنهج الحلزوني لبرونر، والمنظم المتقدم لأوزوبل."],"src":"Bruner, The Process of Education","aka":["برونر","التعلم بالاكتشاف","المنهج الحلزوني"]},"ar.l09.memory":{"k":"معالجة المعلومات","t":["Information Processing & Memory","معالجة المعلومات والذاكرة"],"body":["نموذج **أتكنسون وشيفرين**: ذاكرة **حسية** (سعة كبيرة ومدة قصيرة جداً) ← **عاملة/قصيرة المدى** (نحو 7±2 وحدات، 15–30 ثانية) ← **طويلة المدى** (غير محدودة). والانتباه بوابة الانتقال، والعمليات: ترميز ← تخزين ← استرجاع."],"pts":["النقل للطويلة: التسميع، والتجميع (التقطيع)، والتفصيل بالربط، والتنظيم، والوسائل التذكرية.","التداخل **القبلي**: القديم يعيق الجديد؛ و**البعدي**: الجديد يعيق القديم.","**الترميز المزدوج** (بايفيو): لفظي + بصري أقوى؛ و**الحمل المعرفي** (سويلر): لا تُثقل الذاكرة العاملة.","التدريب الموزع أفضل للاحتفاظ من المكثف."],"ex":["«055 – 123 – 4567» أسهل حفظاً من «0551234567»: تجميع يقلل الوحدات."],"traps":["اسم التداخل بحسب اتجاه الإعاقة: الجديد يعيق القديم = بعدي."],"src":"Atkinson & Shiffrin (1968)؛ Miller (1956)؛ Paivio؛ Sweller","aka":["معالجة المعلومات","الذاكرة العاملة","التداخل البعدي","الترميز المزدوج"]},"ar.l09.adapt":{"k":"البنائية","t":["Piaget — Assimilation & Accommodation","بياجيه: التمثل والمواءمة والموازنة"],"body":["ينظم العقل خبراته في **مخططات (سكيما)**. و**التمثل** إدخال الخبرة الجديدة في مخطط قائم دون تغييره، و**المواءمة** تعديل المخطط أو بناء جديد حين لا تناسبه الخبرة. و**الموازنة** تستعيد التوازن بعد **اختلال التوازن** (الحيرة) فيرتقي التفكير.","**بياجيه (البنائية المعرفية)**: التعلم **تكيّف** = **تمثل** + **مواءمة**، تحركه **الموازنة** بعد **اختلال التوازن**؛ والمتعلم **يبني** معرفته على **خبراته السابقة**."],"pts":["اختلال التوازن فرصة تعلم؛ لذلك يطرح المعلم مواقف محيرة تناسب المرحلة."],"ex":["طفل يسمي الخفاش طائراً (تمثل)، ثم يعرف أنه يرضع صغاره فيحتار (اختلال)، فيعدل: «ليس كل ما يطير طائراً» (مواءمة)."],"traps":["التمثل إضافة إلى مخطط قائم، والمواءمة تعديله.","الموازنة عملية منظمة لا مرحلة نمو."],"src":"Piaget, The Origins of Intelligence in Children","aka":["التمثل","المواءمة","الموازنة","المخطط","السكيما"]},"ar.l09.vygotsky":{"k":"البنائية","t":["Vygotsky — ZPD & Scaffolding","فيجوتسكي: منطقة النمو القريب"],"body":["التعلم عند ليف فيجوتسكي **اجتماعي أولاً ثم فردي**، واللغة أداة التفكير، والحديث الذاتي وسيلة لتنظيمه. و**منطقة النمو القريب** المسافة بين ما ينجزه الطالب **وحده** وما ينجزه **بمساعدة** الأكثر خبرة؛ والتدريس الفعال يستهدفها.","**فيجوتسكي (البنائية الاجتماعية)**: **اجتماعي أولاً**، و**اللغة أداة التفكير**، و**الحديث الذاتي** تطور لا عيب؛ و**منطقة النمو القريب (المجاور)** بين **وحده** و**بمساعدة**، و**السقالات (الدعائم)** تُسحب."],"pts":["**السقالات**: دعم مؤقت متدرج (نموذج، تلميح، سؤال) يُسحب مع التقدم؛ صاغ المصطلح وود وبرونر وروس.","تطبيقاته: التعلم التعاوني، والأقران، والتدريس التبادلي."],"traps":["منطقة النمو القريب ما يُنجز بالمساعدة لا وحده.","الدعم الدائم ليس سقالة؛ السقالة تُسحب."],"src":"Vygotsky, Mind in Society؛ Wood, Bruner & Ross (1976)","aka":["فيجوتسكي","منطقة النمو القريب","السقالات","الحديث الذاتي"],"ex":["طالبة تعجز وحدها عن كتابة فقرة، وتنجح ببدايات جمل وأسئلة توجيهية تُسحب تدريجياً: سقالات داخل منطقة النمو القريب."]},"ar.l10.maslow":{"k":"الدافعية","t":["Maslow — Hierarchy of Needs","ماسلو: هرم الحاجات"],"body":["رتب أبراهام ماسلو الحاجات في هرم لا تبرز فيه الحاجة الأعلى حتى تُشبع الأدنى: **فسيولوجية ← أمن ← انتماء ← تقدير ← تحقيق الذات**. وفي الصورة السباعية تُضاف **المعرفية** ثم **الجمالية** قبل تحقيق الذات."],"pts":["الدنيا حاجات نقص، والعليا حاجات نمو.","الطالب الجائع أو الخائف: ابدأ بالحاجة الدنيا قبل الأكاديمية."],"ex":["طالب يتعرض للتنمر: يبدأ المعلم بالأمن (إيقاف التنمر وإبلاغ الإدارة) ثم الانتماء (زميل مرافق) قبل حوافز الدرجات."],"traps":["المعرفية والجمالية قبل تحقيق الذات لا بعده."],"src":"Maslow, Motivation and Personality","aka":["ماسلو","هرم الحاجات","تحقيق الذات"]},"ar.l10.weiner":{"k":"الدافعية","t":["Weiner — Attribution & Learned Helplessness","واينر: العزو، والعجز المتعلم"],"body":["يدرس برنارد واينر تفسير الطالب لأسباب نجاحه وفشله على ثلاثة أبعاد: **الموقع** (داخلي/خارجي)، و**الثبات**، و**القابلية للضبط**. والعزو السيئ حين يتكرر يقود إلى **العجز المتعلم** (سليجمان): التوقف عن المحاولة رغم القدرة.","الأبعاد: **الموقع** و**الثبات** و**الضبط**؛ و**القدرة** داخلي ثابت، و**الجهد** متغير قابل للضبط، و**صعوبة المهمة** خارجي ثابت، و**الحظ** خارجي متغير. فيوجّه المعلم إلى **الجهد والاستراتيجية**، و**الإحباط** غير **العجز المتعلم** (سليجمان)."],"pts":["**القدرة**: داخلية ثابتة غير قابلة للضبط.","**الجهد**: داخلي متغير قابل للضبط؛ أفضل عزو للفشل.","**صعوبة المهمة**: خارجية ثابتة؛ **الحظ**: خارجي متغير.","الإحباط انفعال مؤقت، والعجز المتعلم توقف عن المحاولة.","**واينر – العزو**: عزو الفشل إلى **نقص الجهد** يدفع للمحاولة، وإلى **ضعف القدرة** يولّد الإحباط والعجز."],"traps":["عزو الفشل إلى القدرة يحبط، وإلى الجهد يحفّز."],"src":"Weiner, An Attributional Theory of Motivation and Emotion؛ Seligman, Helplessness","aka":["واينر","نظرية العزو","العزو","العجز المتعلم"]},"ar.l10.selfeff":{"k":"الدافعية","t":["Bandura — Self-Efficacy","الكفاءة الذاتية"],"body":["اعتقاد الفرد بقدرته على إنجاز **مهمة محددة** بنجاح (ألبرت باندورا). تؤثر في اختيار المهام والجهد والمثابرة والقلق، وتختلف عن تقدير الذات العام."],"pts":["مصادرها: **خبرات الإتقان** (أقواها)، والخبرات البديلة، والإقناع اللفظي، والحالة الفسيولوجية والانفعالية.","تُبنى بمهام متدرجة تضمن نجاحاً مبكراً ونماذج من الأقران."],"ex":["طالب يخاف الإلقاء: جملتان أمام مجموعته، ثم دقيقة أمام نصف الفصل، ثم عرض كامل."],"traps":["الكفاءة الذاتية خاصة بالمهمة وليست تقدير الذات العام."],"src":"Bandura, Self-Efficacy: The Exercise of Control","aka":["الكفاءة الذاتية"]},"ar.l10.achieve":{"k":"الدافعية","t":["Achievement Motivation & Yerkes–Dodson","دافع الإنجاز وقانون يركس–دودسون"],"body":["صاحب دافع الإنجاز المرتفع (ماكليلاند وأتكنسون) يفضل المهام **متوسطة الصعوبة**. وقانون **يركس–دودسون**: العلاقة بين الاستثارة (القلق) والأداء منحنى مقلوب؛ الأداء الأفضل عند استثارة **متوسطة**، والمهام الصعبة تحتاج استثارة أقل."],"pts":["**توجه الإتقان** (يسعى للتعلم) أفضل من **توجه الأداء** (يسعى للظهور).","**العقلية النامية** (دويك): الذكاء ينمو بالجهد؛ ومدح الجهد والاستراتيجية يبنيها."],"traps":["الأداء الأفضل عند قلق متوسط لا عند انعدامه."],"src":"McClelland؛ Atkinson (1957)؛ Dweck, Mindset؛ Yerkes & Dodson (1908)","aka":["دافع الإنجاز","قانون يركس–دودسون","توجه الإتقان","العقلية النامية"]},"ar.l10.factor":{"k":"الذكاء","t":["Factor Theories of Intelligence","النظريات العاملية في الذكاء"],"body":["**سبيرمان**: عامل عام (g) في كل الأنشطة وعوامل خاصة (s). **ثيرستون**: سبع قدرات أولية. **جيلفورد**: بنية العقل (عمليات × محتوى × نواتج = 120 ثم 180 قدرة) وصاحب التمييز بين التقاربي والتباعدي. **كاتل**: ذكاء سائل ومتبلور."],"pts":["قدرات ثيرستون: فهم لفظي، طلاقة لفظية، عددية، مكانية، ذاكرة، سرعة إدراكية، استدلال.","**السائل**: حل المشكلات الجديدة؛ يتراجع مع العمر. **المتبلور**: معارف مكتسبة؛ يزداد.","نسبة الذكاء = العمر العقلي ÷ الزمني × 100 (بينيه للعمر العقلي)؛ عقلي 10 وزمني 8 = 125."],"traps":["المتبلور يزداد مع العمر والسائل يتراجع."],"src":"Spearman (1904)؛ Thurstone, Primary Mental Abilities؛ Guilford, The Nature of Human Intelligence؛ Cattell (1963)","aka":["سبيرمان","ثيرستون","جيلفورد","بنية العقل","كاتل","الذكاء السائل","الذكاء المتبلور"]},"ar.l10.sternberg":{"k":"الذكاء","t":["Sternberg — Triarchic Theory","ستيرنبرغ: الذكاء الثلاثي"],"body":["رأى روبرت ستيرنبرغ أن الاختبارات التقليدية تقيس جانباً واحداً، واقترح ثلاثة أنواع متكاملة يسميها مجتمعة الذكاء الناجح."],"pts":["**التحليلي**: التحليل والمقارنة؛ ما تقيسه الاختبارات المدرسية.","**الإبداعي**: التعامل مع الجديد وتوليد الأفكار.","**العملي**: التكيف وحل مشكلات الحياة؛ «ذكاء الشارع»."],"ex":["طالب متوسط في الاختبار اللفظي يدير مقصف المدرسة بنجاح: ذكاء عملي."],"traps":["الثلاثي لستيرنبرغ لا يُخلط بذكاءات جاردنر الثمانية."],"src":"Sternberg, Beyond IQ","aka":["ستيرنبرغ","الذكاء الثلاثي","الذكاء العملي"]},"ar.l10.meta":{"k":"التفكير","t":["Flavell — Metacognition","ما وراء المعرفة"],"body":["**التفكير في التفكير** (جون فلافل): وعي الفرد بعملياته المعرفية والتحكم فيها بثلاث مهارات: **التخطيط** قبل المهمة، و**المراقبة** أثناءها، و**التقويم** بعدها.","**التفكير في التفكير**: **التخطيط** ← **المراقبة** ← **التقويم**."],"pts":["أسئلتها: ما خطتي؟ هل فهمت ما قرأت؟ كيف وصلت إلى الإجابة؟ هل هذه أفضل طريقة؟","استراتيجياتها: التفكير بصوت مسموع، وجدول KWL، والتقويم الذاتي، والمذكرات التأملية."],"traps":["القراءة الصامتة والحفظ مهارات معرفية؛ مراجعة الفهم أثناء القراءة ما وراء معرفية."],"src":"Flavell, Metacognition and Cognitive Monitoring (1979)","aka":["ما وراء المعرفة","التفكير في التفكير"]},"ar.l10.creative":{"k":"الإبداع","t":["Creative Thinking — Guilford & Torrance","التفكير الإبداعي ومكوناته"],"body":["أساس الإبداع عند **جيلفورد** التفكير التباعدي، ووضع **تورانس** اختبارات تقيس مكوناته: **الطلاقة** (عدد الأفكار)، و**المرونة** (تنوع فئاتها)، و**الأصالة** (ندرتها)، و**الإفاضة** (تفاصيلها)، ومعها **الحساسية للمشكلات**.","**التفكير الإبداعي** نشاط عقلي هادف يُنتج حلولاً **جديدة وأصيلة**، أساسه **التفكير التباعدي**؛ ومراحل والاس: **الإعداد** ← **الاحتضان/الكمون** ← **الإلهام/الإشراق** ← **التحقق**."],"pts":["مراحل والاس: إعداد ← احتضان ← إلهام ← تحقق.","العصف الذهني (أوزبورن): الكم قبل الكيف، وإرجاء الحكم، والترحيب بالغريب، والبناء على أفكار الآخرين.","معوقات: الخوف من الخطأ، والنقد المبكر، والجمود الذهني."],"traps":["الإلهام بعد الاحتضان لا قبله.","نقد الأفكار أثناء طرحها يخالف قواعد العصف الذهني."],"src":"Guilford (1950)؛ Torrance Tests of Creative Thinking؛ Wallas, The Art of Thought؛ Osborn, Applied Imagination","aka":["التفكير الإبداعي","الطلاقة","المرونة","الأصالة","الإفاضة","العصف الذهني"]},"ar.l10.debono":{"k":"برامج التفكير","t":["de Bono — Six Hats & CoRT","ديبونو: القبعات الست وكورت"],"body":["إدوارد ديبونو دعا إلى تعليم التفكير مباشرة، وصاغ **التفكير الجانبي** (الخروج من الأنماط المعتادة). والقبعات الست تفصل أنماط التفكير فيلبس الجميع القبعة نفسها في الوقت نفسه، وبرنامج **كورت** يعلم مهارات التفكير بأدوات مثل PMI."],"pts":["**البيضاء** حقائق، **الحمراء** مشاعر وحدس، **السوداء** حذر ومخاطر.","**الصفراء** فوائد، **الخضراء** إبداع وبدائل، **الزرقاء** ضبط التفكير والخلاصة.","PMI: إيجابيات وسلبيات ونقاط مثيرة للاهتمام.","تمييز: «ستفشل لأن…» = **سوداء**، «أشعر أنها لا تعجبني» = **حمراء**، «ما الأرقام؟» = **بيضاء**، «لنلخص ما توصلنا إليه» = **زرقاء**؛ وتفصل **الأنا** عن الفكرة."],"traps":["«أشعر أنها ستفشل» بلا تبرير = حمراء لا سوداء.","الزرقاء إدارة التفكير نفسه."],"src":"de Bono, Six Thinking Hats؛ CoRT Thinking Program","aka":["ديبونو","القبعات الست","برنامج كورت","التفكير الجانبي"]},"ar.l11.terms":{"k":"مداخل التدريس","t":["Approach, Strategy, Method, Style","المدخل والاستراتيجية والطريقة والأسلوب"],"body":["المدخل يحدد **لماذا** نعلّم بهذه الصورة، والاستراتيجية **الخطة**، والطريقة **الإجراء**، والأسلوب **البصمة الشخصية**. ونموذج التدريس تصور نظري لخطواته، وصنّف جويس وويل النماذج في أربع عائلات."],"pts":["**المدخل**: إطار فكري (البنائي، القصصي، البيئي، التكاملي).","**الاستراتيجية**: خطة شاملة مرنة تضم عدة طرق وأساليب.","**الطريقة**: إجراءات يشترك فيها المعلمون (المحاضرة، المناقشة، الاكتشاف)؛ و**الأسلوب** طابع شخصي في تنفيذها.","**التقنية أو الوسيلة**: أداة تخدم الطريقة، وليست طريقة.","عائلات جويس وويل: معالجة المعلومات، والاجتماعية، والشخصية، والسلوكية."],"ex":["معلمة تتبنى المدخل البنائي، فتختار استراتيجية دورة التعلم، وتنفذ الاستكشاف بطريقة الاكتشاف الموجه، بأسلوبها الهادئ في طرح الأسئلة."],"traps":["معلمان بالطريقة نفسها وأداء مختلف = **أسلوبان**.","السبورة الذكية أو المقطع المرئي **تقنية** لا طريقة."],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار السابع؛ جويس وويل، نماذج التدريس","aka":["المدخل","الاستراتيجية","الطريقة","الأسلوب"]},"ar.l11.approaches":{"k":"مؤشر 7.1","t":["Four Teaching Approaches","المداخل الأربعة للتدريس"],"body":["يطلب مؤشر 7.1 أن يحدد المعلم **الأسس النظرية** للمداخل العامة للتدريس، ويبرز أهميتها في تحفيز المتعلمين وتنمية مهاراتهم وتعديل سلوكهم وتنمية مهاراتهم الاجتماعية."],"pts":["**السلوكي** (سكنر): سلوك ظاهر، وتحليل المهمة، وتعزيز فوري؛ نماذجه الإتقان والتعليم المباشر والمبرمج.","**المعرفي** (الجشطلت، بياجيه، برونر، أوزوبل): تفكير واكتشاف؛ نماذجه الاكتشاف والاستقصاء والمنظم المتقدم.","**الإنساني** (روجرز، ماسلو): الوعي بالذات والاستقلالية والمسؤولية؛ نموذجه التدريس غير الموجه.","**الاجتماعي** (باندورا، فيجوتسكي): التفاعل والنمذجة؛ نماذجه التعاوني ولعب الأدوار والتقصي الجماعي.","**نمذجة السلوك**: المعلم أو زميل يؤدي السلوك المرغوب ليحاكيه الطلاب، مع تعزيز من يتقنه.","**المدخل الإنساني (الشخصي)** يعنى **بالجوانب الوجدانية والشخصية** ويشجع **الاستقلالية المنتجة** و**الإحساس بالمسؤولية**؛ ونموذجه **التدريس غير الموجه** (روجرز): المعلم ميسّر يتقبل الطالب ويصغي له بتعاطف، ويشاركه تحديد أهدافه وتقويم تقدمه في مناخ آمن."],"ex":["«يُجلس المعلم الطالب بجوار زميل متقن ليحاكيه» = اجتماعي؛ «يترك الطالب يختار موضوع بحثه ويقوّم تقدمه بنفسه» = إنساني."],"traps":["التدريس غير الموجه **لروجرز** ومدخله **إنساني**.","النمذجة **اجتماعي** (باندورا)، والاكتشاف **معرفي** (برونر)."],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، مؤشر 7.1 لرتبة الممارس","aka":["المدخل السلوكي","المدخل المعرفي","المدخل الإنساني","المدخل الاجتماعي"]},"ar.l11.induct":{"k":"طرق العرض","t":["Inductive & Deductive Methods","الاستقراء والاستنباط"],"body":["الاستقراء **من الجزء إلى الكل**: أمثلة يلاحظها الطالب ثم يستنتج القاعدة. والاستنباط **من الكل إلى الجزء**: قاعدة يعرضها المعلم ثم تُطبق على أمثلة. وجمع هربارت الاتجاهين في خمس خطوات: التمهيد، العرض، الربط، الاستنتاج، التطبيق."],"pts":["الاستقراء يناسب بناء **المفاهيم والتعميمات** ويبقى أثره أطول، لكنه أبطأ.","الاستنباط أسرع ويناسب التدريب على **تطبيق القاعدة**، لكنها قد تُنسى.","التعلم في الطرق المباشرة (الإلقاء والعرض) **استقبالي**.","الاستقراء يربط **النظرية بالتطبيق** ويبذل فيه الطالب جهداً ويصلح للمجموعات الكبيرة، وعيبه طول الوقت؛ والاستنباط سريع لكن يقل فيه الدافع."],"traps":["كلمة «يستنتج» لا تعني الاستنباط؛ استنتاج القاعدة من الأمثلة **استقراء**.","الطريقة الهربارتية تبدأ **بالتمهيد** لا بالعرض."],"src":"مراجع طرق التدريس العامة (الطريقة الهربارتية الاستدلالية)","aka":["الاستقراء","الاستنباط","الطريقة الهربارتية"],"ex":["معلم يكتب «كتبَ الطالبُ – حضرَ المعلمُ – نجحَ المجتهدُ» ويسأل عن حركة آخر الكلمة بعد الفعل حتى يستنتج الطلاب أن الفاعل مرفوع: هذا استقراء. ولو بدأ بالقاعدة ثم طلب أمثلة لكان استنباطاً."]},"ar.l11.discovery":{"k":"المدخل المعرفي","t":["Discovery Learning — Bruner","التعلم بالاكتشاف (برونر)"],"body":["يرى برونر أن ما يصل إليه الطالب بجهده أبقى مما يُعطى له جاهزاً؛ فيعرض المعلم مواد وأسئلة ويترك الطالب ينظم المعلومات حتى يصل إلى المفهوم. والاستقصاء أوسع منه: يصوغ الطالب سؤاله ويجمع الأدلة ويفسرها كالباحث."],"pts":["**الموجه**: المعلم يحدد المشكلة والأدوات والأسئلة؛ يناسب الصغار.","**شبه الموجه**: المعلم يحدد المشكلة مع بعض التوجيهات.","**الحر**: الطالب يحدد المشكلة والأدوات والإجراءات.","من أفكار برونر أيضاً **المنهج الحلزوني**."],"ex":["معلمة تعطي الطالبات مغناطيساً وأشياء متنوعة وتسأل: ما الذي ينجذب؟ وما المشترك بينها؟ حتى يصلن إلى أنه يجذب بعض الفلزات كالحديد: اكتشاف موجه."],"traps":["في **الحر** يحدد الطالب الأدوات والإجراءات، وفي **الموجه** يحددها المعلم.","الاكتشاف ينتهي **بمفهوم** لا بمنتج."],"src":"برونر، التعلم بالاكتشاف؛ المعايير التربوية العامة، مؤشر 7.1 (المدخل المعرفي)","aka":["الاكتشاف","التعلم بالاكتشاف","الاستقصاء"]},"ar.l11.problem":{"k":"طرق التدريس","t":["Problem Solving — Dewey","حل المشكلات (ديوي)"],"body":["جعل ديوي التفكير العلمي طريقة تدريس: موقف غامض فيه **هدف** و**مانع**، يتجاوزه الطالب بخطوات منظمة فيحدث **التعلم**."],"pts":["الخطوات: الشعور بالمشكلة ← تحديدها ← جمع البيانات ← وضع الفروض ← اختبارها ← النتيجة والتعميم.","**الفرض** تفسير مؤقت يُختبر بالأدلة.","المشكلات **محددة البنية** و**مفتوحة البنية**؛ والثانية أساس التعلم القائم على المشكلات.","**المشكلة** موقف غامض يحتوي **مانعاً** و**هدفاً** ويؤدي إلى **تعلم**."],"traps":["الخطوة الأولى **الشعور بالمشكلة**، والتحديد ثانية.","حل المشكلات لديوي، والمشروعات لتلميذه **كلباترك**."],"src":"ديوي، كيف نفكر؛ المعايير التربوية العامة، المعيار السابع","aka":["حل المشكلات"]},"ar.l11.project":{"k":"طرق التدريس","t":["Project Method — Kilpatrick","طريقة المشروعات (كلباترك)"],"body":["طوّر كلباترك، تلميذ ديوي، طريقة المشروعات: عمل هادف ممتد يختاره الطلاب ويخططونه وينفذونه، وينتهي **بمنتج ملموس** يُعرض ويُقوَّم. وذكر دليل المعلم في التعليم الإلكتروني 1447 «التعلم الإلكتروني القائم على المشاريع» ضمن الاستراتيجيات المقترحة."],"pts":["الخطوات: اختيار ← تخطيط ← تنفيذ ← تقويم، ثم كتابة **تقرير**.","أنواعه عند كلباترك: إنشائية، واستمتاعية، ولحل مشكلة، ولكسب مهارة.","فردي أو جماعي، والمعلم مرشد ومتابع."],"traps":["انتهى العمل **بمنتج** = مشروع؛ انتهى **بمفهوم** = اكتشاف."],"src":"كلباترك، طريقة المشروع؛ دليل المعلم في التعليم الإلكتروني، الإصدار الثاني 1447","aka":["طريقة المشروعات","المشروعات"]},"ar.l11.programmed":{"k":"المدخل السلوكي","t":["Programmed Instruction — Skinner","التعليم المبرمج"],"body":["تطبيق مباشر للإشراط الإجرائي عند سكنر: المادة **إطارات** صغيرة متدرجة، يستجيب الطالب في كل إطار فيعرف صحة إجابته فوراً (**تعزيز**)، ثم ينتقل **بخطوه الذاتي**. ومنه خرجت الحقائب والموديولات وعقود التعلم."],"pts":["**الخطية** (سكنر): مسار واحد للجميع.","**المتشعبة** (كراودر): عند الخطأ إطار علاجي ثم عودة.","**الفردي**: المهام نفسها لكل طالب منفرداً؛ **التفريدي**: مهام مختلفة بحسب الميول.","عيبه: لا ينمي التفاعل الاجتماعي ولا يناسب الأهداف الوجدانية."],"traps":["التعليم المبرمج **سلوكي**، لا معرفي.","المتشعب **لكراودر**، والخطي **لسكنر**."],"src":"سكنر، الإشراط الإجرائي والتعليم المبرمج","aka":["التعليم المبرمج"]},"ar.l11.coop":{"k":"الاستراتيجيات الاجتماعية","t":["Cooperative Learning — Johnson & Johnson","التعلم التعاوني"],"body":["التعلم التعاوني بنية تجعل نجاح الفرد مرتبطاً بنجاح المجموعة، وتجعل كل فرد مسؤولاً عن نصيبه. وإذا غاب أحد عناصره الخمسة عند جونسون وجونسون صار عملاً جماعياً تقليدياً."],"pts":["**الاعتماد الإيجابي المتبادل**: ننجح معاً أو نخفق معاً.","**المسؤولية الفردية**: يُقوَّم كل عضو على إسهامه.","**التفاعل وجهاً لوجه** و**المهارات الاجتماعية**.","**معالجة عمل المجموعة**: تقويم أدائها وتحسينه.","مجموعات **غير متجانسة** (4–6) بأدوار محددة."],"traps":["مجموعة ينجز فيها طالب واحد العمل كله تفتقد **المسؤولية الفردية**."],"src":"جونسون وجونسون، عناصر التعلم التعاوني","aka":["التعلم التعاوني"]},"ar.l11.jigsaw":{"k":"الاستراتيجيات الاجتماعية","t":["Jigsaw & STAD","جيكسو وفرق التحصيل"],"body":["في جيكسو (أرونسون) يُقسّم الدرس أجزاء، فيأخذ كل عضو في **المجموعة الأم** جزءاً، ويتعمق فيه مع أصحاب الجزء نفسه في **مجموعة الخبراء**، ثم يعود ليعلّمه لمجموعته. وفي فرق التحصيل STAD (سلافين) يُختبر كل طالب فردياً، وتُحسب نقاط الفريق من **مقدار تحسن** أعضائه."],"pts":["في جيكسو لا يكتمل الدرس إلا بكل الأجزاء، فيقوى الاعتماد المتبادل.","في STAD يرفع الطالب الأضعف نقاط فريقه إذا تحسّن."],"traps":["جيكسو = **مجموعات خبراء**؛ STAD = **اختبار فردي ودرجة فريق من التحسن**."],"src":"أرونسون (جيكسو)؛ سلافين (فرق التحصيل)","aka":["جيكسو","فرق التحصيل"],"ex":["معلمة تقسم درس «مناطق المملكة» أربعة أجزاء: تأخذ كل طالبة جزءاً، وتتعمق فيه مع صاحبات الجزء نفسه من المجموعات الأخرى، ثم تعود لتشرحه لمجموعتها الأم، ويُختم الدرس باختبار فردي."]},"ar.l11.conceptual":{"k":"التدريس البنائي","t":["Conceptual Change — Posner et al.","التغيير المفاهيمي"],"body":["التصورات البديلة أفكار كوّنها الطالب من خبرته اليومية تخالف العلم، وتقاوم التغيير لأنها تبدو له منطقية. واقترح بوسنر وزملاؤه أنه لا يستبدلها إلا بأربعة شروط."],"pts":["**عدم الرضا** عن التصور الحالي.","المفهوم الجديد **واضح**، و**معقول**، و**مثمر** يفسر مواقف جديدة.","الخطوات: كشف التصورات ← تناقض معرفي ← المفهوم العلمي ← التطبيق.","أدوات الكشف: اختبار تشخيصي ثنائي الشق، ومقابلة، وخرائط مفاهيم، وتوقع – لاحظ – فسّر.","خطوات التدريس: **كشف التصورات القبلية** ← **تناقض معرفي** بحدث يخالف التوقع ← المفهوم العلمي ← تطبيقه ← مقارنة الطالب بين تصوره القديم والجديد."],"traps":["إعادة الشرح دون إحداث **عدم الرضا** لا تغير التصور غالباً.","نموذج بوسنر للتصورات البديلة، لا للتعلم التعاوني."],"src":"بوسنر وزملاؤه، نموذج التغيير المفاهيمي؛ المعايير التربوية العامة، مؤشر 7.2","aka":["التغيير المفاهيمي","التغير المفاهيمي","التصورات البديلة","نموذج بوسنر"],"ex":["يتوقع الطلاب أن الكرة الحديدية تسقط أسرع من كرة بلاستيكية بالحجم نفسه، فيُسقطهما المعلم معاً فتصلان في وقت واحد تقريباً؛ المفاجأة تُحدث عدم الرضا، ثم يقدم المفهوم العلمي (توقع – لاحظ – فسّر)."]},"ar.l12.behav":{"k":"الأهداف","t":["Behavioral Objective — Mager","الهدف السلوكي ومكوناته"],"body":["عبارة تصف ما سيستطيع الطالب أداءه بعد الدرس بصورة تُرى وتُقاس. اشترط فيها روبرت ماجر سلوكاً ظاهراً، وشرطاً يُؤدى فيه، ومعياراً للإتقان. ويعدد دليل الاختبارات 2025 خصائص الهدف قبل بناء جدول المواصفات."],"pts":["يصف سلوك **الطالب** لا المعلم، و**الناتج** لا النشاط.","واضح لا يقبل إلا تفسيراً واحداً، و**بسيط** يتعلق بعملية واحدة.","فعله **قابل للملاحظة والقياس** (يعدد، يحل، يقارن)، لا «يفهم، يدرك، يعرف».","يشتمل على الحد الأدنى للأداء المقبول، وواقعي قابل للتحقيق."],"ex":["«أن يحدد الطالب **على خريطة صمّاء** (شرط) مواقع **خمس** مدن سعودية **على الأقل** (معيار)».","«أن يتعرف الطالب على أهمية الماء» فعلها غير قابل للقياس؛ وبعد التعديل: «أن يذكر الطالب ثلاث فوائد للماء دون الرجوع إلى الكتاب»."],"traps":["«أن يقرأ الطالب الدرس» نشاط لا ناتج.","«أن يعدد الطالب ويشرح أنواع الصخور» هدف مركب."],"src":"ماجر، صياغة الأهداف التعليمية؛ دليل الاختبارات: الأسس الفنية والعمليات الإجرائية 2025 (صياغة الأهداف بصورة سلوكية إجرائية)","aka":["الهدف السلوكي","الهدف الإجرائي"]},"ar.l12.smart":{"k":"الأهداف","t":["SMART Objectives","الأهداف الذكية SMART"],"body":["اختصار إنجليزي لخمس صفات يُفحص بها الهدف قبل اعتماده، يتقاطع مع شروط الهدف السلوكي ويضيف **الصلة** و**الإطار الزمني**."],"pts":["**S** محدد: سلوك واحد واضح.","**M** قابل للقياس: نعرف متى تحقق.","**A** قابل للتحقيق: يتحدى الطالب وهو في متناوله.","**R** وثيق الصلة بناتج التعلم والمعيار.","**T** محدد بزمن: نهاية الحصة أو الأسبوع."],"ex":["«أن يقرأ الطالب نصاً من 100 كلمة قراءة جهرية بأخطاء لا تزيد على 3 في نهاية الأسبوع الرابع»."],"traps":["هدف قابل للقياس لكنه مستحيل لمعظم الطلاب يخالف شرط **قابلية التحقيق**."],"src":"مراجع التخطيط للتدريس (معايير SMART)","aka":["SMART","الأهداف الذكية"]},"ar.l12.bloom":{"k":"المجال المعرفي","t":["Bloom's Taxonomy (1956)","تصنيف بلوم الأصلي"],"body":["نشر بلوم وزملاؤه عام 1956 تصنيفاً هرمياً لأهداف المجال المعرفي في ستة مستويات، كل مستوى يقوم على ما قبله. ويعتمده دليل الاختبارات 2025 في بناء جدول المواصفات."],"pts":["**المعرفة**: استرجاع حقائق ومصطلحات.","**الفهم**: تفسير وتلخيص وترجمة وإعطاء مثال؛ و**التطبيق**: استخدام القاعدة في موقف جديد.","**التحليل**: تفكيك إلى أجزاء وإدراك العلاقات.","**التركيب**: بناء جديد من الأجزاء؛ و**التقويم**: حكم بمعيار، وهو القمة.","الدنيا: تذكر وفهم وتطبيق؛ العليا: تحليل وتركيب وتقويم."],"traps":["في الأصلي القمة **التقويم**، وفي المعدل **الإبداع**."],"src":"بلوم وآخرون (1956)؛ دليل الاختبارات 2025 (تصنيف بلوم المعرفي)","aka":["تصنيف بلوم","بلوم"]},"ar.l12.revised":{"k":"المجال المعرفي","t":["Revised Taxonomy — Anderson & Krathwohl (2001)","التصنيف المعدل وبعد المعرفة"],"body":["جعل أندرسون وكراثوول التصنيف **ثنائي البعد**: بعد العمليات المعرفية (ستة أفعال، الإبداع في قمتها)، وبعد المعرفة (أربعة أنواع). والتقاؤهما يكوّن جدولاً من 24 خلية يُوصف فيه الهدف بفعله ونوع معرفته معاً."],"pts":["**حقائقية**: مصطلحات وتفاصيل (رمز عنصر، تاريخ حدث).","**مفاهيمية**: تصنيفات ومبادئ ونظريات (مفهوم الكثافة).","**إجرائية**: خطوات وطرائق ومتى تُستخدم (خطوات حل معادلة).","**ما وراء معرفية**: وعي الطالب بتفكيره واستراتيجياته (كيف أذاكر؟)."],"ex":["«أن يطبق الطالب خطوات القسمة المطولة» = تطبيق × معرفة إجرائية."],"traps":["«ما وراء المعرفي» نوع معرفة، وليس مستوى سابعاً."],"src":"أندرسون وكراثوول (2001)، التصنيف المعدل","aka":["التصنيف المعدل","بعد المعرفة"]},"ar.l12.verbs":{"k":"المجال المعرفي","t":["Action Verbs by Level","أفعال مستويات بلوم"],"body":["الفعل أسرع مفتاح للتصنيف، بشرط النظر إلى **المهمة كاملة**؛ فـ«اشرح» قد تكون تذكراً إذا كان الشرح محفوظاً حرفياً."],"pts":["**تذكر**: يعدد، يسمي، يعرّف. **فهم**: يشرح، يفسر، يلخص، يعطي مثالاً.","**تطبيق**: يحل، يستخدم، يحسب في موقف جديد.","**تحليل**: يقارن، يميز، يفكك، يبين السبب.","**تقويم**: يحكم، ينقد، يبرر، يفاضل بمعيار.","**إبداع (تركيب)**: يصمم، يقترح، يؤلف، يخطط."],"ex":["«أيهما أفضل للترشيد: المصابيح الموفرة أم إطفاء الأجهزة؟ برّر» تقويم؛ «صمّم ملصقاً لحملة الترشيد» إبداع."],"traps":["«يقارن» و«يميز» **تحليل** لا فهم.","«يقترح» **تركيب**، و«ينقد» **تقويم**."],"src":"دليل الاختبارات 2025 (الأفعال المرتبطة بمستويات بلوم)","aka":["أفعال بلوم"]},"ar.l12.krath":{"k":"المجال الوجداني","t":["Affective Domain — Krathwohl","المجال الوجداني (كراثوول)"],"body":["خمسة مستويات تقيس **درجة استدخال القيمة**: من الانتباه لها إلى أن تصير سمة ثابتة توجه السلوك."],"pts":["**الاستقبال**: الانتباه والإصغاء.","**الاستجابة**: المشاركة برضا والتطوع.","**التقييم**: تقدير القيمة وتبنيها والدفاع عنها.","**التنظيم**: ترتيب القيم في منظومة عند تعارضها.","**التميز بالقيمة (الوسم)**: القيمة جزء ثابت من الشخصية."],"ex":["طالب يسلّم محفظة وجدها (استجابة)، ثم يدافع عن الأمانة في نقاش (تقييم)، حتى يُعرف بين زملائه بالأمين (تميز بالقيمة).","«أن يشارك الطالب تطوعاً في حملة تنظيف الفصل» = استجابة."],"traps":["**التركيب** و**التقمص** ليسا من مستويات كراثوول.","«يقدّر جهود العلماء» هدف **وجداني**."],"src":"كراثوول وبلوم وماسيا، تصنيف الأهداف: المجال الوجداني","aka":["كراثوول","المجال الوجداني"]},"ar.l12.simpson":{"k":"المجال النفس‑حركي","t":["Psychomotor Domain — Simpson","المجال النفس‑حركي (سمبسون)"],"body":["تصنيف سمبسون أشهر تصنيفات المهارات الحركية بسبعة مستويات، تبدأ بالإحساس والملاحظة وتنتهي بابتكار أداء جديد. ويقابله ديف (التقليد ← المعالجة ← الدقة ← الترابط ← التطبيع) وهارو."],"pts":["**الإدراك الحسي** ← **الاستعداد** ← **الاستجابة الموجهة** (تقليد ومحاولة وخطأ).","**الآلية**: أداء بثقة وعادة.","**الاستجابة المعقدة**: أداء ماهر سريع دقيق.","**التكيف**: تعديل المهارة لموقف جديد؛ ثم **الإبداع**."],"ex":["طالب يقلد التصويب بتوجيه المعلم (استجابة موجهة)، ثم يصوب بثقة (آلية)، ثم يغير طريقته حين يتغير موقع المدافع (تكيف).","«أن يغسل يديه بالخطوات الصحيحة بإتقان دون تذكير» = آلية."],"traps":["**الإدراك والاستعداد** أدنى النفس‑حركي، و**الاستقبال والاستجابة** أدنى الوجداني.","**التطبيع** أعلى مستويات ديف لا سمبسون."],"src":"تصنيفات سمبسون وديف وهارو للمجال النفس‑حركي","aka":["سمبسون","المجال النفس‑حركي"]},"ar.l12.set":{"k":"مهارات التدريس","t":["Set Induction & Closure","التهيئة والغلق"],"body":["التهيئة دقائق تنقل الطالب إلى داخل الدرس: تجذب الانتباه، وتربط الجديد بالسابق، وتوضح ما سنفعله. والغلق يقابلها في آخر الحصة فيجمع الأفكار ويثبتها."],"pts":["**الحافزة**: تثير الاهتمام (سؤال مثير، قصة، تجربة مفاجئة).","**التوجيهية**: تربط بالسابق وتوجه الانتباه (قريبة من المنظم المتقدم عند أوزوبل).","**الانتقالية**: بين أجزاء الدرس؛ **التقويمية**: تتأكد من إتقان السابق قبل الانتقال.","**الغلق**: تلخيص وربط وتثبيت، كبطاقة خروج أو سؤال جامع."],"ex":["«تعلمنا أمس أن للهواء وزناً، واليوم نرى كيف يدفع الأجسام» تهيئة توجيهية؛ و«لماذا لم ينسكب الماء من الكوب المقلوب؟» تهيئة حافزة."],"traps":["التي **تربط بالسابق** توجيهية، والتي **تثير الاهتمام فقط** حافزة."],"src":"مراجع مهارات التدريس (التهيئة والغلق)","aka":["التهيئة","الغلق","التهيئة الحافزة","التهيئة التوجيهية"]},"ar.l12.gagne":{"k":"خطة الدرس","t":["Gagné's Nine Events of Instruction","أحداث التدريس التسعة (جانييه)"],"body":["رتب روبرت جانييه الحصة الفعالة في تسعة أحداث متتابعة تقابل عمليات التعلم الداخلية، فيظهر موقع كل عنصر من عناصر الخطة."],"pts":["1) جذب الانتباه 2) إخبار المتعلمين بالأهداف 3) استثارة التعلم السابق.","4) عرض المحتوى 5) توجيه التعلم.","6) استدعاء الأداء 7) تقديم التغذية الراجعة.","8) تقويم الأداء 9) تعزيز الاحتفاظ والانتقال."],"traps":["الحدث الأول **جذب الانتباه** لا عرض المحتوى.","التغذية الراجعة **بعد الأداء** وقبل التقويم."],"src":"جانييه، شروط التعلم","aka":["جانييه","أحداث التدريس التسعة"]},"ar.l12.feedback":{"k":"التقويم من أجل التعلم","t":["Feedback","التغذية الراجعة"],"body":["معلومات يتلقاها الطالب عن أدائه تبين ما أحسن فيه، وما يحتاج إلى تحسين، وكيف. ومن مرتكزات لائحة تقويم الطالب 2025 تعزيز **التقويم من أجل التعلم** في الصف، والتغذية الراجعة قلبه."],"pts":["**فورية** أو في أقرب وقت، و**محددة ووصفية**.","**تركز على المهمة لا الشخص**، ومستمرة بلغة بسيطة.","أفضل صورها **تقدير مع تعليق** يوضح ما أُحسن وما يُحسَّن.","التعزيز تراكم **وجداني**، والتغذية الراجعة تراكم **معرفي**."],"ex":["بدل «أحسنت»: «رتبت خطوات الحل صحيحاً، وأخطأت في إشارة العدد في السطر الثالث؛ راجع ضرب السالب في السالب»."],"traps":["«ممتاز» وحدها تعزيز عام، **ليست** تغذية راجعة كافية."],"src":"لائحة تقويم الطالب في التعليم العام 2025، المادة 3 (مرتكزات تقويم الطالب)","aka":["التغذية الراجعة"]},"ar.l13.flipped":{"k":"نماذج التعلم","t":["Flipped Classroom","الصف المقلوب"],"body":["ينتقل الشرح إلى **المنزل** عبر مقطع قصير أو قراءة، وينتقل التطبيق إلى **الحصة** حيث المعلم حاضر ليساعد، فيُستثمر وقت الحصة في التفاعل والتفكير العالي. وأدرجه دليل المعلم في التعليم الإلكتروني 1447 ضمن الاستراتيجيات التي يفعّلها المعلم."],"pts":["قبل الحصة: مقطع قصير مع سؤال تحقق.","في الحصة: حل مسائل ونقاش ومشروع وتصحيح أخطاء.","من لم يشاهد المقطع يحتاج بديلاً سريعاً في بداية الحصة."],"ex":["معلم كيمياء يرفع على منصة مدرستي مقطعاً مدته ست دقائق عن موازنة المعادلات، ثم يوزع الطلاب في الحصة على مجموعات تحل معادلات متدرجة الصعوبة."],"traps":["المقلوب: الشرح **في المنزل** والتطبيق **في الفصل**؛ والمدمج مزيج حضوري وإلكتروني بأي صورة."],"src":"دليل المعلم في التعليم الإلكتروني، الإصدار الثاني 1447","aka":["الصف المقلوب","الفصل المقلوب"]},"ar.l13.pbl":{"k":"نماذج التعلم","t":["Problem-Based & Project-Based Learning","التعلم القائم على المشكلات والمشروعات"],"body":["في **التعلم القائم على المشكلات** يبدأ الدرس بمشكلة واقعية **غير محددة البنية** بلا حل واحد، فيتعلم الطلاب المحتوى وهم يبحثون عن حل. وفي **القائم على المشروعات** يعمل الطلاب مدة أطول على مهمة تنتهي **بمنتج** يُعرض. وذكرهما دليل المعلم في التعليم الإلكتروني 1447 لتنمية مهارات القرن 21."],"pts":["المشكلات: البداية **مشكلة**، والنهاية حل مقترح مبرر.","المشروعات: البداية **سؤال محوري**، والنهاية **منتج**.","المعلم ميسّر يقوّم بسلالم تقدير معلنة."],"traps":["المسألة الرياضية ذات الحل الواحد ليست مثالاً على التعلم القائم على المشكلات؛ مشكلته **مفتوحة البنية**."],"src":"دليل المعلم في التعليم الإلكتروني، الإصدار الثاني 1447","aka":["التعلم القائم على المشكلات","التعلم القائم على المشروعات"]},"ar.l13.5e":{"k":"النموذج البنائي","t":["5E Learning Cycle — Bybee","دورة التعلم الخماسية"],"body":["أصلها ثلاثي عند كاربلس (استكشاف، تقديم المفهوم، تطبيق)، وطوّرها بايبي إلى خمس مراحل يبدأ اسم كل منها بحرف E. وسمتها الأهم أن الطلاب **يجربون قبل أن يُشرح لهم**."],"pts":["**الانشغال**: إثارة الاهتمام وكشف المعرفة السابقة.","**الاستكشاف**: نشاط عملي قبل الشرح.","**التفسير**: الطلاب يفسرون والمعلم يقدم المصطلح.","**التوسع**: تطبيق المفهوم في موقف جديد.","**التقويم**: في كل مرحلة وفي النهاية."],"traps":["الخماسية تبدأ **بالانشغال**، والثلاثية لكاربلس **بالاستكشاف**.","التطبيق في موقف جديد مرحلة **التوسع** لا التفسير."],"src":"بايبي، نموذج 5E؛ كاربلس، دورة التعلم","aka":["دورة التعلم","5E"]},"ar.l13.diff":{"k":"مؤشر 8.3","t":["Differentiated Instruction — Tomlinson","التعليم المتمايز"],"body":["تعرّف توملينسون التمايز بأنه استجابة المعلم المخططة لاختلاف طلابه: الهدف ومعايير النجاح واحدة، والطرق إليها تختلف بحسب **الاستعداد** و**الاهتمامات** و**نمط التعلم**."],"pts":["**المحتوى**: ما يتعلمه الطالب أو مستوى المادة ومصادرها.","**العملية**: الأنشطة التي يفهم بها المفهوم نفسه.","**المنتج**: كيف يُظهر ما تعلمه.","**البيئة**: ترتيب المكان والمجموعات والجو الصفي.","يبدأ عادة بتقويم قبلي يوجه تقسيم المجموعات المرنة."],"ex":["درس «الكسور المتكافئة»: مجموعة بقطع ملموسة، وأخرى برسوم، وثالثة بمسائل حياتية؛ الهدف واحد والعملية مختلفة."],"traps":["التمايز **لا يعني** خفض الهدف للضعفاء ولا زيادة التمارين المتشابهة للمتفوقين."],"src":"توملينسون، الصف المتمايز؛ المعايير التربوية العامة، مؤشر 8.3","aka":["التعليم المتمايز","التدريس المتمايز"]},"ar.l13.elearn":{"k":"التقنية في التعليم","t":["E-learning & the Teacher's Role","أنماط التعليم الإلكتروني ودور المعلم"],"body":["تعرّف لائحة تقويم الطالب 2025 التعليم الإلكتروني بأنه توظيف تقنيات التعليم والمعلومات والاتصالات لرفع كفاية العملية التعليمية بجميع أنماطها وضبط جودتها. ويحدد دليل المعلم في التعليم الإلكتروني (الإصدار الثاني 1447) دور المعلم عبر منصة مدرستي وقنوات عين."],"pts":["**المتزامن**: في الوقت نفسه من أماكن مختلفة (الفصل الافتراضي)؛ **غير المتزامن**: في أوقات مختلفة (مسجل، واجبات).","قبل الدراسة: التحقق من الدخول إلى المنصة، والاطلاع على أدلتها وعلى **آداب السلوك الرقمي** والتحقق من اطلاع الطلاب عليها.","أثناء الدراسة: إعداد الدرس والخطة الأسبوعية، والحصة المتزامنة، و**رصد الحضور**، وإسناد الواجبات والاختبارات وتصحيحها مع **التغذية الراجعة**.","أدوات التقييم في الدليل: التقييم الإلكتروني، والتقييم الذاتي المفتوح عبر بنوك الأسئلة، والاختبارات المركزية.","الأصل الحضور في المدرسة، والالتحاق بالتعليم الإلكتروني استثناء في حالات خاصة (الإجراءات التنفيذية للائحة تقويم الطالب، القاعدة السادسة)."],"traps":["المقطع المسجل الذي يشاهده الطالب متى شاء **غير متزامن** وإن كان بصوت معلمه."],"src":"دليل المعلم في التعليم الإلكتروني، الإصدار الثاني 1447؛ لائحة تقويم الطالب 2025 (التعريفات)؛ الإجراءات التنفيذية للائحة تقويم الطالب، القاعدة السادسة","aka":["التعليم الإلكتروني","التعليم المتزامن","التعليم غير المتزامن"]},"ar.l13.samr":{"k":"دمج التقنية","t":["SAMR & TPACK","نموذجا SAMR وTPACK"],"body":["**SAMR** (بونتيدورا) يقيس عمق أثر التقنية في المهمة: درجتان **تحسين** ودرجتان **تحويل**. و**TPACK** (ميشرا وكوهلر) يصف معرفة المعلم المطلوبة: المحتوى، وطرق التدريس، والتقنية، وتقاطعها."],"pts":["**الاستبدال**: بديل مباشر بلا تغيير وظيفي.","**التعزيز**: بديل مع تحسين وظيفي (مدقق إملائي، تعليق فوري).","**التعديل**: إعادة تصميم كبيرة للمهمة.","**إعادة التعريف**: مهمة لم تكن ممكنة دون تقنية."],"traps":["الاستبدال **لا يغير** المهمة.","TPACK عن **معارف المعلم**، وSAMR عن مستوى **المهمة**."],"src":"بونتيدورا (SAMR)؛ ميشرا وكوهلر (TPACK)","aka":["SAMR","TPACK"],"ex":["كتابة الفقرة في مستند بدل الورق استبدال؛ وحين يعلّق الزملاء عليها فوراً تعزيز؛ وحين يتبادل الطلاب الرسائل مع طلاب مدرسة في مدينة أخرى صارت المهمة مستحيلة دون تقنية: إعادة تعريف."]},"ar.l13.curr":{"k":"المنهج","t":["Curriculum: Concept & Types","المنهج: مفهومه وأنواعه"],"body":["المنهج **التقليدي** هو المقرر والمعلومات، و**الحديث** جميع الخبرات المخططة التي تقدمها المدرسة داخلها وخارجها لتحقيق النمو الشامل؛ فالمنهج أعم من المقرر، والمقرر أعم من الكتاب. وعناصره: الأهداف ← المحتوى ← الطرق والأنشطة ← التقويم."],"pts":["**الرسمي (المعلن)**: الوثيقة المكتوبة المعتمدة.","**الخفي** (جاكسون): ما يُتعلم ضمناً من المناخ والعلاقات دون تخطيط.","**الفارغ (المحذوف)** (آيزنر): ما لم يُدرج عمداً.","تنظيمات بارزة: النشاط (ديوي)، والحلزوني (برونر)، والمحوري، والمجالات الواسعة."],"traps":["الخفي **غير مخطط**، والفارغ **حُذف عمداً**."],"src":"مراجع المناهج (جاكسون، آيزنر، ديوي، برونر)","aka":["المنهج","المنهج الخفي","المنهج الفارغ"],"ex":["لاحظ الطلاب أن معلمهم يحضر قبل الجرس ويعتذر إذا تأخر دقيقة، فصاروا يحترمون الوقت دون أن يرد ذلك في أي درس: منهج خفي."]},"ar.l13.udl":{"k":"مؤشر 8.3","t":["Inclusive Education & UDL","التعليم الشامل والتصميم الشامل للتعلم"],"body":["يطلب مؤشر 8.3 أن يطبق المعلم **ممارسات التعليم الشامل وأسس التدريس المتمايز** لتحسين تقدم كل طالب. والتعليم الشامل يعلّم الجميع معاً في الفصل العام، ويكيّف البيئة والمنهج والتدريس والتقويم ليشارك الجميع."],"pts":["**الدمج** يطلب من الطالب التكيف مع النظام؛ **الشمول** يغيّر النظام.","مبادئ UDL: وسائل متعددة **للتمثيل**، و**للتعبير والأداء**، و**للمشاركة والتحفيز**.","التمايز أداة من أدوات الشمول، والشمول أوسع منه.","ممارسات شاملة: توقعات عالية للجميع، ومجموعات مرنة، وتقنيات مساعدة، ودعم الأقران، وتسهيلات في الواجبات والاختبارات، وتعاون مع معلم التربية الخاصة."],"ex":["درس يُقدَّم بنص ومقطع مرئي مصحوب بنص مكتوب ومجسم، وتُظهر الطالبات فهمهن برسم أو تسجيل صوتي أو فقرة: تخطيط مسبق يناسب ضعيفة السمع والموهوبة معاً."],"traps":["الشمول **ليس** خفض الأهداف ولا عزل ذوي الاحتياج في ركن الصف."],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، مؤشر 8.3","aka":["التعليم الشامل","التصميم الشامل للتعلم","UDL"]},"ar.l13.cross":{"k":"المعيار الثامن","t":["Cross-Curricular Dimensions","الأبعاد المشتركة بين المناهج"],"body":["مهارات وقيم لا تملكها مادة بعينها، بل تُنمّى عبر كل المواد بخبرات مباشرة أو ضمنية. والمعتمد في مؤشرات المعيار الثامن: أولويات + قيم ست + مهارات."],"pts":["**الأولويات**: المواطنة المسؤولة، ومكانة المملكة الريادية، والتنمية المستدامة.","**القيم الست** (مؤشر 8.4): تقوى الله، والوسطية والاعتدال، وتقدير الذات، والشغف المعرفي، وتقدير العمل وإتقانه، والمسؤولية.","**المهارات**: حل المشكلات، والاعتماد على الذات، والمسؤولية، والتعامل باحترام مع الآخرين.","التضمين **الضمني** بالمواقف أقوى من الوعظ المباشر.","**الشغف المعرفي**: حب الاستطلاع والرغبة الذاتية في المعرفة؛ يُنمّى بالأسئلة المفتوحة والمشكلات الحقيقية والمشروعات البحثية.","قائمة مختصرة شائعة الاستعمال: **الهوية الوطنية والقيم**، **مهارات التفكير العليا**، **المهارات الحياتية**، **الثقافة الرقمية**، **مهارات اللغة والتواصل**؛ والمعتمد نص المؤشرات أعلاه."],"ex":["طالبات يقسن استهلاك الماء في دورات مياه المدرسة أسبوعاً ثم يعرضن حلولاً على الإدارة: تنمية مستدامة (أولوية)، ومسؤولية (قيمة)، وحل مشكلات (مهارة).","معلم الرياضيات الذي يدرج نشاطاً عن الميزانية الأسرية ينمي **المهارات الحياتية**، ومعلم الإنجليزية الذي يربط الدرس باليوم الوطني ينمي **الهوية الوطنية**؛ ومعلم العلوم الذي يحلل فاتورة كهرباء المدرسة لاقتراح ترشيدها ينمي التنمية المستدامة والمسؤولية معاً."],"traps":["الأبعاد المشتركة مسؤولية **كل** المعلمين.","القيم الست تبدأ **بتقوى الله** وتنتهي **بالمسؤولية**."],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار الثامن (مؤشر 8.4)","aka":["الأبعاد المشتركة","القيم الست"]},"ar.l14.expect":{"k":"مؤشر 9.1","t":["High Expectations — Pygmalion Effect","التوقعات العالية وأثر بجماليون"],"body":["في دراسة روزنثال وجاكوبسون (1968) أُخبر معلمون أن طلاباً اختيروا عشوائياً «سيزدهرون»، فتقدم هؤلاء فعلاً أكثر من غيرهم؛ لأن المعلم يعامل من يتوقع منه الكثير بطريقة مختلفة: ينتظره أكثر، ويكلفه بمهام أصعب، ويعطيه تغذية راجعة أدق. هذه **النبوءة التي تحقق ذاتها**."],"pts":["التوقع العالي = إيمان بقدرة **كل** طالب + مهمة تتحداه + دعم حتى يحققها.","التوقع المثالي غير الواقعي يُحبط ويقلل الدافعية.","قارن الطالب **بأدائه السابق** لا بأقرانه.","الدافعية **الداخلية** أقوى وأبقى من الخارجية، والإفراط في المكافآت المادية قد يضعفها.","لإثارة الدافعية: ربط الدرس بحياة الطالب، و**أهداف قصيرة قابلة للتحقيق**، وتنويع الأنشطة، و**تغذية راجعة فورية وصفية**، ومهام فيها تحدٍّ مناسب.","مؤشرات الدافعية: يعمل بجد ولو بلا درجات، ويختار المهام الصعبة، و**يستثمر أخطاءه**، ويثابر؛ والمعلم يجمع **التحدي والدعم**."],"traps":["التوقعات العالية تعكس **الإيمان بقدرة الطلاب**، لا رغبة المعلم في التنافس.","الأثر يعمل في الاتجاهين: التوقع **المنخفض** يخفض التحصيل أيضاً."],"src":"روزنثال وجاكوبسون (1968)؛ المعايير التربوية العامة، مؤشر 9.1","aka":["أثر بجماليون","التوقعات العالية"]},"ar.l14.attrib":{"k":"الدافعية","t":["Attribution — Weiner; Self-Efficacy — Bandura","العزو والكفاءة الذاتية"],"body":["يصنف واينر أسباب النجاح والفشل بثلاثة أبعاد: داخلي أو خارجي، ثابت أو متغير، قابل للضبط أو غير قابل. وإذا تكرر الفشل ونُسب إلى سبب ثابت خارج السيطرة قد يصل الطالب إلى **العجز المتعلم** (سليجمان). أما **الكفاءة الذاتية** (باندورا) فاعتقاد الطالب بقدرته على مهمة محددة."],"pts":["**الجهد**: داخلي متغير قابل للضبط ← أفضل عزو لأنه يدفع إلى المثابرة.","**القدرة**: داخلية ثابتة ← عزو الفشل إليها يولد الإحباط.","مصادر الكفاءة الذاتية من الأقوى: **خبرات الإتقان** ← رؤية نجاح الأقران ← الإقناع اللفظي ← الحالة الانفعالية.","العلاج: مهام متدرجة ونجاح مبكر، وربط النجاح بالجهد والاستراتيجية.","**تقدير الذات** يتراجع عند متدني التحصيل؛ يُرفع بتحديد **جوانب القوة** وتعزيزها ومهام ينجحون فيها، لا بخفض المطلوب.","الطالب الذي يتجنب مهمة بحجة ضعفه السابق فيها يعاني **إحباطاً**."],"ex":["طالبة تقول «أنا غبية في العلوم». تعيد المعلمة توجيه العزو: «أخطاؤك في سؤالي الحسابات، وهذه مهارة تتحسن بالتدريب؛ لنضع خطة أسبوع»."],"traps":["أقوى مصادر الكفاءة الذاتية **خبرات الإتقان** لا الإقناع اللفظي.","العزو لواينر، والعجز المتعلم لسليجمان."],"src":"واينر، نظرية العزو؛ باندورا، الكفاءة الذاتية؛ سليجمان، العجز المتعلم","aka":["نظرية العزو","العزو","العجز المتعلم","الكفاءة الذاتية"]},"ar.l14.kounin":{"k":"إدارة الصف","t":["Kounin's Classroom Management","مفاهيم كونين في إدارة الصف"],"body":["حلل جاكوب كونين تسجيلات حصص كثيرة، فوجد أن الصفوف المنضبطة لا يميزها أسلوب العقاب، بل إدارة سير الدرس التي تمنع المشكلة قبل أن تبدأ وتبقي الطلاب منشغلين."],"pts":["**اليقظة**: وعي المعلم بكل ما يجري وإشعار الطلاب بذلك، فيتدخل مبكراً.","**التداخل**: معالجة أمرين في وقت واحد دون توقف الدرس.","**الزخم والسلاسة**: إيقاع مناسب وانتقالات بلا توقف أو قفز.","**تنبيه المجموعة**: إبقاء الجميع مستعدين (السؤال قبل تحديد المجيب).","**أثر الموجة**: معالجة سلوك طالب تؤثر في بقية الصف."],"traps":["**التداخل** معالجة أمرين معاً، و**اليقظة** الوعي بكل ما يجري."],"src":"كونين، الانضباط وإدارة الجماعة في الصف","aka":["كونين","اليقظة","التداخل","أثر الموجة"],"ex":["معلم يشرح ويلاحظ طالبين يتهامسان في آخر الصف، فيتحرك نحوهما ويضع يده على طاولتهما دون أن يتوقف عن الشرح: توقف الهمس ولم ينقطع الدرس (يقظة وتداخل)."]},"ar.l14.canter":{"k":"إدارة الصف","t":["Assertive Discipline — Canter","الانضباط الحازم (كانتر)"],"body":["بنى لي ومارلين كانتر نموذجهما على مبدأ: للمعلم حق أن يعلّم، ولكل طالب حق أن يتعلم في صف آمن هادئ. ويميزان ثلاثة أساليب استجابة: **غير الحازم** (متردد لا يتابع)، و**العدائي** (يهدد ويهين)، و**الحازم** (واضح هادئ ثابت)."],"pts":["خطة الانضباط: **قواعد** قليلة واضحة، و**تقدير إيجابي** لمن يلتزم، و**عواقب** متدرجة معلنة مسبقاً.","تُطبق العاقبة بهدوء في كل مرة، بلا تفاوض لحظة المخالفة.","التقدير الإيجابي أساس الخطة، لا العقوبة."],"ex":["معلم يعلن في أول يوم عواقب متدرجة (تنبيه أول، فتنبيه ثانٍ، فتدوين وإشعار ولي الأمر)، ويرسل رسائل شكر أسبوعية لأولياء أمور الملتزمين، وحين يخالف طالب يقول بهدوء: «هذا التنبيه الأول» ويكمل."],"traps":["الحازم **ليس** العدائي؛ الصراخ والتهديد أسلوب عدائي."],"src":"كانتر، الانضباط الحازم","aka":["كانتر","الانضباط الحازم"]},"ar.l14.reinf":{"k":"تعديل السلوك","t":["Reinforcement & Punishment","التعزيز والعقاب"],"body":["يعرّف برنامج تعزيز السلوك الإيجابي 1445 التعزيز بأنه تقديم مثير إيجابي محبب، أو إزالة مثير سلبي مؤلم، بعد السلوك المرغوب **مباشرة**، مما يزيد احتمال تكراره. ويضرب مثلاً للتعزيز السلبي بطالب يحضّر دروسه ليتجنب توبيخ المعلم."],"pts":["أنواع المعززات في البرنامج: غذائية، و**اجتماعية** (أسهلها وأكثرها تأثيراً)، ومادية، ونشاطية، ورمزية.","الترتيب المقترح: الاجتماعية أولاً، فإن لم تُجدِ فالنشاطية، ثم المادية.","عوامل فعالية التعزيز: الفورية، والثبات، والكمية المناسبة، وتجنب الإشباع، والتنويع.","العقاب البدني والنفسي والإهانة ممنوعة في قواعد السلوك والمواظبة 1447."],"traps":["«سالب» تعني **إزالة** لا «سيئ»؛ والتعزيز السالب **يزيد** السلوك.","الإكثار من المعزز نفسه يؤدي إلى **الإشباع** فيفقد أثره."],"src":"برنامج تعزيز السلوك الإيجابي 1445 (مفهوم التعزيز، أنواع المعززات، العوامل المؤثرة)؛ قواعد السلوك والمواظبة 1447، المادة 28","aka":["التعزيز","التعزيز الموجب","التعزيز السالب","العقاب"]},"ar.l14.schedules":{"k":"تعديل السلوك","t":["Schedules of Reinforcement","جداول التعزيز"],"body":["جداول التعزيز قواعد تنظم العلاقة بين السلوك والمعززات: متى أقدم التعزيز ومتى أؤجله؟ والاختيار يتبع مرحلة السلوك: **اكتسابه** أو **المحافظة عليه** (برنامج تعزيز السلوك الإيجابي 1445)."],"pts":["**المستمر (المتواصل)**: في كل مرة يحدث السلوك؛ لمرحلة **الاكتساب**، ومحذوره الإشباع.","**المتقطع**: في بعض المرات؛ **الأكثر فاعلية ومقاومة للانطفاء**، ولا يُستخدم في مرحلة الاكتساب.","**الفترة**: تعزيز أول استجابة بعد مرور زمن ثابت أو متغير.","**النسبة**: تعزيز بعد عدد محدد من الاستجابات، ثابت أو متغير."],"ex":["طفل في الصف الأول يُعزَّز عند كل نطق صحيح للحرف (مستمر)، وبعد أن يتقنه يمدحه المعلم بين حين وآخر دون نمط ثابت (متقطع) فيبقى السلوك."],"traps":["لاكتساب سلوك جديد **المستمر**، وللمحافظة عليه **المتقطع**."],"src":"برنامج تعزيز السلوك الإيجابي 1445 (جداول التعزيز)","aka":["جداول التعزيز","التعزيز المتقطع","التعزيز المتواصل"]},"ar.l14.extinct":{"k":"تعديل السلوك","t":["Extinction, Response Cost & Time-out","الانطفاء وتكلفة الاستجابة والإقصاء"],"body":["ثلاث طرق لإضعاف السلوك غير المرغوب: في **الانطفاء** نوقف التعزيز الذي كان يحصل عليه، وفي **تكلفة الاستجابة** يخسر شيئاً كسبه، وفي **الإقصاء** يُبعد مؤقتاً عن الموقف المعزز."],"pts":["الانطفاء (التجاهل المقصود) يُقرن **بالتعزيز التفاضلي** للسلوك البديل، وقد يزيد السلوك مؤقتاً قبل أن يتلاشى.","تكلفة الاستجابة والإقصاء كلاهما **عقاب سالب**.","تمنع قواعد السلوك والمواظبة 1447 **إقصاء الطالب خارج الصف الدراسي**."],"ex":["طالب يصيح «أنا أعرف!» دون رفع يد؛ يتجاهله المعلم ويختار من رفع يده ويشكره. بعد أيام قلّ الصياح: انطفاء مع تعزيز تفاضلي."],"traps":["التجاهل **انطفاء** لا عقاب.","إخراج الطالب من الفصل عقاباً ممارسة **ممنوعة**."],"src":"قواعد السلوك والمواظبة 1447، المادة 28 (البند 29)؛ مراجع تعديل السلوك","aka":["الانطفاء","تكلفة الاستجابة","الإقصاء"]},"ar.l14.premack":{"k":"تعديل السلوك","t":["Premack, Token Economy, Shaping & Modeling","بريماك والاقتصاد الرمزي والتشكيل والنمذجة"],"body":["من أساليب تعزيز السلوك في برنامج تعزيز السلوك الإيجابي 1445: **مبدأ بريماك** (نشاط محبب يُشترط بإنهاء نشاط أقل حباً)، و**الاقتصاد الرمزي** (رموز تُجمع ثم تُستبدل)، و**النمذجة**، و**التشكيل**، و**التسلسل**."],"pts":["الاقتصاد الرمزي يناسب **الابتدائية**، والمعززات الاجتماعية أكثر فاعلية في المتوسطة والثانوية؛ ويُحدد مسبقاً موعد الاستبدال وعدد الرموز.","**التشكيل**: تعزيز التقريبات المتتابعة نحو السلوك النهائي (تدرج في الاستجابة).","**التسلسل**: تجزئة المهمة إلى حلقات متسلسلة وتعزيز كل حلقة.","**النمذجة**: حية، ومصورة، وخيالية (القصص)."],"ex":["طالب لا يكتب إلا كلمة في التعبير؛ يعزز المعلم جملة، ثم جملتين، ثم فقرة قصيرة حتى يصل إلى الفقرة الكاملة: تشكيل."],"traps":["بريماك نشاط **محبب** مشروط بنشاط **أقل حباً**، وليس مكافأة مادية.","التشكيل تدرج في **الاستجابة**، والسحب التدريجي تدرج في **المساعدة**."],"src":"برنامج تعزيز السلوك الإيجابي 1445 (أساليب تعزيز السلوك والخطوات الإجرائية)","aka":["مبدأ بريماك","الاقتصاد الرمزي","التشكيل","النمذجة"]},"ar.l14.rules1447":{"k":"تنظيم رسمي","t":["Student Behavior & Attendance Rules 1447","قواعد السلوك والمواظبة 1447: دور المعلم"],"body":["قواعد السلوك والمواظبة لطلبة التعليم العام (الإصدار الخامس 1447هـ) تخصص للسلوك 100 درجة من الثالث الابتدائي إلى الثالث الثانوي: **80** للسلوك الإيجابي يُعد كل طالب مستحقاً لها تلقائياً بداية كل فصل وتُحسم عند المخالفة مع فرص للتعويض، و**20** للسلوك المتميز. ومسمياتها الحالية: الموجه الطلابي ولجنة التوجيه الطلابي."],"pts":["من دور المعلم: **تمثيل القدوة الحسنة** في القول والفعل، وتعزيز الانضباط الذاتي، والمساهمة في توضيح القواعد.","يباشر **الإجراءات الثلاثة الأولى** في مشكلات الدرجة الأولى، ويحيل من لم يستجب إلى الإدارة.","في الابتدائية: تنبيه شفهي أول ← تنبيه ثانٍ مع حصر أسباب السلوك ← تدوين المشكلة وتوقيع الطالب وإشعار ولي الأمر هاتفياً وحسم درجة من الإدارة مع فرص التعويض، ثم التحويل إلى الموجه الطلابي.","يرصد الغياب في كل حصة، ويرصد مشكلات الدرجة الثانية فأعلى التي باشرها ويسلم الأسماء للإدارة.","ممنوع: الإيذاء الجسدي أو النفسي، والحرمان من الإفطار، و**نسخ الواجب عدة مرات عقاباً**، والسخرية من شخصية الطالب، و**إقصاؤه خارج الصف**.","تدرج في الإجراءات وتعزيز للانضباط الذاتي، ودرجات للمخالفات، وإحالة المخالفات المتكررة (الفصل، الفناء، الحافلة) إلى **وكيل شؤون الطلاب**، و**لجنة التوجيه والإرشاد** (لجنة التوجيه الطلابي حالياً)."],"traps":["المعلم يباشر **ثلاثة** إجراءات فقط في الدرجة الأولى.","المسمى الحالي **الموجه الطلابي** (المرشد الطلابي سابقاً)."],"src":"قواعد السلوك والمواظبة لطلبة التعليم العام، الإصدار الخامس 1447هـ: المادة 5، ودور المعلم، والمادة 6، والمادة 28","aka":["قواعد السلوك والمواظبة","لائحة السلوك والمواظبة"]},"ar.l14.questions":{"k":"مؤشر 9.4","t":["Questioning, Wait Time & Probing","الأسئلة الصفية وزمن الانتظار والسبر"],"body":["السؤال أكثر ما يفعله المعلم في الحصة. وجدت ماري بد رو أن المعلمين ينتظرون عادة أقل من ثانية بعد السؤال، وأن رفع الانتظار إلى 3–5 ثوانٍ يطيل الإجابات ويحسنها ويزيد مشاركة الأقل جرأة."],"pts":["اطرح السؤال **ثم** اختر المجيب ليبقى الجميع منتبهاً.","زمن انتظار **بعد السؤال**، وآخر **بعد إجابة الطالب** قبل التعليق.","السبر: **توضيحي** (وضّح أكثر)، و**تبريري** (لماذا؟)، و**مشجع** (أسئلة تقود من الخطأ إلى الصواب)، و**محوّل** (إلى طالب آخر).","إجابة ناقصة ← سبر توضيحي؛ خاطئة ← سبر مشجع؛ لا إجابة ← إعادة صياغة."],"ex":["طالبة تقول إن الليل والنهار يحدثان بدوران الشمس حول الأرض؛ تسألها المعلمة: «ماذا تفعل الأرض حول نفسها في يوم كامل؟» فتصل إلى دوران الأرض حول محورها: سبر مشجع."],"traps":["بعد الإجابة الخاطئة **سبر مشجع**، لا تصحيح فوري ولا نقل السؤال مباشرة لغيرها."],"src":"رو، زمن الانتظار؛ المعايير التربوية العامة، مؤشر 9.4","aka":["زمن الانتظار","الأسئلة السابرة","السبر المشجع"]},"ar.l15.terms":{"k":"مفاهيم التقويم","t":["Measurement, Evaluation & Assessment","القياس والتقييم والتقويم"],"body":["**القياس** وصف كمي بالأرقام دون حكم، و**التقييم** حكم على قيمة الأداء في ضوء محك، و**التقويم** حكم يتبعه تعديل وعلاج. وتعرّف لائحة تقويم الطالب 2025 التقويم بأنه «عملية منهجية منظمة لجمع المعلومات وتحليلها واستخلاص نتائجها وإصدار أحكام وبناء خطط علاجية وتطويرية في ضوئها»."],"pts":["الترتيب: قياس ← تقييم ← تقويم.","**الاختبار** أداة قياس، وليس نوعاً من التقويم.","**المقنن**: يعده متخصصون بظروف وتعليمات موحدة ومعايير لتفسير الدرجات.","من خصائص التقويم الصفي الفعال في دليل الاختبارات 2025: الموضوعية، والصدق، والثبات، والشمولية، والتنوع، والتمييز، والاستمرارية."],"traps":["الحكم مع علاج = **تقويم** لا تقييم.","اختبار المعلم الجيد **ليس مقنناً** ما لم يُعد بظروف موحدة ومعايير."],"src":"لائحة تقويم الطالب في التعليم العام 2025، المادة 1؛ دليل الاختبارات 2025 (خصائص التقويم الصفي الفعال)","aka":["القياس","التقييم","التقويم"]},"ar.l15.types":{"k":"أنواع التقويم","t":["Diagnostic, Formative & Summative","القبلي والتكويني والختامي"],"body":["تعرّف لائحة تقويم الطالب 2025 الأنواع الثلاثة تعريفاً رسمياً، وتنص في مرتكزاتها على تعزيز **التقويم من أجل التعلم** وتشجيع **التقويم الذاتي**."],"pts":["**القبلي (ويسمى التشخيصي)**: في بداية العام أو الفترة أو المقرر أو الوحدة أو الدرس، للوقوف على استعداد الطالب ومعارفه ومهاراته السابقة.","**التكويني**: عمليات مستمرة خلال الفترة أو العام لتجويد التعلم وبنائه؛ غرضه تحسين التعلم وتعديل التدريس.","**الختامي**: في ختام فترات التعلم لإصدار الحكم على مستوى الطالب.","في دليل الاختبارات 2025: دور المعلم في القبلي **تشخيص**، وفي التكويني **دعم وتيسير** والطالب فيه **تفاعلي**، وفي الختامي **تقييم**.","**التتبعي** بعد التقويم النهائي بفترة لمعرفة بقاء أثر التعلم، و**الانتقائي** لاختيار الطلاب لبرنامج أو مسار؛ وبحسب **الجهة المقوّمة**: **داخلي** (المدرسة)، **خارجي** (الوزارة أو الهيئة)، **متعدد الأطراف**.","**تقويم التعلم** = ختامي، **التقويم من أجل التعلم** = تكويني يقدم أدلة للمعلم والمتعلم، **التقويم كتعلم** = يراقب الطالب تعلمه بنفسه؛ والفائدة الأساسية للتكويني **مراقبة تقدم الطلاب وفاعلية تدريسه وتعديله**."],"ex":["بطاقة خروج تكشف أن نصف الصف أخطأ في وحدة القياس، فيبدأ المعلم الحصة التالية بمراجعة قصيرة: تقويم **تكويني** لأنه عدّل التدريس."],"traps":["«أثناء التدريس» و«تغذية راجعة» و«تعديل» تدل على **التكويني**."],"src":"لائحة تقويم الطالب في التعليم العام 2025، المادتان 1 و3؛ دليل الاختبارات 2025 (أنواع التقويم التربوي)","aka":["التقويم القبلي","التقويم التكويني","التقويم الختامي","التقويم التشخيصي"]},"ar.l15.ref":{"k":"أنواع التقويم","t":["Criterion- vs Norm-Referenced","محكي المرجع ومعياري المرجع"],"body":["الدرجة لا معنى لها حتى نقارنها بشيء. وتعرّف لائحة تقويم الطالب 2025 المحكية بأنها مقارنة أداء الطالب **بمحك خارجي محدد مسبقاً** دون النظر إلى أقرانه، والمعيارية بأنها المقارنة بين أدائه و**أداء أقرانه**."],"pts":["المحكي يجيب: هل أتقن؟ (رخصة القيادة، مستويات الأداء للصفين الأول والثاني).","المعياري يجيب: ما ترتيبه؟ (الانتقاء والمفاضلة، الرتب المئينية، الدرجات المعيارية).","ذاتي المرجع يجيب: هل تحسن عن نفسه؟ (قبلي وبعدي).","دليل الاختبارات 2025: المعياري يميز بين مستويات الطلاب وفق منحنى التوزيع الاعتدالي.","نتائج المحكي قائمة بالأهداف المتحققة، ونتائج المعياري رتب مئينية ودرجات معيارية؛ والمعياري للانتقاء والتصفية والمفاضلة.","**التقويم الذاتي** يشرك الطالب في وضع المحكات والحكم على عمله، و**تقويم الأقران** يحكم فيه الطلاب على أعمال بعضهم بمحكات معدة مسبقاً."],"traps":["«زملائه» أو «ترتيبه» = **معياري**؛ «أتقن/لم يتقن» = **محكي**."],"src":"لائحة تقويم الطالب في التعليم العام 2025، المادة 1؛ دليل الاختبارات 2025 (أساليب تفسير النتائج)","aka":["محكي المرجع","معياري المرجع","ذاتي المرجع"]},"ar.l15.authentic":{"k":"التقويم البديل","t":["Authentic (Alternative) Assessment","التقويم البديل (الأصيل)"],"body":["يعرّفه دليل الاختبارات 2025 بأنه نهج يقيس التعلم بطرق غير تقليدية كالمشاريع والاختبارات العملية، ويقيس استخدام الطالب للمعرفة في حياته ومهارات كالعمل الجماعي وتنظيم الوقت، ويتطلب **الدمج** بينه وبين التقويم التقليدي للوصول إلى حكم دقيق."],"pts":["**تقويم الأداء**: مهمة فعلية (تجربة، عرض، رسالة حقيقية).","**قائمة الشطب**: وجود السلوك أو غيابه دون تدريج.","**سلم التقدير**: عددي (1–5) أو لفظي (دائماً… نادراً).","**السجل القصصي** يكتبه المعلم عن سلوك محدد كما حدث، و**سجل سير التعلم** يكتبه الطالب.","يُسمى **التقويم البديل / الأصيل / الواقعي**؛ ومن شروطه: **العدالة** (فرص متساوية ومحكات معلنة مسبقاً) والتعدد في الأدوات؛ و**تقويم الأداء** مثل كتابة سيرة ذاتية وطلب توظيف حقيقي."],"traps":["الاختبار الكتابي **لا يقيس** المهارة العملية؛ الوضوء والتجربة بالملاحظة وقائمة الشطب."],"src":"دليل الاختبارات: الأسس الفنية والعمليات الإجرائية 2025 (التقويم البديل)","aka":["التقويم البديل","التقويم الأصيل","قائمة الشطب","سلم التقدير"]},"ar.l15.rubric":{"k":"أدوات التقويم","t":["Rubrics","سلم التقدير الوصفي (الروبرك)"],"body":["جدول يضع **معايير** الأداء في جانب و**مستويات** الجودة في جانب، ويصف كل خلية بعبارة تقول كيف يبدو الأداء في هذا المستوى، مع درجة لكل مستوى. يُعلن قبل المهمة، فيعرف الطلاب المطلوب ويقوّمون أنفسهم به."],"pts":["**التحليلي**: درجة لكل معيار ← تغذية راجعة تفصيلية.","**الكلي**: درجة واحدة لوصف عام ← أسرع وأقل تفصيلاً.","قائمة الشطب «موجود أم لا»، وسلم التقدير «بأي درجة»، والروبرك «كيف يبدو كل مستوى»."],"ex":["معيار «تنظيم الفقرة»: 4 = جملة مفتاحية وثلاث جمل داعمة مترابطة وخاتمة؛ 3 = جمل داعمة مع ضعف في الربط؛ 2 = جمل غير مرتبة؛ 1 = جمل متفرقة بلا فكرة رئيسة."],"traps":["السلم العددي بلا أوصاف **ليس** روبرك."],"src":"دليل الاختبارات 2025 (أساليب التقويم وأدواته)","aka":["الروبرك","سلم التقدير الوصفي"]},"ar.l15.portfolio":{"k":"أدوات التقويم","t":["Portfolio","ملف الإنجاز"],"body":["جمع منظم وهادف لشواهد تعلم الطالب يبين جهوده وتقدمه، لكل قطعة فيه سبب، ويكتب الطالب تأمله عليها؛ فهدفه الأساسي **التأمل الذاتي** ومتابعة التقدم. وفي الإجراءات التنفيذية للائحة تقويم الطالب يُوثَّق مستوى طالب الصفين الأول والثاني بشواهد في «ملف إنجاز الطالب»."],"pts":["أنواعه: ملف عمل (المسودات)، وملف عرض (أفضل الأعمال)، وملف تقويم (شواهد على معايير).","مكوناته: أعمال مؤرخة، وتأملات الطالب، وتقويم المعلم.","يُقوَّم بروبرك معلن ويُراجع دورياً مع الطالب."],"traps":["هدفه **التأمل ومتابعة التقدم**، لا التخزين والأرشفة."],"src":"الإجراءات التنفيذية للائحة تقويم الطالب، القاعدة الثانية","aka":["ملف الإنجاز","البورتفوليو"]},"ar.l15.objective":{"k":"أنواع الأسئلة","t":["Objective Items & Writing Rules","الأسئلة الموضوعية وقواعد صياغتها"],"body":["لها إجابة واحدة محددة سلفاً فلا تتأثر بذاتية المصحح: الاختيار من متعدد، والصواب والخطأ، والمطابقة، والإكمال. تغطي محتوى واسعاً ويسرع تصحيحها، لكنها عرضة للتخمين وتحتاج وقتاً في الإعداد ولا تقيس التعبير."],"pts":["**الاختيار من متعدد**: مقدمة تحمل المشكلة كاملة، وبدائل متجانسة معقولة متقاربة الطول، وموقع الإجابة متغير، وتجنب «جميع ما سبق» و«لا شيء مما سبق».","**الصواب والخطأ**: فكرة واحدة، بلا كلمات جزم (دائماً، أبداً، جميع) ولا نفي مزدوج.","**المطابقة**: قائمتان متجانستان، والاستجابات **أكثر** من المقدمات.","**الإكمال**: فراغ واحد مهم قرب آخر الجملة، دون نقل حرفي من الكتاب."],"ex":["«كل المعادن تتمدد بالحرارة دائماً» تصبح «يتمدد الحديد عند تسخينه»: حذفنا كلمتي الجزم اللتين تكشفان الإجابة."],"traps":["لتقليل التخمين **نزيد** البدائل الفعالة لا نقللها.","الإجابة القصيرة والمقالي المقيد **ليسا** موضوعيين؛ والإكمال موضوعي."],"src":"دليل الاختبارات 2025 (الاختبارات التحريرية)","aka":["الأسئلة الموضوعية","الاختيار من متعدد"]},"ar.l15.tos":{"k":"بناء الاختبار","t":["Table of Specifications","جدول المواصفات"],"body":["يعرّفه دليل الاختبارات 2025 بأنه مخطط تفصيلي **ثنائي البعد** يربط موضوعات المحتوى بالأهداف، ويبين الوزن النسبي لكل موضوع ولكل مستوى. يُبنى بعد تحديد الأهداف وتحليل المحتوى وقبل كتابة الأسئلة، ووظيفته الأولى **صدق المحتوى**."],"pts":["وزن الموضوع = (عدد أهدافه أو صفحاته أو حصصه ÷ المجموع) × 100.","أسئلة الخلية = العدد الكلي × وزن الموضوع × وزن المستوى.","لا تقل فقرات كل ناتج تعلم عن 3–4 فقرات، وتُرتب بحسب النوع ثم من الأسهل إلى الأصعب.","**مثال**: 50 سؤالاً لثلاث وحدات حصصها 4 و8 و8 (من 20) ← 10 و20 و20 سؤالاً؛ وبأوزان مستويات 20% و40% و40% تصبح الوحدة الأولى 2 و4 و4، والثانية والثالثة 4 و8 و8 لكل منهما (المجموع 50).","اختبار أسئلته متنوعة لكنه **يركز على موضوعات دون أخرى** ← الحل جدول مواصفات؛ ويتحقق صدق المحتوى بالجدول أو بتحكيم المختصين."],"traps":["يحقق **صدق المحتوى**، لا الثبات ولا الموضوعية.","الخطوة الأولى في بناء الاختبار **تحديد الأهداف** لا الجدول."],"src":"دليل الاختبارات: الأسس الفنية والعمليات الإجرائية 2025 (إعداد جداول المواصفات؛ عدد الفقرات وترتيبها)","aka":["جدول المواصفات"],"ex":["وحدة من 6 حصص من أصل 20 في اختبار من 40 سؤالاً: 6 ÷ 20 × 40 = 12 سؤالاً."]},"ar.l15.reg":{"k":"تنظيم رسمي","t":["Student Assessment Regulation 2025","لائحة تقويم الطالب 2025: الدرجات والنجاح"],"body":["تحكم لائحة تقويم الطالب في التعليم العام (2025) وإجراءاتها التنفيذية ودليل توزيع درجات المواد الدراسية 2025 أرقام التقويم: لكل مادة **100 درجة** في كل فترة."],"pts":["المواد المقوَّمة تكوينياً وختامياً (من الثالث الابتدائي حتى الثانوية): **60** تقويمات تكوينية و**40** اختبار نهاية الفترة.","النجاح: **النهاية الصغرى 50%**، و**النسبة الشرطية 20%** من درجة الاختبار التحريري (نهاية العام في الابتدائية والمتوسطة، ونهاية كل فترة في الثانوية)، ويُشترط في الابتدائية والمتوسطة أداء الاختبار الختامي.","اختبارات تحريرية قصيرة من **20 درجة مرتين على الأقل** في الفترة (دليل التوزيع 2025).","**لا تُطبق النسبة الشرطية على الدور الثاني**؛ وفيه يحتفظ الطالب بـ40 درجة ويُختبر من 60.","يستمر تحسين درجات الأدوات التكوينية حتى بدء اختبارات نهاية الفترة؛ وللسلوك 100 درجة وللمواظبة 100."],"ex":["طالب في الثاني متوسط مجموعه 58، لكن درجته في اختبار نهاية العام التحريري 6 من 40 (أقل من 8 = 20%): لم يحقق النسبة الشرطية فيدخل الدور الثاني، ولا تُطبق عليه النسبة الشرطية هناك."],"traps":["60 تكويني و40 ختامي، لا العكس."],"src":"لائحة تقويم الطالب في التعليم العام 2025 (المواد 1 و5 و6)؛ الإجراءات التنفيذية للائحة تقويم الطالب، القاعدتان 3 و4؛ دليل توزيع درجات المواد الدراسية 2025","aka":["لائحة تقويم الطالب","النسبة الشرطية","النهاية الصغرى"]},"ar.l15.levels":{"k":"تنظيم رسمي","t":["Performance Levels — Grades 1–2","مستويات الأداء للصفين الأول والثاني"],"body":["مستويات الأداء خاصة **بالصفين الأول والثاني الابتدائي** (والصف الأول للتعليم المستمر): يُقوَّم الطالب تكوينياً بمستوى إتقانه لكل معيار من معايير المادة، عدا **الرياضيات واللغة العربية** فتُقوَّمان قبلياً وتكوينياً وختامياً بالدرجات. ومن الصف الثالث فما فوق التقويم بالدرجات."],"pts":["**متفوق** 95% فأكثر من المعايير، و**متقدم** من 85% إلى أقل من 95%، و**متمكن** من 75% إلى أقل من 85% (وكلها بما فيها معايير الحد الأدنى).","**غير مجتاز**: أقل من 75%، أو لم يجتز معياراً أو أكثر من معايير الحد الأدنى.","يدوّن المعلم تقويمه **يومياً** في سجل متابعة تقويم الطالب، ويرصد الخلاصة في النظام الرقمي نهاية الفترة موثقة بشواهد في ملف إنجاز الطالب.","من لم يتقن معياراً من **معايير الحد الأدنى** يُحال إلى لجنة التوجيه الطلابي، ويستمر تقويمه فيه حتى نهاية العام."],"traps":["مستويات الأداء **للصفين الأول والثاني فقط**، وتُستثنى منها الرياضيات واللغة العربية.","أتقن 90% لكنه لم يتقن معياراً من الحد الأدنى = **غير مجتاز**."],"src":"لائحة تقويم الطالب في التعليم العام 2025، المادة 5؛ الإجراءات التنفيذية للائحة تقويم الطالب، القاعدة الثانية","aka":["مستويات الأداء"]},"ar.l16.validity":{"k":"خصائص الاختبار","t":["Validity","الصدق وأنواعه"],"body":["الصدق أن يقيس الاختبار ما وُضع لقياسه فعلاً؛ ويصفه دليل الاختبارات 2025 بأن «يتوافق التقويم مع الأهداف، ويقيس ما هو مخصص لقياسه». وهو أهم خصائص الاختبار، ولا يكون مطلقاً بل لغرض معين وفئة معينة."],"pts":["**المحتوى**: تمثيل الفقرات للمحتوى والأهداف؛ بجدول المواصفات وتحكيم المختصين.","**الظاهري**: مظهر الاختبار يوحي بأنه يقيس ما وُضع له؛ أضعفها.","**المحك**: ارتباط بمحك يُجمع **في الوقت نفسه** (تلازمي) أو **في المستقبل** (تنبؤي).","**البناء**: اتساق الاختبار مع النظرية المفسرة للسمة؛ بالتحليل العاملي.","**الصدق الذاتي** = √معامل الثبات؛ ثبات 0.64 ← صدق ذاتي 0.8.","**الصدق العيني**: كفاية **عدد الأسئلة** لتمثيل المادة، ويقابله **الصدق المنطقي**: تمثيل الموضوعات؛ وثبات 0.81 ← صدق ذاتي 0.9."],"traps":["«بعد سنة» أو «سينجح» = **تنبؤي**؛ «في الوقت نفسه» = **تلازمي**.","صدق المحتوى **بجدول المواصفات**، وصدق البناء **بالتحليل العاملي**."],"src":"دليل الاختبارات 2025 (خصائص التقويم الصفي الفعال)؛ مراجع القياس والتقويم التربوي","aka":["الصدق","صدق المحتوى","صدق المحك","صدق البناء","الصدق الذاتي"]},"ar.l16.reliab":{"k":"خصائص الاختبار","t":["Reliability & Objectivity","الثبات والموضوعية"],"body":["الثبات اتساق النتائج واستقرارها عند تكرار القياس، ويصفه دليل الاختبارات 2025 بأن نتائج التقويم «ثابتة نسبياً عند تكرار العملية في نفس الظروف». و**الموضوعية** عدم تأثر النتائج بذاتية المصحح، وهي شرط للثبات، والثبات شرط ضروري غير كافٍ للصدق."],"pts":["**إعادة التطبيق** (معامل الاستقرار): الاختبار نفسه مرتين؛ عيبه أثر التذكر إذا قصرت المدة.","**الصور المتكافئة** (معامل التكافؤ): نسختان بمواصفات واحدة.","**الاتساق الداخلي**: التجزئة النصفية وكودر ريتشاردسون وكرونباخ من تطبيق واحد.","**ثبات المصححين**: ارتباط درجات مصححين مستقلين؛ مؤشر على الموضوعية في المقالي.","يرتفع بزيادة عدد الفقرات وتباين العينة والصعوبة المتوسطة، وينخفض بالتخمين والغموض.","إجابة صحيحة ثم خاطئة عند الإعادة دون تعلم جديد = **انخفاض ثبات** الفقرة، لا ضعف تمييزها."],"traps":["الميزان الذي يزيد كيلوين دائماً **ثابت غير صادق**.","إجابة صحيحة ثم خاطئة عند الإعادة دون تعلم جديد = ضعف **ثبات** لا تمييز."],"src":"دليل الاختبارات 2025 (خصائص التقويم الصفي الفعال)؛ مراجع القياس والتقويم التربوي","aka":["الثبات","الموضوعية","إعادة التطبيق"]},"ar.l16.coef":{"k":"معاملات الثبات","t":["Reliability Coefficients & SEM","معاملات الثبات والخطأ المعياري"],"body":["معاملات الاتساق الداخلي تُحسب من تطبيق واحد، ولكل منها موضع. والخطأ المعياري للقياس يترجم الثبات إلى وحدات الدرجة: كم تتذبذب درجة الطالب حول درجته الحقيقية."],"pts":["**سبيرمان براون**: ر الكلي = 2ر ÷ (1 + ر). مثال: ارتباط النصفين 0.60 ← 1.20 ÷ 1.60 = **0.75**.","**كودر ريتشاردسون (KR-20)** للفقرات الثنائية: [ك ÷ (ك − 1)] × [1 − (مجموع ص×خ ÷ التباين الكلي)]. مثال: ك = 10، ومجموع ص×خ = 1.8، والتباين 6 ← (10 ÷ 9) × 0.7 ≈ **0.78**.","**كرونباخ ألفا**: الصيغة نفسها بمجموع تباينات الفقرات؛ للمقاييس المتدرجة والمقالية.","**الخطأ المعياري** = الانحراف المعياري × √(1 − الثبات). مثال: انحراف 10 وثبات 0.84 ← 10 × 0.4 = **4**، فدرجة 70 تعني أن الحقيقية غالباً بين 66 و74."],"traps":["**كرونباخ** للمتدرج و**كودر ريتشاردسون** للثنائي، وكلاهما للثبات لا الصدق.","كلما **كبر** الخطأ المعياري **قلّ** الثبات."],"src":"مراجع القياس والتقويم التربوي (معادلات الثبات)","aka":["سبيرمان براون","كودر ريتشاردسون","كرونباخ ألفا","الخطأ المعياري للقياس"]},"ar.l16.difficulty":{"k":"تحليل الفقرات","t":["Item Difficulty Index","معامل الصعوبة"],"body":["في الاستعمال الشائع: نسبة من أجاب صحيحاً إلى عدد المجيبين، ولذلك يسميه بعضهم **معامل السهولة**؛ كلما ارتفع كانت الفقرة أسهل. ودليل الاختبارات 2025 يحسبه بالصيغة نفسها (× 100)، ويعد 100% سهلاً جداً والصفر صعباً جداً، وينصح **بالاحتفاظ بالفقرة إذا وقع معاملها بين 30% و70%**."],"pts":["**الموضوعي**: المصيبون ÷ المجيبين. مثال: 18 من 30 ← **0.60**.","**بالمجموعتين**: (صحيح العليا + صحيح الدنيا) ÷ أفراد المجموعتين. مثال: (7 + 3) ÷ 16 ≈ **0.63**.","**المقالي**: مجموع درجات السؤال ÷ (عدد الطلاب × درجته). مثال: 20 طالباً، والسؤال من 5، والمجموع 60 ← 60 ÷ 100 = **0.60**.","المدى المقبول الشائع في المراجع 0.20–0.80، و0.50 مثالي.","0.90 سهلة جداً، و0.50 متوسطة ومثالية، و0.20 صعبة.","بعض المراجع تسمي نسبة المخطئين «معامل الصعوبة» ونسبة المصيبين «معامل السهولة» ومجموعهما = 1؛ انتبه لتسمية السؤال."],"traps":["المعامل **المرتفع** يعني فقرة **سهلة**، ما لم يُعرَّف بنسبة المخطئين.","فقرة 0.85 خارج المدى الشائع وخارج توصية الدليل: سهلة جداً تُراجع."],"src":"دليل الاختبارات: الأسس الفنية والعمليات الإجرائية 2025 (تحليل فقرات الاختبار: معامل الصعوبة)","aka":["معامل الصعوبة","معامل السهولة"],"ex":["فصل من 25 طالباً أجاب 14 منهم صحيحاً: 14 ÷ 25 = **0.56** (فقرة متوسطة)."]},"ar.l16.discrim":{"k":"تحليل الفقرات","t":["Item Discrimination Index","معامل التمييز"],"body":["يقيس قدرة الفقرة على التفريق بين المتمكنين والأقل تمكناً: نرتب الأوراق تنازلياً، ونأخذ أعلى 27% وأدنى 27%، ونقارن أداء الفئتين. ويحسبه دليل الاختبارات 2025 بالدرجات فيصلح للمقالي، **ويقبله ضمن المدى 0.40 – 1.00**."],"pts":["**الموضوعي**: (صحيح العليا − صحيح الدنيا) ÷ عدد إحدى الفئتين. مثال: 30 طالباً ← 8 في كل فئة؛ 7 و3 ← 4 ÷ 8 = **0.50**.","**صيغة الدليل**: (مجموع درجات العليا − مجموع الدنيا) ÷ (عدد إحدى الفئتين × درجة السؤال). مثال مقالي من 4: (26 − 14) ÷ 32 ≈ **0.38**.","**سالب**: 2 من العليا و5 من الدنيا ← −3 ÷ 8 ≈ **−0.38**؛ تُحذف الفقرة أو تُراجع.","التفسير الشائع: 0.40 فأعلى ممتاز، و0.30–0.39 جيد، و0.20–0.29 يحتاج تعديلاً، وأقل من 0.20 ضعيف."],"traps":["التمييز السالب يعني أن **الأقل تمكناً أجابوا أفضل**؛ غالباً خطأ في المفتاح أو غموض.","فقرة يجيبها الجميع تمييزها **صفر**."],"src":"دليل الاختبارات: الأسس الفنية والعمليات الإجرائية 2025 (معامل تمييز الفقرة)","aka":["معامل التمييز","التمييز السالب"],"ex":["فقرة أجاب عنها 7 من الفئة العليا (8 طلاب) و3 من الدنيا (8 طلاب): الصعوبة (7 + 3) ÷ 16 ≈ 0.63، والتمييز (7 − 3) ÷ 8 = 0.50؛ فقرة متوسطة ممتازة التمييز."]},"ar.l16.distract":{"k":"تحليل الفقرات","t":["Distractor Analysis","تحليل فعالية المشتتات"],"body":["البدائل الخاطئة في الاختيار من متعدد وظيفتها أن تجذب من لم يتقن. فالمشتت الفعال يختاره من الفئة **الدنيا** أكثر من الفئة **العليا**."],"pts":["مثال: المفتاح (ب)، و8 طلاب في كل فئة.","(أ): عليا 0، دنيا 4 ← **فعال**.","(ب) المفتاح: عليا 6، دنيا 2 ← صعوبة 8 ÷ 16 = 0.50، وتمييز 4 ÷ 8 = 0.50.","(ج): عليا 2، دنيا 2 ← **غير مميز** يُراجع؛ (د): لم يختره أحد ← **غير فعال** يُستبدل.","المشتت الذي تختاره العليا أكثر يُراجع؛ قد يكون غامضاً أو إجابة صحيحة ثانية."],"traps":["المشتت الذي **لا يختاره أحد** فاشل لا «سهل»."],"src":"مراجع القياس والتقويم التربوي (تحليل الفقرات)","aka":["المشتت الفعال","فعالية المشتتات"]},"ar.l16.central":{"k":"الإحصاء الوصفي","t":["Measures of Central Tendency","النزعة المركزية"],"body":["تبرز الدرجة التي تتمركز حولها درجات الأفراد (دليل الاختبارات 2025)، ولكل مقياس موضع يكون فيه الأنسب."],"pts":["**المتوسط** = مجموع القيم ÷ عددها؛ يتأثر بالقيم المتطرفة.","**الوسيط**: القيمة الوسطى بعد الترتيب، وفي العدد الزوجي متوسط القيمتين الوسطيين؛ الأنسب للبيانات الملتوية.","**المنوال**: الأكثر تكراراً؛ للبيانات النوعية، وقد يتعدد.","مثال: 4، 6، 6، 7، 9، 10، 14 ← المتوسط 56 ÷ 7 = **8**، والوسيط **7**، والمنوال **6**؛ ولو صارت 14 = 49 لصار المتوسط 91 ÷ 7 = **13** وبقي الوسيط **7**."],"traps":["الوسيط **للملتوي والمتطرف**، والمتوسط **للاعتدالي**، والمنوال **للنوعي**."],"src":"دليل الاختبارات 2025 (مقاييس النزعة المركزية)","aka":["المتوسط الحسابي","الوسيط","المنوال"]},"ar.l16.spread":{"k":"الإحصاء الوصفي","t":["Measures of Dispersion","مقاييس التشتت"],"body":["التشتت انحراف القيم عن المتوسط (دليل الاختبارات 2025): هل الطلاب متقاربون أم متباعدون؟ والصف ذو الانحراف المعياري الأصغر أكثر **تجانساً**."],"pts":["**المدى** = أكبر قيمة − أصغر قيمة؛ أبسطها وأكثرها تأثراً بالمتطرفات.","**التباين** = متوسط مربعات الانحرافات عن المتوسط، و**الانحراف المعياري** جذره.","مثال: 2، 4، 4، 4، 5، 5، 7، 9 ← المتوسط 5، ومربعات الانحرافات 9، 1، 1، 1، 0، 0، 4، 16 (مجموعها 32) ← التباين 32 ÷ 8 = **4** ← الانحراف **2**.","إضافة ثابت لكل الدرجات ترفع المتوسط ولا تغير الانحراف؛ والضرب في ثابت يضرب الاثنين.","الانحراف المعياري **صفر** يعني أن الدرجات كلها متساوية؛ و**الجدول التكراري** يعرض الفئات وتكراراتها والتكرار المتجمع."],"traps":["تباين 81 ← انحراف **9**.","الصف الأكثر تجانساً صاحب الانحراف **الأصغر**."],"src":"دليل الاختبارات 2025 (مقاييس التشتت)","aka":["المدى","التباين","الانحراف المعياري"]},"ar.l16.normal":{"k":"التوزيع","t":["Normal Distribution & Skewness","المنحنى الاعتدالي والالتواء"],"body":["منحنى متماثل جرسي يتساوى فيه المتوسط والوسيط والمنوال. وتطلب لائحة تقويم الطالب 2025 في التقويم التكويني «توزيعاً منطقياً للدرجات»: منحنى يرتفع عند الوسط وينخفض تدريجياً عند الطرفين، لمعالجة تضخم الدرجات."],"pts":["نحو **68%** من الدرجات بين المتوسط ± انحراف، و**95%** ± انحرافين، و**99.7%** ± ثلاثة.","مثال: متوسط 60 وانحراف 8 ← نحو 68% بين 52 و68، ونحو 95% بين 44 و76.","**الالتواء الموجب**: الذيل نحو اليمين، ومعظم الدرجات منخفضة، والمتوسط أكبر من الوسيط ← اختبار **صعب**.","**الالتواء السالب**: الذيل نحو اليسار، ومعظم الدرجات مرتفعة ← اختبار **سهل**.","نحو **34%** بين المتوسط وانحراف واحد فوقه، ونحو **2.5%** فوق انحرافين؛ وفي الالتواء السالب معظم الدرجات مرتفعة (اختبار سهل أو تدريس فعّال)."],"traps":["اسم الالتواء يتبع **اتجاه الذيل** لا مكان التكدس."],"src":"لائحة تقويم الطالب في التعليم العام 2025، المادة 1 (توزيع منطقي للدرجات)؛ مراجع الإحصاء التربوي","aka":["التوزيع الاعتدالي","الالتواء الموجب","الالتواء السالب"]},"ar.l16.z":{"k":"الدرجات المعيارية","t":["Standard Scores (z, T) & Percentile Rank","الدرجات المعيارية والرتبة المئينية"],"body":["الدرجة الخام لا تُقارن عبر اختبارين مختلفين؛ فنحوّلها إلى درجة معيارية تقول: كم انحرافاً معيارياً تبعد عن متوسط مجموعتها؟ أما الرتبة المئينية فتقول: كم في المئة من المجموعة دونها؟"],"pts":["**ز** = (الدرجة − المتوسط) ÷ الانحراف؛ متوسطها 0 وانحرافها 1.","**ت** = 50 + 10 × ز؛ متوسطها 50 وانحرافها 10.","مثال: 80 (متوسط 70، انحراف 5) ← ز = 2 ← ت = 70؛ و54 (متوسط 60، انحراف 4) ← ز = −1.5 ← ت = 35.","**الرتبة المئينية** ≈ (عدد من درجاتهم أقل ÷ العدد الكلي) × 100؛ مثال: 30 من 40 دونه ← **75**."],"traps":["الأفضل نسبياً صاحب **ز الأكبر** لا الدرجة الخام الأكبر.","الرتبة المئينية 90 **ليست** 90% إجابات صحيحة."],"src":"مراجع القياس والتقويم التربوي (الدرجات المعيارية والمئينية)","aka":["الدرجة المعيارية","الدرجة التائية","الرتبة المئينية"],"ex":["طالب حصل على 80 في الرياضيات (المتوسط 70، الانحراف 5) و85 في العلوم (المتوسط 80، الانحراف 10): ز الرياضيات = 2، وز العلوم = 0.5؛ فأداؤه النسبي في الرياضيات أفضل رغم أن درجته الخام أقل."]},"ar.l01.wasat":{"k":"قيمة","t":["Moderation (Wasatiyyah)","الوسطية والاعتدال"],"aka":["الوسطية","الاعتدال","الغلو","التطرف الفكري"],"body":["الوسطية هي الاعتدال والتوازن: لا زيادة تصل إلى الغلو والتشدد، ولا تقصير يصل إلى التفريط والتهاون. وهي ميزان في الفكر والقول والحكم والتعامل.","المعايير المهنية تطلب أن يكون المعلم نموذجاً في الامتثال **بالقيم الإسلامية الوسطية السمحة**، وأن يصمم أنشطة تعزز قيم الوسطية والتسامح والاعتدال ونبذ التطرف. وفي مدونة 1447 تأتي القيم نفسها واجبات: **التحلي بالنزاهة والصدق والأمانة والتسامح والرفق والعدالة**، ويُحظر **اعتناق الأفكار المتطرفة أو نشرها**."],"pts":["**الغلو**: تجاوز الحد المشروع حتى التشدد والتطرف؛ **التفريط**: التهاون والتقصير.","الوسطية تظهر في **أحكام المعلم** (عدل في التقويم والتعامل) لا في كلامه فقط.","قواعد السلوك 1447 تجعل من دور المعلم: **تعزيز التنوع الثقافي والوسطية والاعتدال الفكري، والتأكد من سلامة البيئة التعليمية من الفكر المتطرف**.","من حالات الإبعاد عن التدريس في لائحة الوظائف: **تبني اتجاهات فكرية منحرفة** أثناء أداء الواجب التعليمي بما يؤثر سلباً في الطلاب (المادة 14).","ندوة أو برنامج عن **التطرف الفكري** يُصنَّف قضية مجتمعية يزوّد المعلم طلابه بخبرات عنها."],"ex":["طالب في الثاني المتوسط يصف زميله بالتقصير لأنه لا يلتزم بنافلة معينة. المعلم لا يوبخ ولا يجاري، بل يوضح بهدوء الفرق بين الواجب والمستحب ويذكّر بأدب النصيحة. لا غلو في الحكم على الآخرين، ولا تهوين من القيم."],"traps":["الوسطية ليست «منطقة رمادية» بلا مواقف؛ الثوابت تُعلَّم بوضوح، والاعتدال في الأسلوب والحكم.","خيار «أتجنب الحديث عن القيم حتى لا أُتهم بالتشدد» تفريط لا وسطية."],"src":"المعايير المهنية للمعلمين، هيئة تقويم التعليم والتدريب (المجال الأول: القيم والمسؤوليات المهنية) (1.1)؛ مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ (المادتان 6 و14)؛ قواعد السلوك والمواظبة لطلبة التعليم العام، الإصدار الخامس 1447هـ (دور المعلم)؛ لائحة الوظائف التعليمية بتعديلات 1446هـ (المادة 14)"},"ar.l01.neutral":{"k":"موقف صفي","t":["Professional Neutrality","الحياد في القضايا الخلافية"],"aka":["الحياد المهني","الخلافية","القضايا الخلافية"],"body":["القضايا الخلافية مسائل يختلف فيها أهل العلم أو الناس: فتاوى فقهية مختلف فيها، تيارات دينية، شؤون سياسية. وواجب المعلم ألا يحوّل الحصة إلى منبر لرأيه الشخصي، وأن يحيل الطالب إلى المصادر الموثوقة والجهات المختصة.","مدونة 1447 نصت على ذلك في واجبات المعلم مع طلابه: **تجنب الدخول في نقاشات حول القضايا ذات الحساسية، مثل التيارات الدينية والقضايا الفقهية الخلافية والشؤون السياسية** (المادة 8)، وفي الواجبات العامة: **توخي الموضوعية والعمل بحيادية دون تمييز** (المادة 6)."],"pts":["الحياد في **الخلافيات** لا في **الثوابت** (العقيدة، الولاء للوطن وقيادته، القيم).","الحياد **لا يعني إسكات الطالب**: يستمع إليه باحترام، ويبيّن أن المسألة محل خلاف، ويوجهه إلى المرجع المختص.","تحظر المدونة **معارضة القرارات الصادرة من الجهات العليا والتشكيك في مصداقيتها وإثارة الرأي العام** (المادة 14)."],"ex":["طالب في الثانوية يسأل معلم الرياضيات عن حكم مسألة فقهية مختلف فيها ويطلب رأيه. يجيب المعلم: «هذه مسألة فيها أقوال لأهل العلم، وأحسن من يجيبك عنها معلم العلوم الشرعية أو أهل الفتوى المعتمدون»، ثم يعود إلى هدف الدرس."],"traps":["خيار «يعرض رأيه الشخصي بوضوح ليقنع الطلاب» خاطئ حتى لو كان واثقاً من رأيه.","خيار «يرفض السؤال ويوبخ الطالب» خاطئ أيضاً؛ الصحيح الإحالة الهادئة."],"src":"مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ (المواد 6 و8 و14)"},"ar.l01.dialogue":{"k":"موقف صفي","t":["Culture of Dialogue","ثقافة الحوار مع الطالب المختلف"],"aka":["ثقافة الحوار","الأدلة المنطقية والقدوة العملية"],"body":["المؤشر 1.1 للممارس يطلب أن **يناقش الأفكار المختلفة، ويتقبل اختلاف وجهات نظر الآخرين، ويوظف المواقف الصفية في تنمية ثقافة الحوار**. فالطالب الذي يجادل أو يشكك فرصة تعليمية لا تهديد.","الطريقة: إنصات كامل، ثم سؤال يوضح مقصده، ثم أدلة منطقية وشواهد تناسب عمره، مع قدوة عملية تجعل كلام المعلم مصدَّقاً. والحوار الهادئ يحمي الطالب من البحث عن إجابات في مصادر غير موثوقة."],"pts":["خطوات الحوار: **إنصات ← توضيح ← أدلة وشواهد ← اتفاق على المشترك**.","لا يُغلق باب الحوار، ولا يُحال الطالب إلى «موقع إلكتروني» ليتخلص المعلم من السؤال.","سؤال «الأمة أم الوطن؟» يجاب بحوار يجمع: حب الوطن والانتماء للأمة لا يتعارضان.","مدونة 1447: **احترام التنوع في وجهات النظر** (المادة 10)."],"ex":["طالب يقول في درس التاريخ: «ما فائدة دراسة الماضي؟». يعيد المعلم السؤال للصف، ويجمع إجابات الطلاب، ثم يعرض مثالاً من تأسيس الدولة السعودية يبيّن كيف تشرح الأحداث حاضرنا، فيتحول الاعتراض إلى نقاش يحقق الهدف."],"traps":["«قفل باب الجدال» قمع، و«الإحالة لموقع» تنصّل؛ الصحيح **أدلة منطقية + قدوة**.","الحوار لا يعني التسوية بين الثوابت والآراء؛ الثوابت تُبيَّن بأدلتها."],"src":"المعايير المهنية للمعلمين، هيئة تقويم التعليم والتدريب (المجال الأول: القيم والمسؤوليات المهنية) (1.1، مؤشر الممارس 3)؛ مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ (المادة 10)"},"ar.l01.krathwohl":{"k":"نظرية","t":["Krathwohl's Affective Taxonomy","تصنيف كراثول للمجال الوجداني"],"aka":["كراثول","تمثّل القيمة"],"body":["صنّف ديفيد كراثول (David Krathwohl) مع زملائه أهداف المجال الوجداني (المشاعر والقيم والاتجاهات) في خمسة مستويات متدرجة، كل مستوى يبني على ما قبله، من مجرد الانتباه للقيمة حتى تصبح جزءاً من شخصية المتعلم.","ويفيد المعلم في صياغة أهداف القيم: بدل «أن يحب الطالب وطنه» (لا يُقاس) يكتب سلوكاً يدل على المستوى: يصغي، يشارك، يدافع، يوازن، يتمثّل."],"pts":["1. **الاستقبال (التقبل)**: ينتبه ويصغي باهتمام.","2. **الاستجابة**: يشارك ويتفاعل (يشارك في ندوة).","3. **التقييم (التقدير)**: يقدّر القيمة ويتبناها ويدافع عنها.","4. **التنظيم**: يرتب القيم في منظومة ويوازن بينها عند التعارض.","5. **التمييز بالقيمة (التمثّل)**: تصبح القيمة سمة ثابتة في سلوكه، فيكون قدوة لغيره."],"ex":["في قيمة المحافظة على المرافق: يصغي الطالب للشرح (استقبال)، ثم يشارك في حملة الصف (استجابة)، ثم يدافع عن القيمة أمام زملائه (تقدير)، ثم يوازن بين رغبته في اللعب ونظافة الملعب (تنظيم)، ثم يحافظ على المرافق تلقائياً حتى خارج المدرسة (تمثّل)."],"traps":["الأعلى دائماً **التمثّل** (يكون قدوة لأسرته)، والأدنى **الاستقبال** (يصغي).","لا تخلط كراثول (وجداني) بتصنيف بلوم (معرفي) أو تصنيفات المجال المهاري."],"src":"تصنيف الأهداف التربوية في المجال الوجداني (كراثول وزملاؤه)"},"ar.l01.diversity":{"k":"قيمة","t":["Cultural Diversity & Coexistence","التنوع الثقافي والتعايش"],"aka":["التنوع الثقافي","التعايش","التسامح","التفاعل الإيجابي مع الثقافات الأخرى"],"body":["التنوع الثقافي حقيقة في كثير من الفصول: طلاب من مناطق مختلفة في المملكة، أو من جنسيات وعادات ولغات أخرى. والمعلم يحوّل هذا التنوع إلى مصدر تعلم بالاحترام المتبادل.","مدونة 1447 تجمع الأمرين في فقرة واحدة: ينمي لدى الطلاب الاعتزاز بدينهم والولاء لمليكهم والانتماء لوطنهم، **كما يعزز لديهم أهمية التفاعل الإيجابي مع الثقافات الأخرى** (المادة 8). وتطلب **احترام التنوع في وجهات النظر** (المادة 10)، و**العدالة والإنصاف في معاملة جميع الطلاب دون تمييز** (المادة 8)."],"pts":["الاستشهاد بمثال إيجابي من ثقافة أخرى = **تعزيز احترام الآخرين**، لا تهديد للهوية.","أفضل استراتيجية: **نشاط عملي** يعيشه الطالب (مقابلة، مشروع مشترك، عرض من زميل)، لا ملصقات وقوائم أعياد.","**التسامح**: قبول المخالف والتعامل معه بالحسنى من غير تنازل عن الثوابت؛ و**التعصب** نقيضه.","التعامل مع زميل عمل غير مسلم يكون **وفق مقتضيات مهام العمل** وباحترام؛ والمدونة تطلب التعامل مع الزملاء **دون تمييز** (المادة 13)."],"ex":["في فصل ابتدائي فيه طلاب من خمس جنسيات، تطلب المعلمة من كل طالب أن يحكي كيف يُكرم الضيف في بيته، ثم تجمع القواسم المشتركة على السبورة: الترحيب، والطعام، والبشاشة. نشاط واحد عزز الاحترام وربطه بقيمة الكرم في ثقافتنا."],"traps":["جمع الطلاب المتشابهين ثقافياً وعزلهم خطأ؛ الصحيح إتاحة الحديث والمشاركة للجميع.","احترام الثقافات **لا يعني** التنازل عن الثوابت."],"src":"مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ (المواد 8 و10 و13)؛ المعايير المهنية للمعلمين، هيئة تقويم التعليم والتدريب (المجال الأول: القيم والمسؤوليات المهنية) (1.2)؛ قواعد السلوك والمواظبة لطلبة التعليم العام، الإصدار الخامس 1447هـ (دور المعلم)"},"ar.l01.techcode":{"k":"مدونة 1447","t":["Technology Duties in the 1447 Code","واجبات المعلم التقنية في مدونة 1447"],"aka":["حقوق النشر","نظام مكافحة الجرائم المعلوماتية"],"body":["الباب الرابع من مدونة 1447 خاص بالتقنية: الأجهزة، والإنترنت، والبريد الإلكتروني، ومواقع التواصل الاجتماعي. والفكرة الجامعة أن المعلم يمثل التعليم في كل ما ينشره ويستخدمه.","وتطلب المدونة من المعلم في مواقع التواصل أن يستخدمها بما يعكس السلوك المهني، **مع الاطلاع والتقيد بنظام مكافحة الجرائم المعلوماتية** (المادة 21)."],"pts":["**نظام مكافحة الجرائم المعلوماتية** (1428هـ) يجرّم التنصت والابتزاز والتهديد والتشهير وتغيير معلومات المواقع والدخول غير المشروع؛ وليس من أخلاقيات المراسلة إخفاء الهوية أو التصرف بحرية في وثيقة وصلت بالخطأ أو إرسال رسائل متكررة للتنبيه.","**الإنترنت** (المادة 19): الالتزام **بحقوق الملكية الفكرية** وشروط الترخيص، و**التأكد من سلامة المحتوى المعروض أمام الطلاب**، وإبلاغ الإدارة فوراً عن أي أمر غير معتاد.","**الذكاء الاصطناعي** (المادة 19): الالتزام بسياسات الاستخدام المعتمدة، واحترام خصوصية البيانات، وتجنب الاعتماد الكلي عليه في القرارات الحساسة.","**البريد** (المادة 20): الحكومي للمراسلات الرسمية فقط، ولا يُستخدم البريد الشخصي في المراسلات الرسمية.","**التواصل الاجتماعي** (المادة 21): يتجنب **التصوير أو نشر أي محتوى يتعلق بالمدرسة أو الطلاب أو الزملاء**، ولا يسرّب القرارات والتعاميم، ولا يدير حساباً باسم جهته ما لم يُعيَّن متحدثاً رسمياً.","**الأجهزة** (المادة 18): لا يحمّل برامج أو يستخدم وحدات تخزين خارجية إلا بعد مراجعة الإدارة المختصة، ويحافظ على **كلمة السر**."],"ex":["معلم أعجبه نشاط طلابه فأراد تصويرهم ونشر المقطع في حسابه الشخصي. وفق المادة 21 يمتنع عن ذلك، ويرفع النشاط لإدارة المدرسة لتتولى النشر عبر قنواتها وفق ضوابط الوزارة."],"traps":["«الحساب شخصي فلا شأن للوزارة» خطأ؛ المدونة تنظم سلوك المعلم في حساباته الشخصية.","الذكاء الاصطناعي **مسموح بضوابط**، لا ممنوع مطلقاً ولا مطلق بلا قيود."],"src":"مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ، الباب الرابع (المواد 18–21)"},"ar.l01.privacy":{"k":"مدونة 1447","t":["Student Privacy & Data","خصوصية الطالب ونشر الصور والمعلومات"],"aka":["خصوصية الطالب","مراجعة لوائح الوزارة"],"body":["معلومات الطالب ووثائقه وصوره أمانة. مدونة 1447 تطلب **التعامل مع الوثائق والمعلومات الشخصية للطلاب بسرية تامة وفقاً للأنظمة والتعليمات** (المادة 8)، و**الالتزام بنظام حماية البيانات الشخصية** ولائحته (المادة 6)، وتحظر **إفشاء المعلومات السرية حتى بعد انتهاء الخدمة** (المادة 15).","لذلك فأي طلب للمعلومات من جهة خارجية، أو أي رغبة في نشر صور، تمر بإدارة المدرسة ولوائح الوزارة أولاً."],"pts":["نشر صور الطلاب: **مراجعة لوائح الوزارة أولاً**، ثم إذن ولي الأمر، والنشر عبر القنوات الرسمية.","طلب جهة خارجية (أخصائي، جهة بحثية) معلومات عن طالب: **إدارة المدرسة أولاً** واتباع تعليماتها.","المدونة تطلب **تجنب التصوير أو نشر أي محتوى يتعلق بالمدرسة أو الطلاب** في مواقع التواصل (المادة 21).","لا تُعرض كشوف الدرجات أو ترتيب الطلاب علناً."],"ex":["اتصل شخص يعرّف نفسه بأنه أخصائي ويطلب ملف طالب في الصف السادس. المعلمة تعتذر بلطف وتحيله إلى قائدة المدرسة، ولا ترسل شيئاً حتى لو أكد أن الطالب موافق."],"traps":["**إذن الطالب وحده** لا يكفي لإرسال معلوماته.","الترتيب الصحيح: **لوائح الوزارة** ← إذن ولي الأمر ← النشر الرسمي."],"src":"مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ (المواد 6 و8 و15 و21)"},"ar.l02.mithaq":{"k":"أخلاقيات المهنة","t":["Teaching Ethics Charter","ميثاق أخلاقيات مهنة التعليم"],"aka":["ميثاق أخلاقيات مهنة التعليم","الميثاق","أخلاقيات المهنة","أهداف الميثاق"],"body":["الميثاق وثيقة قيم أصدرتها الوزارة لتعرّف المعلم بالسجايا الحميدة والسلوكيات الفاضلة التي تليق بمهنته، في علاقته بطلابه وزملائه وأسر الطلاب ومجتمعه.","ومكانته ثابتة في ثلاث وثائق رسمية حديثة: المعيار الفرعي 1.3 يطلب أن **يربط المعلم بين ما نصت عليه مواد ميثاق أخلاقيات مهنة التعليم وأدائه المهني مع طلابه وزملائه وأولياء الأمور ومجتمع المدرسة**؛ ولائحة الوظائف التعليمية تجعل **عدم النزاهة أو الإخلال بأمانة التعليم وعدم الالتزام بميثاقها** من حالات الإبعاد (المادة 14/8)؛ ونظام التعليم العام 1448 ينص على [[الالتزام بميثاق أخلاقيات مهنة التعليم|ar.law.ethics]] ضمن واجبات المعلم."],"pts":["الميثاق **وثيقة قيم** (ماذا يليق بالمعلم)، و[[مدونة 1447|ar.l02.code1447]] **قواعد سلوك ملزمة** بواجبات ومحظورات ومساءلة.","الخلاف المهني بين معلمين مرجعه **الميثاق السعودي**، لا المواثيق العالمية ولا الاجتهاد الشخصي.","علاقات المعلم في الميثاق (الطلاب، الزملاء، الأسرة، المجتمع) هي نفسها أبواب الواجبات في مدونة 1447.","**أهداف الميثاق**: تعزيز انتماء المعلم لرسالته ومهنته والارتقاء بها، توعيته بأهميته المهنية، **الإسهام في تعزيز مكانة المعلم العلمية والاجتماعية**، وحفزه على تمثّل قيم مهنته.","**مواده**: التعريفات ← الأهداف ← رسالة التعليم ← المعلم وأداؤه المهني ← المعلم وطلابه ← المعلم والمجتمع ← المعلم والمجتمع المدرسي ← المعلم والأسرة؛ و«المعلم» فيه يشمل المشرفين والمديرين والمرشدين، و«الطالب» طلاب التعليم العام وما في مستواه.","**المجتمع المدرسي**: الثقة المتبادلة والعمل **بروح الفريق** مع الزملاء والإدارة، واحترام [[قواعد السلوك الوظيفي|ar.l02.civilcode]]؛ والالتزام بالأنظمة والمشاركة في نشاطات المدرسة **أركان أساسية** في تحقيق أهدافها."],"ex":["معلمان اختلفا: هل يجوز ذكر أسماء الطلاب الضعاف أمام الصف لتحفيزهم؟ يرجعان إلى الميثاق (صون كرامة الطالب) ومدونة 1447 (السرية والعدالة)، فيتفقان على التغذية الراجعة الفردية."],"traps":["لا تقل «ألغت مدونة 1447 الميثاق»: نص المدونة لم يذكر ذلك، والمعايير ونظام 1448 ولائحة الوظائف ما زالت تسمّي الميثاق.","مرجع الخلاف المهني **الميثاق السعودي** لا «المواثيق العالمية»."],"src":"المعايير المهنية للمعلمين، هيئة تقويم التعليم والتدريب (المجال الأول: القيم والمسؤوليات المهنية) (المعيار 1.3)؛ لائحة الوظائف التعليمية بتعديلات 1446هـ (المادة 14/8)؛ نظام التعليم العام 1448 (المادة 49/3)"},"ar.l02.code1447":{"k":"الأحدث","t":["Code of Conduct for Education Job Holders 1447","مدونة السلوك الوظيفي لشاغلي الوظائف التعليمية 1447"],"aka":["مدونة السلوك الوظيفي","مدونة 1447","المدونة"],"body":["أحدث وثيقة تنظم سلوك المعلم: **مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية**، صدرت عن وزارة التعليم بتاريخ **1447/2/3هـ**، استناداً إلى المادة 32 من لائحة الوظائف التعليمية التي كلفت الوزارة بإصدارها بالاتفاق مع الجهات المختصة.","تتكون من **26 مادة** في ستة أبواب وأحكام ختامية: أحكام تعريفية، ثم واجبات شاغل الوظيفة التعليمية، ثم المحظورات، ثم واجبات استخدام التقنية، ثم تعارض المصالح ومكافحة الفساد، ثم التزامات الوزارة تجاه المعلم."],"pts":["**المنبع الأساس** لسلوك المعلم: الآداب والأخلاق الإسلامية وفق توجيهات ولاة الأمر والأنظمة (المادة 2).","كل معلم **مسؤول عما يصدر عنه**، والمخالفة تعرّضه **للمساءلة والإجراءات التأديبية والجزائية** (المادتان 4 و5).","مع الطلاب (المادة 8): العدالة دون تمييز، دعم ذوي الإعاقة، السرية، **عدم تكليفهم بطلبات مادية** للأنشطة أو الوسائل، الالتزام بلائحة تقويم الطلاب، و**الاطلاع والتقيد بنظام حماية الطفل ونظام الحماية من الإيذاء**.","مع الرؤساء (المادة 11): ينفذ المهام، وإذا كانت مخلة بالأنظمة **يُعلم رئيسه خطياً**.","تسري على جميع شاغلي الوظائف التعليمية بمختلف التصنيفات التعاقدية، وفي **المدارس الأهلية والعالمية** والمدارس والأكاديميات السعودية في الخارج (المادة 25)."],"ex":["طلب مسؤول من معلم تعديل درجات طالب دون سند. المعلم وفق المادة 11 يُعلم رئيسه **كتابياً** أن الطلب مخالف للأنظمة، ولا ينفذه، ولا ينشر الأمر خارج القنوات الرسمية."],"traps":["مدونة 1447 تسري على **المعلم في المدرسة الأهلية** أيضاً.","عند الأمر المخالف: لا تنفيذ صامت ولا رفض شفهي، بل **إعلام الرئيس خطياً**."],"src":"مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ (المواد 1–26)"},"ar.l02.prohibited":{"k":"مدونة 1447","t":["Prohibitions in the 1447 Code","محظورات المعلم وتعارض المصالح"],"aka":["المحظورات","تعارض المصالح","السرية المهنية"],"body":["الباب الثالث من مدونة 1447 يحدد ما لا يجوز للمعلم مطلقاً، ويكمله الباب الخامس عن تعارض المصالح ومكافحة الفساد. هذه «الخطوط الحمراء» المهنية."],"pts":["**عام** (المادة 14): الاستهزاء بشعائر الإسلام أو اعتناق الأفكار المتطرفة أو نشرها؛ إساءة استعمال السلطة؛ استغلال النفوذ؛ الرشوة؛ التزوير؛ **تسريب أسئلة الاختبار ونماذج الإجابة**؛ الاشتغال بالتجارة؛ الجمع بين الوظيفة ومهنة أخرى دون ترخيص؛ الإضراب أو التحريض عليه؛ الشكاوى الجماعية أو الكيدية؛ و**جمع الأموال لأي غرض من الطلبة والموظفين**.","**المعلومات** (المادة 15): إفشاء المعلومات السرية **حتى بعد انتهاء الخدمة**؛ والتصريح للإعلام أو وسائل التواصل في موضوعات تحت الدراسة أو التحقيق دون موافقة خطية مسبقة.","**الهدايا** (المادة 17): قبول هدية أو ميزة تؤثر في نزاهته أو قراراته.","**تعارض المصالح** (المادة 22): الإفصاح خطياً عن أي تعارض قبل اتخاذ القرار، وعدم المشاركة في قرار عقد يكون أحد أقاربه طرفاً فيه.","**مكافحة الفساد** (المادة 23): إبلاغ الرئيس المباشر خطياً عن أي تجاوز، وإبلاغ الجهات المختصة عن الفساد، وإعلام الرئيس فوراً إذا عُرضت عليه رشوة."],"ex":["ولي أمر يقدّم لمعلمة هدية ثمينة قبل اختبارات نهاية الفصل. تعتذر المعلمة بلطف؛ لأن المادة 17 تحظر قبول هدية من شأنها التأثير في نزاهتها أو قراراتها، والتوقيت يجعل التأثير محتملاً."],"traps":["جمع مبلغ من الطلاب «لحفلة الصف» أو «لوسائل تعليمية» **محظور** ولو كان يسيراً (المادتان 8 و14).","سرية المعلومات **لا تنتهي** بانتهاء الخدمة."],"src":"مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ (المواد 14–17 و22–23)"},"ar.l02.civilcode":{"k":"للتمييز","t":["Civil Service Code of Conduct","مدونة السلوك الوظيفي للوظيفة العامة"],"aka":["قواعد السلوك الوظيفي","مدونة الوظيفة العامة"],"body":["قبل مدونة المعلمين توجد **مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة العامة**: إطار عام يجب على **كل موظف عام** التقيد به، تلقي الضوء على المعايير والأخلاق والقيم التي يتحلى بها الموظف أثناء أداء واجباته، وتُعد مخالفتها مخالفة لمقتضى الواجب الوظيفي يترتب عليها إجراءات تأديبية وجزائية.","ونصت مقدمتها على أنها تضمنت المبادئ العامة الشاملة، فقد لا تحيط بمعايير كل جهة، وقد يتطلب الأمر **إضافة معايير وقواعد تتناسب مع الجهات ذات الطابع الوظيفي أو المهني الخاص**. وهذا دور [[مدونة المعلمين 1447|ar.l02.code1447]]: تفصيل خاص بمهنة التعليم."],"pts":["**مدونة الوظيفة العامة**: لكل موظفي الخدمة المدنية، مبادئ عامة.","**مدونة 1447**: لشاغلي الوظائف التعليمية في الحكومي والأهلي والعالمي والمدارس السعودية في الخارج، وفيها ما يخص الطلاب وأولياء الأمور والاختبارات.","**الميثاق**: وثيقة قيم وأخلاقيات لمهنة التعليم.","العلاقة تكاملية: المعلم موظف عام، وصاحب مهنة لها قواعدها الخاصة."],"ex":["معلم يسأل عن استعمال جهاز حاسب المدرسة في عمل خاص خارج الدوام. المبدأ العام في مدونة الوظيفة العامة، ومنصوص أيضاً لشاغلي الوظائف التعليمية في مدونة 1447: يُحظر استخدام ممتلكات الدولة لمنفعة شخصية (المادة 16)، ولا يُستخدم الجهاز إلا لأغراض العمل (المادة 18)."],"traps":["إذا ذُكر في السؤال «طلاب» أو «أولياء أمور» أو «تسريب أسئلة» فالمرجع الأدق **مدونة 1447** الخاصة بالتعليم.","لا تخلط «المدونة» (قواعد ملزمة) بـ«الميثاق» (أخلاقيات المهنة)."],"src":"مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة العامة (المقدمة)؛ مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ"},"ar.l02.jobsreg":{"k":"لائحة","t":["Education Jobs Regulation","لائحة الوظائف التعليمية (بتعديلات 1446)"],"aka":["لائحة الوظائف التعليمية","الرتب الخمس","تحت التجربة سنتين"],"body":["اللائحة تنظم المسار الوظيفي للمعلم: الرتب، والتعيين، والتجربة، والنصاب، والترقية، والنقل، والتكليف، والرواتب، وانتهاء الخدمة. وتقع في **11 باباً و38 مادة**، وحلّت محل لائحة الوظائف التعليمية السابقة الصادرة عام 1401هـ. والنسخة المعتمدة هنا **المتضمنة تعديلات 1446هـ**.","وتذكر مقدمة مدونة 1447 أن اللائحة صادرة بقرار وزير الخدمة المدنية (سابقاً) رقم 2481 وتاريخ 1440/10/9هـ."],"pts":["**الرتب** (المادة 3): معلم خبير، معلم متقدم، معلم ممارس، معلم/مساعد معلم.","**التعيين ابتداءً** على **معلم ممارس** (شهادة جامعية في التخصص مع تحقيق المعايير المهنية) أو **مساعد معلم** (ثانوية ودبلوم لا يقل عن سنة) (المادة 5).","**التجربة سنتان** للمعين ابتداءً، وإن لم تثبت صلاحيته يصدر الوزير قراراً بإنهاء خدمته (المادة 8).","**الإبعاد** عن التدريس (المادة 14) في حالات منها: الإساءة للدين، تبني اتجاهات فكرية منحرفة، الإيذاء الجسدي أو التحرش، المخدرات، و**عدم النزاهة أو الإخلال بأمانة التعليم وعدم الالتزام بميثاقها**.","**التكليف** (المادة 19): القائد والوكيل من رتبة ممارس فأعلى، والمشرف التربوي من متقدم أو خبير؛ ومدة التكليف لا تزيد على أربع سنوات قابلة للتمديد."],"ex":["خريجة بكالوريوس تربوي عُيّنت معلمة ممارسة: تبدأ على الدرجة الثانية من المستوى الأول، وتقضي سنتين تحت التجربة، ثم تحتاج 6 سنوات في الرتبة مع بقية الشروط لتُرقّى إلى معلمة متقدمة."],"traps":["«معلم» رتبة لمن كان يزاول التعليم عند نفاذ اللائحة بمؤهل **دون الجامعي**؛ والتعيين الجديد يبدأ من **ممارس**.","قائد المدرسة يُختار من المكلفين بعمل **وكيل** مضى على تكليفهم 3 سنوات على الأقل (المادة 19/3)."],"src":"لائحة الوظائف التعليمية بتعديلات 1446هـ (المواد 1–38)؛ مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ (المقدمة)"},"ar.l02.license":{"k":"الرخصة","t":["Professional License","الرخصة المهنية"],"aka":["الرخصة المهنية","درجات الاجتياز","صلاحية الرخصة","إلزامية لمزاولة التعليم"],"body":["الرخصة المهنية **وثيقة تصدرها هيئة تقويم التعليم والتدريب** وفق معايير وإجراءات محددة، يكون حاملها مؤهلاً لمزاولة مهنة التعليم بحسب مستويات محددة ومدة زمنية محددة. والوزارة تلتزم بنتائج اختبارات الكفاية المهنية والرخص الصادرة من الهيئة (لائحة الوظائف، المادة 32).","مستوى الرخصة يتحدد بشرطين معاً: **الدرجة الأدنى في كلا الاختبارين** (التربوي العام والتخصصي) و**سنوات الخبرة** المناسبة للمؤهل."],"pts":["**المستويات**: رخصة معلم، معلم ممارس، معلم متقدم، معلم خبير.","**الدرجات** في **كلا** الاختبارين: من 50 إلى 69 ممارس، من 70 إلى 79 متقدم، 80 فأكثر خبير، بشرط سنوات الخبرة.","**خبرة مستوى خبير**: 11 سنة فأكثر للبكالوريوس، و9 للماجستير، و7 للدكتوراه؛ و**متقدم**: من 6 للبكالوريوس، ومن 5 للماجستير، ومن 4 للدكتوراه.","**السريان**: إذا صدرت الرخصة خلال سنة ميلادية من اجتياز الاختبار الأحدث فمدتها **5 سنوات من تاريخ إصدارها**؛ وإن صدرت بعد ذلك تنتهي بعد 5 سنوات من نهاية تلك السنة.","**تعديل 1446** (المادة 34 من اللائحة): الرخصة **شرط للممارسة المهنية**، ويجب الحصول عليها قبل **2026/02/01م**، ويُستثنى من بلغ **الخمسين** قبل هذا التاريخ مع إلحاقه ببرامج تطوير مهني."],"ex":["معلم بكالوريوس خبرته 8 سنوات حصل على 82 في التربوي و85 في التخصصي. درجاته تؤهل لخبير، لكن خبرته (من 6 إلى أقل من 11) تجعل رخصته **متقدم**، ويرقّيها حين يكمل 11 سنة."],"traps":["الرخصة تصدرها **الهيئة** لا الوزارة.","الدرجة وحدها لا تكفي؛ **سنوات الخبرة** جزء من الشرط."],"src":"ضوابط الرخص المهنية للوظائف التعليمية، هيئة تقويم التعليم والتدريب (1445هـ، المواد 1–9)؛ لائحة الوظائف التعليمية بتعديلات 1446هـ (المواد 1 و32 و34)"},"ar.l02.behavior":{"k":"قواعد 1447","t":["Behavior & Attendance Rules 1447","قواعد السلوك والمواظبة (الإصدار الخامس)"],"aka":["قواعد السلوك والمواظبة","لائحة السلوك والمواظبة"],"body":["قواعد السلوك والمواظبة لطلبة التعليم العام في **إصدارها الخامس (1447هـ - 2025م)** هي المرجع الحالي لضبط سلوك الطلاب وحضورهم، وتلغي ما سبقها. هدفها العام: **ضبط السلوك والمواظبة بما يتوافق مع المبادئ الإسلامية والقيم الأخلاقية وثقافة المجتمع**.","وتحدد أدوار كل طرف: قسم التوجيه الطلابي بإدارة التعليم، وإدارة المدرسة، والمعلم، ولجنة التوجيه الطلابي، والموجه الطلابي، والأسرة، والطالب."],"pts":["**النطاق** (المادة 28/2): ما يحدث داخل المدرسة، وفي التعليم الإلكتروني، والبرامج والأنشطة خارج المدرسة، والجهات التي يُرشَّح لها الطالب، وحافلات النقل، و**حدود المدرسة (الشوارع المحاذية لها)** إذا رصدها منسوبو المدرسة أو الجهات المنظمة أو أجهزة التصوير الخاصة بالمدرسة.","تُطبق في مدارس التعليم العام **الحكومي والخاص** ومدارس التعليم المستمر والمدارس السعودية في الخارج (المادة 28/1).","**التدرج**: الإجراء الأول عند أول مخالفة، والتالي عند **تكرار المشكلة نفسها**؛ وإذا ارتكب الطالب أكثر من مشكلة في وقت واحد تُتخذ إجراءات **الأعلى درجة**.","**دور المعلم**: تنفيذ الإجراءات الثلاثة الأولى لمشكلات **الدرجة الأولى** مباشرة وإحالة من لم يتجاوب لإدارة المدرسة، ورصد مشكلات **الدرجة الثانية فأعلى** وتسليمها للإدارة، وتمكين الطالب من **الفرص التعويضية**.","مثال من الدرجة الثالثة (المتوسطة والثانوية): **الشجار أو الاشتراك في مضاربة جماعية**؛ الإجراء الأول دعوة ولي الأمر وتعهد خطي وحسم 3 درجات وتحويل الطالب للموجه الطلابي، والثاني عند التكرار يشمل **نقل الطالب إلى فصل آخر** بقرار لجنة التوجيه الطلابي (المادة 12)."],"ex":["طالب في الثاني المتوسط اشترك في مضاربة جماعية للمرة الأولى. يرصد المعلم المشكلة ويسلمها للإدارة، فتُدعى أسرته، ويوقّع الطالب تعهداً، وتُحسم 3 درجات مع إتاحة فرصة التعويض، ويُحوَّل للموجه الطلابي لدراسة حالته. لا عقاب أمام الزملاء ولا تشهير."],"traps":["القواعد لا تقف عند سور المدرسة: تشمل الحافلة والتعليم الإلكتروني و**الشوارع المحاذية** إذا رُصدت.","قواعد الضبط التي يتفق عليها المعلم مع طلابه يجب أن **تتسق مع قواعد الوزارة**."],"src":"قواعد السلوك والمواظبة لطلبة التعليم العام، الإصدار الخامس 1447هـ (المواد 2 و3 و12 و28)"},"ar.l02.committee":{"k":"قواعد 1447","t":["Student Guidance Committee & Counselor","لجنة التوجيه الطلابي والموجه الطلابي"],"aka":["لجنة التوجيه الطلابي","الموجه الطلابي","المرشد الطلابي","لجنة التوجيه والإرشاد"],"body":["في قواعد 1447 الاسمان المعتمدان: **لجنة التوجيه الطلابي** و**الموجه الطلابي** (يقابلان في المراجع الأقدم «لجنة التوجيه والإرشاد» و«المرشد الطلابي»). اللجنة تدرس المشكلات الأكبر وتوصي وتقرر في حدود صلاحياتها، والموجه يدرس الحالة ويعالجها."],"pts":["من مهام اللجنة: إعداد خطة لتفعيل القواعد، **عقد مجلس أولياء الأمور** للتأكيد على دور الأسرة، استلام شواهد السلوك المتميز وتقدير الدرجة، توفير فرص التعويض، **تصنيف المشكلات التي لم ترد في القواعد** بما لا يتجاوز الدرجة الثالثة، دراسة **الحالات عالية الخطورة** ورفع التوصيات لمدير المدرسة، وإحالة الحالات للجهات المختصة.","**الموجه الطلابي لا يشارك** في رصد درجات السلوك ولا في تنفيذ الإجراءات على المخالف؛ دوره **دراسة الحالة وعلاجها** بعد التنفيذ (المادة 28).","المعلم يحدد أبرز مشكلات الطلبة ويطلب **الدعم والمشورة من لجنة التوجيه الطلابي** عند الحاجة، ويشارك في متابعة الحالات داخل الفصل وتنفيذ توصياتها."],"ex":["معلم لاحظ أن طالباً يتأخر صباحاً ويبدو منهكاً. لا يكتفي بالحسم، بل يحيل الحالة للموجه الطلابي ليدرس السبب مع الأسرة، فيتبين أن الطالب يرعى أخاه المريض ليلاً، فتُبنى له خطة دعم."],"traps":["خيار «الموجه الطلابي يحسم الدرجة» خاطئ؛ الحسم من **إدارة المدرسة**.","الحالات **عالية الخطورة** تتطلب تدخلاً مباشراً وسريعاً من إدارة المدرسة."],"src":"قواعد السلوك والمواظبة لطلبة التعليم العام، الإصدار الخامس 1447هـ (التعريفات، دور لجنة التوجيه الطلابي، دور المعلم، المادتان 5 و28)"},"ar.l02.childprot":{"k":"نظام","t":["Child Protection Law","نظام حماية الطفل ولائحته"],"aka":["نظام حماية الطفل","الإيذاء","الإهمال","1919"],"body":["نظام حماية الطفل صدر بالمرسوم الملكي **م/14 وتاريخ 1436/2/3هـ**، وعُدّل بالمرسوم **م/72 وتاريخ 1443/8/6هـ**، وصدرت له **لائحة تنفيذية جديدة** بديلة عن لائحة 1436. يعرّف **الطفل** بأنه كل إنسان **لم يتجاوز الثامنة عشرة**، ويحميه من **الإيذاء** (كل شكل من أشكال الإساءة للطفل أو استغلاله أو التهديد بذلك: جسدية أو نفسية أو جنسية) ومن **الإهمال** (عدم توفير حاجاته الأساسية أو التقصير فيها: الجسدية والصحية والعاطفية والنفسية والتربوية والتعليمية وغيرها).","ومدونة 1447 تلزم المعلم **بالاطلاع على اللائحة التنفيذية لنظام حماية الطفل ونظام الحماية من الإيذاء والتقيد بهما** في ممارساته التربوية (المادة 8)."],"pts":["**واجب الإبلاغ**: على كل من يطّلع على حالة إيذاء أو إهمال تبليغ الجهات المختصة **فوراً** (النظام، المادة 22).","اللائحة التنفيذية الجديدة (المادة 21): الإبلاغ إلى **مركز البلاغات على الرقم الموحد** مع **المحافظة على سرية هوية المبلّغ**؛ وعلى إدارة المدرسة إذا تعذر حل الحالة أن تبلّغ مركز البلاغات مع تقرير، وتسهّل دخول فريق متعدد التخصصات، وتبلّغ الجهات الأمنية في الحالات الخطيرة.","قواعد السلوك 1447 (المادة 29): الإجراءات **لا تتطلب التدرج**؛ يُبلَّغ مدير المدرسة فوراً وبسرية، وتُحال الحالة للجنة التوجيه الطلابي، ويُدوَّن محضر، ويُبلَّغ مركز بلاغات وزارة الموارد البشرية **(1919)** فوراً إذا تطلبت تدخلاً عاجلاً، وتُرفع لإدارة التعليم إذا كان مصدر الإيذاء أحد منسوبي المدرسة.","من صور الإيذاء أو الإهمال في النظام (المادة 3): **التسبب في انقطاع الطفل عن التعليم**، و**استخدام الكلمات المسيئة التي تحط من كرامته**، و**التمييز ضده**.","ونظام التعليم العام 1448 يضيف [[واجب الإبلاغ على إدارة المؤسسة التعليمية|ar.law.report]]."],"ex":["لاحظت معلمة كدمات متكررة على ذراع طالبة في الصف الرابع، وتهربت الطالبة من السؤال. المعلمة لا تحقق بنفسها ولا تتصل بالأسرة، بل تبلغ قائدة المدرسة فوراً وبسرية، والمدرسة تتولى الإجراءات والإبلاغ وفق المادة 29 من قواعد السلوك."],"traps":["حالات الإيذاء **لا تنتظر التدرج** ولا الصلح الداخلي.","الكلمات المسيئة التي تحط من كرامة الطفل **إيذاء** في نص النظام، لا «أسلوب حازم»."],"src":"نظام حماية الطفل (م/14 لعام 1436، وتعديلات م/72 لعام 1443)؛ اللائحة التنفيذية الجديدة لنظام حماية الطفل (المادة 21)؛ قواعد السلوك والمواظبة لطلبة التعليم العام، الإصدار الخامس 1447هـ (المادة 29)؛ مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ (المادة 8)"},"ar.l02.rifq":{"k":"برنامج وزاري","t":["Rifq Program","برنامج رفق لخفض العنف (1445)"],"aka":["رفق","التنمر","العنف"],"body":["«رفق» برنامج إرشادي وقائي وعلاجي أعدته وزارة التعليم (التوجيه الطلابي) عام 1445هـ لخفض العنف المدرسي بكل أشكاله، طوال العام الدراسي وفي جميع المراحل، بنين وبنات. واسمه مأخوذ من الحديث: «إن الرفق لا يكون في شيء إلا زانه، ولا يُنزع من شيء إلا شانه»، و«الرفق» في البرنامج ضد العنف ومعناه لين الجانب.","يعمل على ثلاثة مستويات: **المدرسة** و**الأسرة** و**الطلبة**، ويرتب العمل في: وقاية، ثم كشف وتعرّف على المؤشرات (المشاهدة الواعية، الملاحظة العلمية، قائمة المؤشرات)، ثم تدخل مبكر، ثم أساليب علاجية للمعتدي والمعتدى عليه، مع نماذج للحصر والمتابعة والإبلاغ لمركز البلاغات."],"pts":["**العنف**: كل سلوك متعمد ينتج عنه أضرار جسدية أو نفسية للآخرين أو تخريب للممتلكات.","**التنمر** خمسة محددات: شكل من أشكال العنف، **متعمد**، بين **أقران** من الفئة العمرية نفسها، مع **اختلاف ميزان القوة**، و**متكرر**.","**المشاجرة الطارئة ليست تنمراً**، لغياب شرط التكرار والاستمرار.","النظريات المفسرة للعنف في البرنامج: البيولوجية، والسلوكية (التعزيز)، و**التعلم بالمشاهدة (النمذجة)**، و**الإحباط - العدوان**، والاجتماعية.","من استراتيجيات الخفض **ضبط المثيرات**: الحد من أسباب العنف في المحيط التربوي والأسري."],"ex":["طالبان في الخامس الابتدائي تشاجرا مرة واحدة على الكرة: مشاجرة طارئة تُعالج بإجراءات السلوك. أما طالب يسخر يومياً من زميل أصغر جسماً ويعزله عن المجموعة منذ أسابيع، فهذا **تنمر** لاكتمال محدداته، ويستدعي خطة علاجية مع الموجه الطلابي وإشراك الأسرة."],"traps":["لا يكفي **التكرار** وحده؛ التنمر يحتاج **تعمداً واختلال قوة بين أقران**.","ولي الأمر الذي يشكو تنمراً: **استماع ثم متابعة مع الموجه الطلابي**، لا تهوين ولا تنصّل."],"src":"برنامج رفق لخفض العنف في مدارس التعليم العام، وزارة التعليم 1445هـ (الملخص، الأهداف، المصطلحات، النظريات المفسرة، أسباب العنف)"},"ar.l03.pd":{"k":"مفهوم","t":["Professional Development","التنمية المهنية للمعلم"],"aka":["التنمية المهنية","التطوير المهني","النمو المهني"],"body":["التنمية المهنية جهد منظم مستمر يرتقي بمعارف المعلم ومهاراته وقيمه حتى ينعكس على تعلم طلابه. وتعرّف لائحة الوظائف التعليمية **التطوير المهني** بأنه **عملية منظمة لتنمية المعارف والمهارات العلمية والتربوية وفق المعايير المهنية**.","وهو اليوم حق وواجب ومعيار ترقية: مدونة 1447 تطلب أن **يحرص المعلم على التطوير المهني المستمر واستخدام أساليب التدريس الفعالة والمبتكرة** (المادة 7)، ونظام التعليم 1448 يجعله [[حقاً وواجباً|ar.law.teacher]]، ولائحة الوظائف تشترط **الحد الأدنى من نقاط التطوير المهني** للترقية والتكليف."],"pts":["مكوناتها في الأدب التربوي: **التدريب المهني** (مهارات) + **التربية المهنية** (معتقدات وقيم) + **المساندة المهنية** (استقرار وظيفي ومناخ داعم).","مبادئها: **عملية مستمرة** لا نتيجة تنتهي بدورة، تُخطط جماعياً، في بيئة مشجعة، ويُقاس **أثرها في تعلم الطلاب**.","أهدافها: مواكبة المستجدات، التعلم مدى الحياة، ترسيخ أخلاقيات المهنة، تحسين تعلم الطلاب.","المعلم يتحمل **مسؤولية نموه الذاتي**، ويدرس مناسبة أي دورة له قبل التسجيل."],"ex":["عُرضت على معلم دورة في تصميم الفيديو التعليمي. قبل التسجيل سأل: هل تعالج احتياجاً في خطتي؟ هل ستغير ممارستي مع طلابي؟ فوجد أن احتياجه الأكبر في التقويم التكويني، فقدّمه في خطته."],"traps":["**تطوير البيئة المادية للصف** ليس هدفاً للتنمية المهنية.","**المساندة** ليست تدريباً؛ هي الاستقرار الوظيفي والمناخ الداعم."],"src":"لائحة الوظائف التعليمية بتعديلات 1446هـ (المادتان 1 و10)؛ مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ (المادة 7)؛ نظام التعليم العام 1448 (المادتان 48 و49)"},"ar.l03.reflect":{"k":"التأمل","t":["Reflective Practice","التأمل الذاتي في التدريس"],"aka":["التأمل الذاتي","التأمل في التدريس","التأمل الناقد","التأمل الذاتي وتقويم الزملاء والخبراء"],"body":["التأمل الذاتي استقصاء منظم وواعٍ في الممارسة: يعود المعلم إلى ما فعله، ويسأل لماذا حدث، وما البديل، ثم يجرب. وارتبط المفهوم بأعمال دونالد شون (Donald Schön) عن «الممارس المتأمل» الذي يتأمل **أثناء الفعل** و**بعد الفعل**.","مؤشر الممارس 2.2 يطلب أن **يحلل ممارساته المهنية تحليلاً نقدياً في ضوء التقويم والتأمل الذاتي ومستوى أداء طلابه**، ومؤشر 3.1 يطلب أن **يمارس التأمل الذاتي للواقع التدريسي لاستكشاف القضايا التربوية التي تمثل مجالاً للبحوث الإجرائية**."],"pts":["**المستويات** كما تُدرَّس للاختبار: **وصفي** (ماذا حدث؟) ← **تفسيري** (تبرير بحل واحد) ← **حواري** (حوار داخلي يختبر عدة حلول وفروض) ← **ناقد** (تأمل جماعي مع الزملاء).","**أدوات فردية**: [[نافذة جوهاري|ar.l03.johari]]، أداة سوات SWOT، بطاقة التأمل، ملف الإنجاز، تصوير الدرس بالفيديو، صحائف التأمل، سلالم التقدير وقوائم الشطب.","**أدوات جماعية**: البحث الإجرائي، ملف الإنجاز الجماعي، مؤتمرات التأمل، مجموعات التركيز، التدريب المعرفي.","يحدث في **التخطيط والتنفيذ والتقويم**، ويعتمد على **الوقت والخبرة**.","مثال التأمل الذاتي في الاختبار: **تصوير جزء من أدائه التدريسي ومراجعته** لاحقاً؛ أما طلب التغذية الراجعة من زميل فتقويم أقران.","أسئلة توجّه تأمل الطالب في تعلمه: ماذا تعلمت؟ كيف أحسّن؟ وليس «كيف أتفوق على زملائي؟» (مقارنة لا تأمل)."],"ex":["بعد حصة مضطربة كتبت المعلمة: «الطالبات تكلمن أثناء العمل الجماعي» (وصفي). ثم: «لأن التعليمات لم تكن واضحة» (تفسيري). ثم سألت نفسها: أهي التعليمات، أم حجم المجموعة، أم نوع المهمة؟ (حواري). ثم عرضت الموقف على زميلاتها في مجتمع التعلم (ناقد)."],"traps":["تصوير الدرس ومراجعته = **تأمل ذاتي**؛ طلب رأي زميل = **تقويم أقران**.","التفسيري **حل واحد**، والحواري **عدة حلول**، والناقد **جماعي**."],"src":"المعايير المهنية للمعلمين، هيئة تقويم التعليم والتدريب (المجال الأول: القيم والمسؤوليات المهنية) (2.2 و3.1)؛ أدبيات الممارس المتأمل (دونالد شون)"},"ar.l03.johari":{"k":"أداة تأمل","t":["Johari Window","نافذة جوهاري"],"aka":["نافذة جوهاري"],"body":["أداة لفهم الذات وعلاقتها بالآخرين، وضعها عالما النفس جوزيف لفت وهارينغتون إنغام (Joseph Luft & Harrington Ingham)، واسمها مركب من اسميهما. تقسم ما يُعرف عن الشخص إلى أربع مناطق بحسب سؤالين: هل أعرفه أنا؟ وهل يعرفه الآخرون؟"],"pts":["**المنطقة العامة (المفتوحة)**: أعرفها ويعرفها غيري.","**المنطقة العمياء**: يعرفها غيري ولا أعرفها، وتُضيَّق **بطلب التغذية الراجعة**.","**المنطقة الخاصة (المخفية)**: أعرفها وأخفيها، وتضيق **بالإفصاح**.","**المنطقة المجهولة**: لا أعرفها ولا يعرفها غيري، وتُكتشف بالتجربة والتأمل.","الهدف المهني: **توسيع المنطقة العامة**."],"ex":["معلم يظن أنه يوزع الأسئلة على الجميع، وبعد زيارة زميل اكتشف أنه يوجه أغلبها للصفوف الأمامية. هذه معلومة كانت في **المنطقة العمياء**، وكشفتها التغذية الراجعة."],"traps":["ما يراه الآخرون ولا تراه = **العمياء** لا الخاصة.","علاج العمياء **التغذية الراجعة**، وعلاج الخاصة **الإفصاح**."],"src":"نافذة جوهاري (لفت وإنغام)"},"ar.l04.plc":{"k":"مجتمعات التعلم","t":["Professional Learning Community","مجتمع التعلم المهني"],"aka":["مجتمع التعلم المهني","مجتمعات التعلم المهنية","مجتمعات التعلم","ثقافة التعاون","الأسئلة والفصول"],"body":["مجتمع التعلم المهني مجموعة من المعلمين داخل المدرسة يعملون معاً بشكل **مخطط ومستمر** لتحسين تعلم الطلاب، فيتعلمون هم أنفسهم أثناء ذلك. وارتبط المفهوم في الأدب التربوي بأعمال ريتشارد دوفور (Richard DuFour) الذي لخّصه في ثلاث أفكار كبرى: ضمان تعلم الطلاب، وثقافة التعاون، والتركيز على النتائج.","وفي الميدان السعودي ينص النموذج الإشرافي في ضوء تمكين المدرسة 1446 من أهدافه على **توفير متطلبات التطوير المهني المستمر الذاتي والتعاوني، وتفعيل مجتمعات التعلم المهنية بأساليب وأدوات وأوعية متنوعة**، ويظهر في نموذج تقييم أداء المعلم ضمن عنصر «التفاعل مع المجتمع المهني»."],"pts":["**المبادئ**: تشارك الرؤية والقيم والأهداف، وثقافة التعاون، والتركيز على تعلم الطلاب، والتركيز على النتائج.","**عملي لا نظري**: يحلل بيانات الطلاب ويقرر ماذا يغير في التدريس.","**التشكيل** حسب **الصف أو التخصص** المشترك.","**أسئلة التحليل** عن **الأسئلة والفصول** (أين أخطأ الطلاب؟ لماذا اختلفت الفصول؟) لا عن الأفراد المتفوقين.","**عوامل النجاح**: قيادة داعمة، وبنية تنظيمية ووقت مخصص، ونظام فاعل للتطبيق.","تحليل نتائج الاختبارات الوطنية لثلاث سنوات يُوظَّف في **تعديل خطط التدريس والأنشطة في ضوء النتائج**؛ ومراجعة الزملاء لأعمال بعضهم تساعد على **حل مشكلات التدريس**."],"ex":["معلمو العلوم في الصف الثاني المتوسط يجتمعون كل أسبوعين. حللوا سؤالاً أخفق فيه أكثر من نصف الطلاب في الفصول الأربعة، فاكتشفوا أن المفهوم يُدرّس بمثال واحد، فاتفقوا على نشاط عملي موحد، وسيقيسون أثره في الاختبار القصير القادم."],"traps":["هدفه تعاون **المعلمين** لتحسين تعلم **الطلاب**، لا تعاون الطلاب ولا تقويم المعلمين.","«يُعنى بالجوانب النظرية» مفهوم خاطئ عنه."],"src":"المعايير المهنية للمعلمين، هيئة تقويم التعليم والتدريب (المجال الأول: القيم والمسؤوليات المهنية) (3.1)؛ النموذج الإشرافي في ضوء تمكين المدرسة 1446 (الأهداف التفصيلية)؛ الدليل الإرشادي لإدارة الأداء الوظيفي 2026؛ أدبيات مجتمعات التعلم المهنية (دوفور)"},"ar.l04.plcforms":{"k":"مجتمعات التعلم","t":["Forms of Collaborative Learning","أوعية مجتمعات التعلم المهنية"],"aka":["أوعية مجتمعات التعلم","أوعية مجتمعات التعلم المهنية","التوأمة المهنية","الشبكات المهنية","التدريب بالأقران"],"body":["«الأوعية» هي القوالب التي يجري فيها تعلم المعلمين معاً. واختيار الوعاء يتبع الهدف: مهارة جديدة؟ مشكلة صفية مشتركة؟ تبادل بين مدرستين؟","وتجمعها قائمة واحدة: التدريب المباشر، ورش العمل وحلقات النقاش، المؤتمرات والندوات، البرامج الأكاديمية، البحوث الإجرائية، التدريب بالأقران، التوأمة المهنية، الشبكات المهنية، مجموعات التخصص."],"pts":["**التدريب المباشر**، و**ورش العمل وحلقات النقاش**، و**المؤتمرات والندوات**، و**البرامج الأكاديمية**.","**البحوث الإجرائية**: وعاء لحل مشكلة مشتركة بمنهجية.","**التدريب بالأقران**: زميل يدرب زميله على مهارة ويتابعه في الصف.","**التوأمة المهنية**: شراكة بين معلمين أو مدرستين لتبادل الخبرات.","**الشبكات المهنية**: روابط معلمين متميزين في مهارة، ينسق المشرف عملهم لدعم أقرانهم."],"ex":["مدرستان متجاورتان: الأولى متميزة في التعلم التعاوني والثانية في توظيف التقنية. اتفقتا على توأمة: زيارات متبادلة شهرية، وورشة مشتركة كل فصل."],"traps":["التوأمة **بين طرفين** (معلمين أو مدرستين)؛ والشبكة **مجموعة أوسع** ينسقها مشرف.","البحوث الإجرائية من أوعية مجتمعات التعلم ومن أدوات التأمل الجماعي معاً."],"src":"أدبيات مجتمعات التعلم المهنية؛ النموذج الإشرافي في ضوء تمكين المدرسة 1446"},"ar.l04.parentcomm":{"k":"أولياء الأمور","t":["Communicating with Parents","التواصل مع أولياء الأمور"],"aka":["التواصل مع أولياء الأمور","شريك الوالدين","اجتماع الأهداف المشتركة"],"body":["العلاقة مع ولي الأمر شراكة في مصلحة الطالب. ومدونة 1447 تحدد قواعدها في المادة 9: **تعزيز التواصل الإيجابي** والاستماع إلى ملاحظاتهم والإجابة عن استفساراتهم في الزيارات المدرسية أو **عبر المنصات الرسمية المعتمدة للتواصل مع ولي الأمر**، والتعامل **باحترام وتقدير** وتقديم المعلومات عن المستوى الأكاديمي والسلوكي **بأسلوب واضح وموضوعي ودون تمييز**، وتجنب ما يثير سوء الفهم أو النزاع، والتعاون في إيجاد الحلول وإرشاد الأسرة إلى الأساليب التربوية."],"pts":["لمناقشة التقدم: **اجتماع للأهداف المشتركة** أفضل من التواقيع ودفاتر المتابعة.","التواصل لا يقتصر على المشكلات: **رسائل إيجابية** ودعوات للفعاليات والتكريم.","مع أسر الطلاب **ذوي الإعاقة**: توجيه وتوعية لتعديل الاتجاهات السلوكية الخاطئة وتوثيق الروابط بين البيت والمدرسة (المادة 9/3).","**السرية**: معلومات الطالب تخصه وأسرته؛ ولا يُتحدث عن طالب أمام غيره.","نموذج تقييم أداء المعلم يخصص **10%** لعنصر **التفاعل مع أولياء الأمور**."],"ex":["معلمة ترسل كل أسبوعين رسالة قصيرة عبر المنصة المعتمدة: إنجاز إيجابي للطالبة، ومهارة تعمل عليها، ونشاط منزلي من خمس دقائق. وحين احتاجت لاحقاً إلى لقاء بسبب تراجع مفاجئ، كانت الثقة قائمة."],"traps":["القناة **الرسمية المعتمدة** مقدمة على الحسابات الشخصية.","مزايا اجتماعات أولياء الأمور **لا تشمل** إشراكهم في **تقويم المعلمين**."],"src":"مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ (المادة 9)؛ الدليل الإرشادي لإدارة الأداء الوظيفي 2026؛ المعايير المهنية للمعلمين، هيئة تقويم التعليم والتدريب (المجال الأول: القيم والمسؤوليات المهنية) (3.2)"},"ar.l04.angry":{"k":"موقف صفي","t":["The Upset Parent","ولي الأمر الغاضب والإنصات الفعّال"],"aka":["الإنصات الفعّال","الإنصات أولاً"],"body":["موقف أساسي في هذا المعيار: ولي أمر يدخل غاضباً. والقاعدة الذهبية: **الإنصات أولاً**. الغاضب لا يسمع حتى يُسمع، فإذا عبّر عن رأيه ومشاعره وفهمه لما حدث، صار مستعداً للنقاش."],"pts":["**الترتيب**: إنصات ← تلخيص ما فهمته منه ← عرض الحقائق بهدوء وموضوعية ← حل مشترك ← متابعة.","غاضب من **مستوى ابنه**: هدوء ومنطق وحياد بالأدلة (أعمال، نتائج)، دون رفع درجات ولا تحويل فوري.","يريد **أخذ ابنه أثناء الحصة**: الاستئذان إجراء إداري ← **إدارة المدرسة**.","يشكو **تنمراً**: **الاستماع له ثم إخباره بمتابعة الأمر مع المرشد الطلابي** (الموجه الطلابي في قواعد 1447) وفق برنامج [[رفق|ar.l02.rifq]]؛ لا تهوين ولا تنصّل.","يسأل عن **صعوبات تعلم**: موعد مع **المختص** في المدرسة؛ التشخيص ليس من صلاحية المعلم."],"ex":["ولي أمر يقول بحدة: «ابني يقول إنك تظلمه في الدرجات!». يدعوه المعلم للجلوس ويقول: «أفهم قلقك، أخبرني ماذا قال لك بالتفصيل»، وبعد أن ينتهي يعرض أوراق الطالب ومعايير التصحيح، ثم يتفقان على خطة مراجعة أسبوعية."],"traps":["شرح وجهة نظرك ومراجعة اللوائح خطوات **صحيحة في توقيت خاطئ** إذا سبقت الإنصات.","رفع الدرجة لإرضاء ولي الأمر إخلال بالعدالة."],"src":"مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ (المادة 9)؛ المعايير المهنية للمعلمين، هيئة تقويم التعليم والتدريب (المجال الأول: القيم والمسؤوليات المهنية) (3.2)"},"ar.l04.family":{"k":"قواعد 1447","t":["The Family's Role","دور الأسرة ومجلس أولياء الأمور"],"aka":["دور الأسرة","مجلس أولياء الأمور","مجالس أولياء الأمور"],"body":["قواعد السلوك والمواظبة 1447 تجعل الأسرة شريكاً بأدوار مكتوبة، لا متلقياً للاستدعاءات. ومن مهام **لجنة التوجيه الطلابي** في المدرسة **عقد مجلس أولياء الأمور للتأكيد على دور الأسرة في تعزيز القيم والسلوك الإيجابي لدى الأبناء**."],"pts":["من أدوار الأسرة: **الاطلاع على جميع أنظمة المدرسة وقواعدها وتعليماتها ومناقشتها مع الأبناء**.","**حضور الاجتماعات ومجالس أولياء الأمور** والفعاليات التثقيفية والتوعوية التي تنفذها المدرسة.","**التواصل الفوري مع المدرسة عند تغيّب الابن** مع توضيح سبب الغياب.","**إخطار المدرسة باحتياجات الابن** والتعاون معها لحل مشكلاته، و**إبلاغ الموجه الطلابي أو الوكيل** عند تعرضه لمشكلات سلوكية.","التزام ولي الأمر بمسؤوليته الكاملة تجاه ابنه وفق القواعد ونظامي **الحماية من الإيذاء وحماية الطفل**."],"ex":["طالب يكرر مخالفة استخدام الجوال. المعلم لا يسرد مخالفاته على والده، بل يعطيه نسخة من قواعد استخدام الأجهزة في المدرسة، ويتفقان على متابعة مشتركة في البيت والمدرسة لأسبوعين."],"traps":["لزيادة تعاون والد الطالب المخالف: **تزويده بالقواعد السلوكية** للمتابعة في البيت، لا المقارنة بإخوته.","النتائج المتدنية **لصف كامل** ← **مجلس أولياء الأمور** (لقاء جماعي)."],"src":"قواعد السلوك والمواظبة لطلبة التعليم العام، الإصدار الخامس 1447هـ (دور الأسرة، دور لجنة التوجيه الطلابي)"},"ar.l04.partnership":{"k":"المجتمع المحلي","t":["Community Partnership","الشراكة المجتمعية"],"aka":["الشراكة المجتمعية","المشاركة المجتمعية","مقومات الشراكة"],"body":["الشراكة المجتمعية إتاحة الفرصة لأولياء الأمور ومؤسسات المجتمع للإسهام **بالفكر والمشورة والموارد** في تطوير التعليم، في علاقة **تبادلية**: المدرسة تأخذ من مجتمعها وتعطيه.","ومن الأطر المشهورة في هذا الباب نموذج جويس إبستين (Joyce Epstein) لأنماط مشاركة الأسرة والمجتمع الستة: الوالدية، والتواصل، والتطوع، والتعلم في المنزل، والمشاركة في اتخاذ القرار، والتعاون مع المجتمع."],"pts":["**المقومات**: احترام متبادل، وتقدير جهود المعلمين، ومسؤولية مشتركة بين المدرسة والأسرة والقطاعين العام والخاص والجامعات.","**النتائج**: اتجاهات أفضل نحو المدرسة، وتحصيل أعلى، وتسرب أقل، ودعم أكبر من الأسر، ومعنويات أعلى للمعلمين.","**المجتمع المحيط بالمدرسة**: جهات حكومية وأهلية وأفراد يقدمون دعماً مادياً أو عينياً أو بشرياً.","مؤشر الممارس 3.3: **يوضح جوانب علاقة المدرسة مع المجتمع المحلي وأهميتها، ويشارك بإيجابية في المناسبات والفعاليات الاجتماعية التي تعززها**.","من صور التفاعل مع المؤسسات: تنمية الوعي بخدمة البيئة، التدريب في مراكز محو الأمية، دعم نادي الحي، دروس التقوية.","معلم يتتبع الفعاليات المحلية والدولية ويحث أولياء الأمور على المشاركة بمنجزات أبنائهم: يعكس **رغبته في دعم طلابه للافتخار بمنجزاتهم**."],"ex":["مركز صحي قريب يقدم للمدرسة محاضرة عن التغذية، والمدرسة تفتح ساحتها لحملة توعوية للحي. علاقة تبادلية واضحة، وكلاهما يخدم الصحة المدرسية."],"traps":["الشراكة **تبادلية**؛ الخيار الذي «يأخذ دعماً فقط» ناقص.","**المشاركة** جهود تطوعية في التخطيط والتنفيذ والتقويم؛ و**الشراكة** علاقة منظمة أوسع بمسؤولية مشتركة."],"src":"المعايير المهنية للمعلمين، هيئة تقويم التعليم والتدريب (المجال الأول: القيم والمسؤوليات المهنية) (3.3)؛ رؤية المملكة 2030 (الشراكة المجتمعية)؛ أدبيات الشراكة بين المدرسة والأسرة والمجتمع (إبستين)"},"ar.l04.local":{"k":"مؤشر 3.3","t":["Local Issues & Functional Knowledge","القضايا المحلية ووظيفة المعرفة"],"aka":["القضايا المحلية","وظيفة المعرفة","القضية المحلية"],"body":["مؤشر الممارس 3.3 يطلب أن **يتقصى القضايا المحلية ويوظفها في التدريس بصورة تعزز وظيفة المعرفة**. و«وظيفة المعرفة» أن يستعمل الطالب ما تعلمه ليفهم مشكلة في بيئته ويقترح لها حلاً، فتصير المعرفة أداة لا محفوظاً."],"pts":["**التقصي**: الأخبار المحلية، والإحصاءات الرسمية، وسؤال الأسر والطلاب، والمؤسسات القريبة.","**التوظيف** مربوط بهدف الدرس: بيانات حقيقية في الرياضيات، نص في اللغة، تجربة في العلوم، مشروع خدمة.","**الضوابط**: مناسبة للعمر، بلا تشهير بأشخاص أو جهات، متسقة مع القيم والأنظمة، ولا تتحول الحصة إلى موعظة.","مدونة 1447: **مراعاة القيم المجتمعية في تقديم المحتوى التعليمي والتوعوي الهادف، مع تجنب المعلومات المضللة** (المادة 10).","مؤشر المتقدم: **يحلل القضايا المحلية التي ينبغي تناولها في المنهج ويبين لزملائه كيفية عرضها**.","**أمثلة قضايا محلية**: ترشيد المياه والكهرباء، السلامة المرورية، النظافة والتشجير، التصحر، التغذية والسمنة، التنمر الإلكتروني، الحفاظ على التراث، الإسراف في المناسبات."],"ex":["في درس التمثيل البياني يجمع طلاب الأول المتوسط استهلاك أسرهم من الكهرباء لشهرين من الفواتير، ويمثلونه بيانياً، ويقترحون ثلاث عادات للترشيد. قضية محلية خدمت هدف الدرس."],"traps":["طرح القضية دون ربطها **بهدف الدرس** ليس توظيفاً.","ذكر اسم جهة أو شخص بعينه في سياق سلبي **تشهير** يخالف الضوابط."],"src":"المعايير المهنية للمعلمين، هيئة تقويم التعليم والتدريب (المجال الأول: القيم والمسؤوليات المهنية) (3.3)؛ مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ (المادة 10)"},"ar.l05.rel":{"k":"استيعاب المقروء","t":["Purpose & Relations","الغرض والعلاقات بين الجمل"],"body":["**الغرض من النص** يُعرف من نوع الجمل: أمر ورجاء = حث، وأدلة وحجج = إقناع. والعلاقة بين الجملتين تُعرف من أداة الربط."],"pts":["**طردية**: كلما زاد س زاد ص؛ و**عكسية**: زاد س نقص ص.","**سبب ونتيجة**: لأن، بسبب، فـ، لذلك؛ و**تمثيل**: مثل، كـ؛ و**تفصيل بعد إجمال**.","**عود الضمير**: على أقرب اسم يستقيم به المعنى، لا أقرب اسم في اللفظ.","**الاستفهام المنفي** (ألم تسافر؟): «بلى» للإثبات و«نعم» للنفي.","البديل الذي **يعارض** النص أو يضيف ما لم يُذكر فيه مرفوض.","**العنوان المناسب** يجمع فكرة النص كاملة؛ وعنوان شخصية أو حدث واحد في نص متعدد الأحداث مشتت."],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 4.1: استيعاب المقروء"},"ar.l06.place":{"k":"الأعداد","t":["Place Value & Rounding","القيمة المنزلية والتقريب"],"pts":["**منازل العدد** من اليمين: آحاد، عشرات، مئات، آحاد الألوف، عشرات الألوف، مئات الألوف، آحاد الملايين؛ في 2571315 الرقم 5 الأيسر في **مئات الألوف**.","**القيمة المنزلية**: الرقم 9 في 59831 قيمته **9000**.","**التقريب**: **5 فأكثر** زد واحداً، و**أقل من 5** احذف: 24.372 ≈ 24، 156.984 ≈ 157، 1.8723 ≈ 1.9 لأقرب عُشر، 28.0153 ≈ 28.02 لأقرب جزء من مئة.","**الترتيب** التصاعدي من الأصغر: قارن العشرية منزلة منزلة (0.405 < 0.45 < 0.5 < 0.6).","**التقدير**: قرّب ثم احسب (0.4 جرام × 1000 دبوس ≈ 400 جرام)."],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 4.4"},"ar.l06.div":{"k":"الأعداد","t":["Divisibility, Primes, GCD & LCM","قابلية القسمة والأولية والقاسم والمضاعف"],"pts":["**قابلية القسمة**: على 2 إذا كان الآحاد زوجياً، على 3 إذا قبل **مجموع الأرقام** القسمة على 3، على 5 إذا انتهى بـ0 أو 5، على 6 إذا قبل 2 و3، على 10 إذا انتهى بـ0.","**العدد الأولي**: 2، 3، 5، 7، 11، 13…؛ والعدد 1 **ليس أولياً**، و2 الأولي الزوجي الوحيد.","فردي + فردي = **زوجي**، وفردي + زوجي = فردي.","**القاسم المشترك الأكبر**: أكبر عدد يقسمهما (16 و28 → 4)؛ و**المضاعف المشترك الأصغر**: أصغر عدد يقبل القسمة عليهما (4 و6 → 12)."],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 4.4"},"ar.l06.frac":{"k":"الأعداد","t":["Fractions, Decimals & Equations","الكسور والعشرية والمعادلة"],"pts":["**مقارنة الكسور**: 2/3 ≈ 0.67، 3/5 = 0.6، 7/10 = 0.7؛ وعند تساوي البسط ذو **المقام الأصغر** أكبر.","**الكسور الشائعة**: 1/2 = 50%، 1/4 = 25%، 3/4 = 75%، 1/5 = 20%، 1/8 = 12.5%، 1/3 ≈ 33.3%، 1/10 = 10%.","**ضرب العشري**: اضرب بلا فاصلة ثم ضعها بعدد المنازل في العددين (1.5 × 2.3 = 3.45)؛ و**القسمة** على عشري: انقل الفاصلة في الطرفين حتى يصير المقسوم عليه صحيحاً.","**المعادلة الخطية البسيطة**: 3س + 7 = 22 → 3س = 15 → س = 5."],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 4.4"},"ar.l07.principles":{"k":"مبادئ النمو","t":["Principles of Development","خصائص النمو ومبادئه"],"body":["النمو **تغيّر تقدمي منظّم** يشمل الجوانب الجسمية والعقلية والانفعالية واللغوية والاجتماعية والأخلاقية، وهي **متكاملة**. وعلم نفس النمو يدرس **السلوك وتطوره** ويفيد في **ملاءمة التدريس للمرحلة**."],"pts":["**خصائص النمو**: **مستمر**، **متتابع**، **تراكمي**، **متغير السرعة**، **قابل للتنبؤ** لكن **بفروق فردية**.","**بمعدلات مختلفة**: سريع في الطفولة المبكرة والمراهقة، بطيء في الطفولة المتوسطة.","اتجاهه **رأسي–ذيلي** و**مركزي–طرفي** (الذراع قبل الأصابع)، و**من العام إلى الخاص** (القبض بالكف قبل الأصابع).","عوامله: **تفاعل الوراثة والبيئة**، و**النضج** والتعلم والغدد والتغذية والأسرة.","**التكويني** (البنائي) زيادة في الحجم والشكل، و**الوظيفي** تحسّن أداء الأعضاء والقدرات.","مسك القلم نمو **جسمي (حركي دقيق)**، وتكوين المفاهيم **عقلي**، والتحكم بالغضب **انفعالي**."],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.1"},"ar.l07.stages":{"k":"المراحل الدراسية","t":["School-Age Characteristics","خصائص المراحل الدراسية"],"pts":["**الطفولة المتوسطة (6–9، الصفوف الأولية)**: نمو جسمي **بطيء منتظم**، مرحلة **الفضول والسؤال**، ولا يُطلب فيها الجلوس الطويل.","**الطفولة المتأخرة (9–12، الصفوف العليا)**: **سن الجماعة/العصابة**، تطبيع اجتماعي، زيادة المفردات، بطء جسمي قبل طفرة المراهقة.","**المراهقة المبكرة (12–15، المتوسطة)**: **طفرة نمو جسمي** وبلوغ، البحث عن القدوة، و**أحلام اليقظة**.","**المراهقة المتوسطة (15–18، الثانوية)**: الاستقلال عن الأسرة، الاهتمام بالمهنة، المثالية والمجادلة، الشعور بالذات ومقاومة السلطة.","البنات يسبقن الأولاد في البلوغ بنحو **سنة إلى سنتين**.","الطفل الذي **يرمي الأشياء ويجربها** يمارس **الاستكشاف**؛ و**التعليم يجب أن يناسب مرحلة النمو**."],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.1"},"ar.l07.stress":{"k":"الأحداث الضاغطة","t":["Stressful Events & Growth Problems","الأحداث الضاغطة ومشكلات النمو"],"body":["مؤشر 5.1 للممارس: **يبين تأثير مشكلات النمو والأحداث اليومية الضاغطة على تعلم المتعلم وكيفية التعامل معها**."],"pts":["**أحداث ضاغطة**: طلاق الوالدين أو خلافهما، وفاة قريب، الانتقال، ولادة أخ، المرض، ضغط الاختبارات، التنمر؛ وأثرها: تشتت وتراجع وانسحاب أو عدوان وشكاوى جسمية وغياب.","**مشكلات نمو شائعة**: **القلق**، **العدوان**، **الغيرة**، **الكذب** (خيالي أو هروب من العقاب)، **الخجل والانطواء**، **مخاوف المدرسة**.","**العلامة التحذيرية**: **التغير المفاجئ** في السلوك أو التحصيل أو المظهر.","التعامل: **ملاحظة** ← **حوار فردي هادئ** بلا لوم ← **مرونة مؤقتة** ← **إحالة** للموجه الطلابي والأسرة ← متابعة؛ ويوفّر **روتيناً ثابتاً** ويحفظ **السرية**.","**الطالب المنتقل حديثاً**: تعريفه بالفصل، و**زميل مرافق**، وإشراك تدريجي.","**قلق الاختبار**: توضيح التقويم مبكراً، وتدريب على أسئلة مشابهة، وتنويع أدوات التقويم، وإدارة الوقت."],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.1"},"ar.l07.emo":{"k":"الحماية","t":["Emotional Disorders, Abuse & Neglect","الاضطراب الانفعالي والإيذاء والإهمال"],"body":["مؤشر 5.1 للممارس: **يوضح مؤشرات الاضطرابات الانفعالية وحالات الاعتداء والإهمال**؛ والمعلم أقرب من يلاحظها يومياً."],"pts":["**مؤشرات اضطراب انفعالي**: حزن مستمر، انسحاب، نوبات غضب أو عدوان، خوف مفرط، شكاوى جسمية بلا سبب طبي، تغير حاد في النوم أو الأكل أو التحصيل.","**الإيذاء** (قواعد 1447): كل استغلال أو إساءة **الجسدية أو النفسية أو الجنسية** أو التهديد بها، ومنه التقصير في الحاجات الأساسية؛ و**الإهمال**: عدم توفير الحاجات الجسدية والصحية والعاطفية والتربوية أو التقصير فيها.","علامات محتملة: **جسدي** (كدمات أو حروق غير مفسرة، خوف من العودة إلى المنزل)، **نفسي** (خوف شديد، تدنٍّ حاد في تقدير الذات)، **إهمال** (جوع مستمر، رداءة النظافة، غياب، حاجات صحية مهملة).","تعد القواعد **انقطاع الطالب عن التعليم** نوعاً من الإيذاء أو الإهمال، وتستثني المتعرض للإيذاء من إجراءات تهدد سلامته.","**ليست دليلاً قاطعاً**: المعلم **يلاحظ ويوثق ويبلغ** ولا يعد الطالب بإخفاء الأمر.","إذا كان المصدر **أحد منسوبي المدرسة** تُرفع الحالة إلى **إدارة التعليم**، ولمن لاحظ **تراخياً من الإدارة** الإبلاغ مباشرة إلى 1919."],"src":"قواعد السلوك والمواظبة لطلبة التعليم العام، الإصدار الخامس 1447هـ، المادة 29"},"ar.l08.indiv":{"k":"الفروق الفردية","t":["Individual Differences","الفروق الفردية"],"body":["**انحراف الفرد عن متوسط الجماعة** في سمة ما؛ وهي **كمية** (في الدرجة لا في النوع) وتتوزع **توزيعاً اعتدالياً**."],"pts":["**فروق بين الأفراد** و**فروق داخل الفرد**.","أسبابها **الوراثة** و**البيئة** و**العمر** و**الجنس**: عوامل **طبيعية** وأخرى **مكتسبة**.","**أكبر مدى** في **الانفعالية والشخصية** ثم العقلية، و**أقل مدى** في **الجسمية**؛ و**العقلية أكثر ثباتاً**، والانفعالية **أكثر تغيراً**.","تظهر في **القدرات** و**التحصيل** و**الاستعداد** و**الاتجاهات** و**الميول**؛ والاستجابة على «موافق بشدة… غير موافق بشدة» تقيس **الاتجاهات**.","تراعيها: التعليم المتمايز، الموديولات والحقائب، التعليم المبرمج، التعاوني، الصف المقلوب؛ مع **تنويع** و**عدم** المقارنة العلنية.","**زمن الرجع**: الزمن بين ظهور المثير وبداية الاستجابة، من مظاهر الفروق التي تُقاس كمياً."],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.2"},"ar.l08.styles":{"k":"أنماط التعلم","t":["Learning Styles & Models","أنماط التعلم ونماذجها"],"pts":["أنماط التعلم (VARK): **البصري** صور ورسوم وخرائط، **السمعي** شرح ومناقشة، **الحسي الحركي** تجربة وحركة، **القرائي الكتابي** نصوص وملاحظات.","تقسيم (بصري/سمعي/حسي) يعتمد على **أنماط التعلم**، لا على الذكاءات المتعددة.","**نموذج كولب**: خبرة محسوسة ← ملاحظة تأملية ← تصور مجرد ← تجريب نشط.","**مكارثي (4MAT)**: لماذا؟ ماذا؟ كيف؟ ماذا لو؟","**هيرمان** يصنف التفكير في أربعة أرباع: تحليلي، منظم، شعوري اجتماعي، تخيّلي.","التطبيق: **تنويع** العرض والأنشطة لا تصنيف الطلاب."],"ex":["تتأمل قضايا الحياة ونفسها = ذاتي؛ تحب الألغاز = **منطقي**؛ يقود زملاءه ويفهم مشاعرهم = **اجتماعي**؛ يصنف النباتات = **طبيعي**."],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.2"},"ar.l08.ld2":{"k":"صعوبات التعلم","t":["Diagnosing & Teaching LD","تشخيص صعوبات التعلم وتدريسها"],"pts":["**محك التباين**: فجوة بين **القدرة (الذكاء)** والتحصيل؛ وسبب التدني **اضطراب في العمليات الذهنية**، ويُعدّ للطالب **خطة تربوية فردية**. و**الصعوبات الأولية** خلل في العمليات النفسية نفسها، و**الثانوية** تنتج عن عوامل خارجية كسوء التعليم.","من **مؤشراتها** استمرار المشكلات بعد **الصف الثاني الابتدائي** رغم سلامة الذكاء والحواس، فيُحال للتشخيص.","أدوات التشخيص: الملاحظة، المقابلة، دراسة الحالة، الاختبارات محكية المرجع، و**الاختبارات التحصيلية والتشخيصية** مقارنةً بالقدرة، ومقياس **مايكل بست**.","**استراتيجيات تدريس ذوي الصعوبات**: التدريس المباشر، **تعدد الحواس (VAKT)**، استراتيجية **التجميع**، واستراتيجية **الموقع**.","تفريق سريع: ضعيف في **كل المواد** مع ذكاء حدّي = بطء تعلم؛ في **مادة أو مادتين** مع ذكاء عادي = صعوبات؛ بسبب **إهمال وغياب** = تأخر دراسي (يُعالج بمعالجة السبب)."],"ex":["طالب ذكي في النقاش يقلب الحروف ويتعثر في القراءة: المعلم لا يصفه بالكسل، بل يوثق ملاحظاته ويحيله إلى معلم صعوبات التعلم."],"src":"الدليل التنظيمي للتربية الخاصة (وزارة التعليم)"},"ar.l08.sensory":{"k":"الفئات الخاصة","t":["Sensory & Physical Disabilities, ADHD","الإعاقات الحسية والجسمية وفرط الحركة"],"pts":["**الإعاقة السمعية**: لغة الإشارة وقراءة الشفاه، مواجهة الطالب، الجلوس في المقدمة، الوسائل البصرية.","**الإعاقة البصرية**: **برايل** والمواد المسموعة والمجسمات، والوصف اللفظي لما على السبورة.","**الإعاقة الجسمية**: قصور حركي أو حسي قد يصحبه قلق وعدم اتزان انفعالي؛ و**متلازمة داون** سببها كروموسومي.","**فرط الحركة وتشتت الانتباه (ADHD)**: بعيداً عن المشتتات، مهام قصيرة، فواصل حركية، تعليمات واضحة، تعزيز فوري.","**التوحد** يظهر قبل سن الثالثة؛ وبيئته **التعلم المنظم** (TEACCH).","مع أي فئة: **اعتراف بالإنجاز** ومهام في حدود القدرة وتعزيز فوري و**عدم** الإحراج أمام الأقران؛ ولا يُبلَّغ ولي الأمر بتشخيص غير مؤكد."],"src":"الدليل التنظيمي للتربية الخاصة (وزارة التعليم)"},"ar.l08.giftchar":{"k":"الموهوبون","t":["Gifted Traits & Provision","خصائص الموهوب ورعايته"],"pts":["خصائصه: نمو لغوي مبكر، فضول غير عادي، ذاكرة قوية، طلاقة لفظية، **حس الدعابة**، **قيادية**، نضج أخلاقي مبكر، **حساسية مفرطة** و**الكمالية**.","قد يشعر بالملل والاضطراب إذا لم يُتحدَّ.","**التعجيل (التسريع)**: القبول **المبكر**، **تخطي الصفوف**، **ضغط المنهج**، مقررات متقدمة.","**التجميع**: فصول أو مجموعات خاصة؛ ويُفضّل في المملكة الإثراء داخل المدرسة مع برامج موهبة.","الخطأ: مزيد من **التمارين نفسها** أو جعله مساعداً للمعلم دائماً؛ والصحيح مهام أعمق.","الكشف بـ**محكات متعددة**: ذكاء وقدرات، تحصيل، إبداع، **ترشيح المعلم**، ملاحظة الأداء."],"ex":["طالبة أنهت تمارين الكسور في دقائق: لا تُعطى عشرين مثلها، بل مشكلة مفتوحة (تحويل وصفة من 4 أشخاص إلى 30)."],"src":"القواعد التنظيمية لفصول ومدارس الموهوبين 1447هـ؛ المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.4"},"ar.l08.bg":{"k":"الخلفيات","t":["Social, Economic & Cultural Backgrounds","الخلفيات الاجتماعية والاقتصادية والثقافية"],"body":["مؤشر 5.2 للممارس: **يميز الاختلافات بين المتعلمين التي تعزى للخلفيات الاجتماعية والاقتصادية والثقافية واحتياجاتها التعليمية التي ينبغي تلبيتها**."],"pts":["**الخلفية الاقتصادية المحدودة**: نقص الأدوات والإنترنت؛ فمصادر المدرسة، و**عدم اشتراط مواد مكلفة**، ووقت للإنجاز في المدرسة.","**الخلفية الاجتماعية** (تعليم الوالدين، حجم الأسرة واستقرارها) تؤثر في الدعم المنزلي والخبرات السابقة.","**الخلفية الثقافية واللغوية** (طالب وافد، لغة أم غير العربية): أمثلة متنوعة وشرح للمفردات واحترام للعادات.","**التدريس المستجيب ثقافياً**: **توقعات عالية للجميع** وتجنب **القوالب النمطية**.","الإطار الوطني لمعايير المناهج: **تكافؤ فرص التعلم** يراعي الفروق و**الخلفيات الثقافية والاجتماعية** لكل الفئات؛ و**العدالة** **تقديم ما يحتاجه كل طالب**.","التعرف على الخلفيات بالحوار وبطاقة الطالب والأسرة والموجه، مع حفظ **خصوصية** الظروف."],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.2"},"ar.l08.iepteam":{"k":"التربية الخاصة","t":["IEP Team, Family & Placement","فريق الخطة ودور الأسرة والمكان التربوي"],"body":["مؤشر 5.4 للممارس: **يبين الإجراءات التي ينبغي التقيد بها في التعامل مع الفئات الخاصة، ويعرف الجهات التي يجب إشراكها في متابعة حالاتها**. والخطة في لائحة تقويم الطالب: وصف للخدمات التربوية والمساندة يعدها **فريق متعدد التخصصات**."],"pts":["المسار ينتهي بتحديد **الأهلية والمكان التربوي** ثم الخطة؛ والتشخيص **لا يُكتفى بنتيجة مقياس واحد**. و**لجنة الخطط التعليمية**: قائد المدرسة (رئيساً)، وكيل الشؤون التعليمية، **معلم التربية الخاصة**، **معلم التعليم العام**، المرشد أو الأخصائي الاجتماعي، **المختصون**، **ولي الأمر**، و**الطالب** قدر الإمكان.","عناصر الخطة: **مستوى الأداء الحالي** ← **أهداف طويلة المدى** ← **أهداف قصيرة المدى** ← **أهداف تدريسية** ← **الخدمات** ← **مواعيد** ← **التقويم** ← **المشاركون**؛ وهي **وثيقة متجددة** تُراجع **سنوياً أو نصف سنوي**.","**دور الأسرة**: الموافقة والمشاركة والتنفيذ في المنزل؛ و**على المدرسة** الشرح بلغة مفهومة والإشعار خطياً قبل أي تحويل.","**دور معلم التعليم العام بعد الإحالة**: تكييف التدريس والمشاركة في الخطة والتقويم **بالتعاون مع معلم التربية الخاصة**.","**الخدمات المساندة**: **العلاج الطبيعي والوظيفي وتصحيح عيوب النطق والكلام والإرشاد النفسي**.","**المكان التربوي**: فصل عام مع معلم مستشار ← معلم متجول ← **غرفة المصادر** ← فصل خاص ← معهد."],"src":"الدليل التنظيمي للتربية الخاصة (وزارة التعليم)؛ لائحة تقويم الطالب وإجراءاتها"},"ar.l09.thorndike":{"k":"السلوكية","t":["Thorndike, Watson & Guthrie","ثورندايك وواطسون وجاثري"],"body":["**ثورندايك – المحاولة والخطأ** (القط في الصندوق): التعلم اختيار الاستجابة الناجحة وتثبيتها بعد محاولات عشوائية. وهو صاحب نظرية **العناصر المتطابقة** في انتقال الأثر."],"pts":["قوانينه: **الأثر** (المتبوعة بارتياح تقوى)، **التدريب/التكرار** (الاستعمال يقوي)، **الاستعداد** (التهيؤ).","**واطسون** مؤسس المدرسة السلوكية (الطفل ألبرت): الانفعالات تُتعلم بالإشراط، والبيئة تصنع الفرد.","**جاثري** نظرية **الاقتران**: اقتران واحد كافٍ للتعلم.","**قانون المرة الواحدة**: ارتباط من خبرة واحدة شديدة (الخوف من النار بعد لسعة).","الاشتراط الإجرائي يُسمى **الاشتراط الوسيلي**؛ لأن الاستجابة وسيلة للمعزز.","عند بافلوف أيضاً **الإشراط من الدرجة الثانية**."],"traps":["المحاولة والخطأ تدريجي، والاستبصار مفاجئ."],"src":"Thorndike, Animal Intelligence؛ Watson (1913)؛ Guthrie (1935)"},"ar.l09.terms":{"k":"مفاهيم","t":["Learning, Instruction, Teaching, Education","التعلم والتعليم والتدريس والتربية"],"pts":["**التعلم** نشاط ذاتي يكتسب به المتعلم السلوك من الخبرة والممارسة؛ تغير شبه دائم.","**التعليم** تصميم منظم للخبرة يساعد المتعلم على تغيير سلوكه.","**التدريس** إجراء قصير المدى يقوم به المعلم لأهداف محددة.","**التربية** عملية شاملة تستهدف نمو الفرد وإعداده للحياة."],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.3"},"ar.l09.reinf":{"k":"السلوكية","t":["Reinforcers & Applications","المعززات وتطبيقات سكنر"],"pts":["**أنواع المعززات**: **مادية** (هدية)، **اجتماعية** (ابتسامة، مدح)، **رمزية** (نجوم تُستبدل = **الاقتصاد الرمزي**)، **نشاطية** (وقت لعب).","**التسلسل**: ربط خطوات سلوك مركب؛ و**التلاشي**: سحب المساعدات تدريجياً.","**التعليم المبرمج**: خطوات صغيرة + استجابة نشطة + تغذية راجعة فورية + سير ذاتي؛ الخطي لسكنر والمتشعب لكراودر.","تطبيقات أخرى: **تعديل السلوك**، و**العقود السلوكية**، والتعلم للإتقان.","التعزيز **فوري** و**متنوع** و**متناسب**، للسلوك لا للشخص، ويتحول من مادي إلى اجتماعي إلى ذاتي.","**العقاب السالب**: الحرمان من الفسحة = **تكلفة الاستجابة**، و**الإقصاء** إبعاد عن مصدر التعزيز."],"ex":["طالب خجول: مدح حين يرفع يده، ثم حين يجيب بكلمة، ثم بجملة؛ تشكيل بالتقريبات، ثم تعزيز متقطع حتى لا ينطفئ."],"src":"Skinner, The Technology of Teaching"},"ar.l09.moraldis":{"k":"التعلم الاجتماعي","t":["Bandura — Moral Disengagement","الانفصال الأخلاقي والنمذجة في الصف"],"pts":["آليات **الانفصال الأخلاقي**: **التبرير الأخلاقي**، **التهذيب اللفظي** (الاعتداء «مزاح»)، **المقارنة المريحة**، **إزاحة المسؤولية**، **تشويه العواقب**، **لوم الضحية**.","النظرية **حلقة وصل** بين السلوكية والمعرفية، وتقوم على **الحتمية التبادلية**.","**التعزيز الذاتي** يأتي من رضا الفرد عن نفسه، و**العقاب البديل** يقلل السلوك عند الملاحظ.","تطبيقات: المعلم **قدوة** (يؤدي الوضوء أمام الطلاب)، فيديو ثم تطبيق، نماذج حية ورمزية.","النمذجة الأنسب لتعلم **الاتجاهات والقيم والمهارات الاجتماعية**.","مصادر الكفاءة الذاتية: **خبرات الإتقان**، **الخبرات البديلة**، **الإقناع اللفظي**، **الحالة الفسيولوجية**."],"src":"Bandura, Moral Disengagement (2016)؛ Social Foundations of Thought and Action"},"ar.l09.tolman":{"k":"المعرفية","t":["Tolman & the Cognitive View","تولمان والمدخل المعرفي"],"body":["النظريات المعرفية تهتم بـ**العمليات العقلية الداخلية** (الإدراك، الفهم، التنظيم، المعنى)، والمتعلم **نشط** يعالج المعلومات."],"pts":["**تولمان** (الفئران في المتاهة): **التعلم الكامن** يحدث دون تعزيز ويظهر عند الحاجة، ويكوّن المتعلم **خرائط معرفية**؛ والتعلم **هادف**.","**فرتهايمر** مؤسس الجشطلت، و**كوهلر** صاحب القرد والعصا، و**كوفكا** ثالثهم.","**أوزوبل – التعلم ذو المعنى بالاستقبال**: **الاندماج/الاحتواء** في البنية المعرفية؛ وأنماطه من (**استقبال/اكتشاف**) × (**ذو معنى/صمّ-استظهار**)، ولا يوجد «استقبال قائم على الاكتشاف».","**التمايز التقدمي**: الأفكار الشاملة أولاً؛ و**التوفيق التكاملي**: ربط الجديد بالسابق؛ وخرائط المفاهيم (نوفاك) من تطبيقاته.","تطبيق: **فيلم تمهيدي** عن تجاذب الأجسام قبل درس الشحنات = **منظم متقدم**.","**برونر – التعلم بالاكتشاف**: **بنية المادة**، والاستعداد، والدافعية الداخلية، و**الاكتشاف الموجه** الأنسب صفياً؛ و**العملي/الحركي** ← **الأيقوني/التصويري** ← **الرمزي**."],"src":"Tolman, Purposive Behavior in Animals and Men؛ Ausubel؛ Bruner"},"ar.l09.memtypes":{"k":"معالجة المعلومات","t":["Memory Types & Forgetting","أنواع الذاكرة والنسيان"],"pts":["**الذاكرة الحسية** (ثوانٍ، سعة كبيرة) ← **قصيرة المدى/العاملة** (**7±2**، 15–30 ثانية) ← **طويلة المدى** (سعة غير محدودة)؛ وما لا يُنتبه له يُفقد.","الطويلة: **تقريرية** (دلالية: معانٍ؛ عرضية: أحداث شخصية) و**إجرائية** (مهارات كالسباحة).","**نظريات النسيان**: **الاضمحلال**، **التداخل** (**قبلي** و**بعدي**)، **الكبت**، فشل الاسترجاع.","**الترميز المزدوج** (بايفيو/**بافيو**): التخزين **لفظياً وبصرياً** معاً؛ و**الحمل المعرفي** (سويلر).","النموذج (نورمان وأتكنسون وشفرن) يشبّه العقل بالحاسوب: مدخلات ← معالجة ← مخرجات؛ وعدم الاسترجاع نسيان.","**التدريب الموزع** (جلسات متباعدة) أفضل من **التدريب المكثف**؛ والنقل للطويلة: **التسميع (الإعادة)**، **التجميع/التقطيع**، **التفصيل/الإتقان**، التنظيم، الوسائل التذكرية."],"src":"Atkinson & Shiffrin (1968)؛ Tulving (1972)؛ Paivio"},"ar.l09.transfer":{"k":"البنائية","t":["Transfer of Learning","انتقال أثر التعلم"],"body":["استخدام خبرة سابقة في موقف جديد. ويحققه التدريس للفهم لا للحفظ، وتنويع الأمثلة والسياقات، وربط التعلم بالحياة."],"pts":["**موجب** (القراءة تسهّل أي جملة)، **سالب** (عادة قديمة تعيق الجديد)، **صفري**.","**أفقي** (المستوى نفسه في سياق آخر) و**رأسي** (مهمة أعلى تبنى على السابقة)؛ و**قريب/بعيد**.","تفسيره: **العناصر المتطابقة** (ثورندايك) و**التعميم** (جد).","البنائية: المعلم **ميسّر**، والخطأ فرصة، والتقويم بديل (مشاريع، حل مشكلات)."],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.3"},"ar.l09.brain":{"k":"الدماغ","t":["Brain-Based Learning","التعلم المستند إلى الدماغ"],"body":["مؤشرا 5.3 للممارس: **يعرف نظريات التعلم ونتائج الأبحاث العلمية المعاصرة في عمليات التعلم وكيفية توظيفها**، و**يعرف أساليب التعلم الفردي ويبين مدى اعتمادها على العوامل المعرفية والانفعالية والبيئية**."],"pts":["مبادئ (كين وكين): الدماغ **اجتماعي**، و**البحث عن المعنى** فطري بتكوين **الأنماط**، و**الانفعالات** أساسية، و**يتعزز بالتحدي ويُكبح بالتهديد**، وكل دماغ **فريد**، ويعالج **الأجزاء والكل معاً**.","**الاسترخاء اليقظ**: أمان نفسي مع تحدٍّ مرتفع؛ **الانغماس المنظم** في خبرات حقيقية؛ **المعالجة النشطة** بالتأمل والتلخيص والتطبيق.","في الصف: تقليل التهديد، ربط بخبرة الطالب، تنويع الحواس، فواصل وحركة، تعاون، تغذية راجعة فورية."],"src":"Caine & Caine, Making Connections؛ المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.3"},"ar.l09.styles":{"k":"الأساليب المعرفية","t":["Cognitive Styles","الأساليب المعرفية"],"body":["**الأسلوب المعرفي** طريقة مفضلة **ثابتة نسبياً** في الإدراك والتفكير وتنظيم المعلومات؛ يصف **كيف** يتعلم الفرد لا **مقدار** ذكائه."],"pts":["**الاعتماد على المجال مقابل الاستقلال عنه** (ويتكن): **المعتمد** يدرك الكل ويتأثر بالسياق ويفضل العمل الجماعي، و**المستقل** يحلل ويفضل الفردي؛ ويُقاس بـ**الأشكال المتضمنة**.","**الاندفاع مقابل التروي** (كاجان): **المندفع** سريع كثير الخطأ، و**المتروي** يفحص البدائل؛ ويُعالج الاندفاع بـ**التوقف والتفكير** وتمديد وقت الانتظار.","**نموذج دن ودن**: عناصر **بيئية** (الصوت، الإضاءة، الحرارة) و**انفعالية** (الدافعية، المثابرة) و**اجتماعية** و**جسمية** و**نفسية**.","لا أسلوب أفضل مطلقاً: المعلم **ينوع**، ويساعد الطالب على **الوعي بأسلوبه**."],"src":"Witkin (1977)؛ Kagan (1965)؛ Dunn & Dunn"},"ar.l10.motiv":{"k":"الدافعية","t":["Motivation — Basics & Classroom","الدافعية: خصائصها وإجراءاتها"],"body":["الدافعية **حالة داخلية** تحرّك السلوك؛ **الدافع** داخلي و**الحافز** خارجي و**الباعث** هدف يجذب. والإفراط في المكافآت الخارجية **يُضعف** الداخلية (أثر التبرير الزائد)."],"pts":["**خصائص الدافعية**: الغرضية، النشاط، الاستمرار، التنوع، التحسين والتكيف؛ و**وظائفها**: توليد السلوك وتوجيهه وتحديد شدته وديمومته.","**أنواع الدوافع**: **بيولوجية** (جوع، عطش) و**اجتماعية** مكتسبة (الأمن، الانتماء، الإنجاز)؛ و**موراي** و**أتكنسون** من رواد دافعية الإنجاز.","**نظرية التوقع والقيمة**: الدافعية = توقع النجاح × قيمة المهمة.","إجراءات صفية: تغذية راجعة **فورية وصفية**، توقعات عالية، تنويع، **عدم المقارنة**، إشراك الطالب في مجموعة متميزة، مهام في حدود القدرة مع تحدٍّ.","**دويك**: **توجه الإتقان** أفضل من **توجه الأداء**، و**العقلية النامية** مقابل **الثابتة**؛ و**ماكليلاند/أتكنسون – دافع الإنجاز**: مهام **متوسطة الصعوبة**."],"ex":["طالب رسب ويقول «أنا غبي في الرياضيات»: ينقل المعلم العزو إلى الجهد والاستراتيجية: «أخطأت في خطوتين لم نتدرب عليهما».","هرم ماسلو في صورته الموسعة **سبعة** مستويات: فسيولوجية ← أمن ← انتماء ← تقدير ← **المعرفة** ← **الجمال** ← تحقيق الذات."],"src":"Deci & Ryan؛ Eccles & Wigfield؛ المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.3"},"ar.l10.iq":{"k":"الذكاء","t":["IQ & Intelligence Tests","نسبة الذكاء واختباراته"],"body":["**الذكاء** قدرة عقلية عامة على التعلم والتفكير المجرد والتكيف وحل المشكلات. **بينيه** وضع **أول اختبار ذكاء** (1905) ومفهوم **العمر العقلي**، و**نسبة الذكاء** (ستيرن/تيرمان) متوسطها 100 وانحرافها 15."],"pts":["**90–109** متوسط، **70–85** بطيء التعلم (حدّي)، **أقل من 70** إعاقة فكرية، **130 فأكثر** موهوب.","**ثابتة نسبياً**: طالب ذكاؤه 110 يبقى قريباً منها.","**جالتون** أكد **الوراثة** وابتكر **معامل الارتباط**؛ **وكسلر** مقاييس لفظية وأدائية؛ **ستانفورد بينيه** أول اختبار مقنن؛ **رافن** مصفوفات غير لفظية.","النتيجة **لا تُستخدم وحدها** للتصنيف، ولا تُعلن للطلاب.","**سبيرمان – العاملان**، **جاردنر – الذكاءات المتعددة**، **ستيرنبرغ – الثلاثي**، **جولمان – الذكاء الوجداني (العاطفي)**؛ و**ثيرستون – القدرات العقلية الأولية**؛ **جيلفورد – بنية العقل**؛ **كاتل**: ذكاء **سائل** و**متبلور**."],"src":"Binet & Simon (1905)؛ Terman, Stanford-Binet؛ Wechsler"},"ar.l10.goleman":{"k":"الذكاء","t":["Goleman — Emotional Intelligence","جولمان: الذكاء الوجداني"],"body":["دانيال جولمان رأى أن النجاح لا يتوقف على الذكاء المعرفي وحده، بل على **الذكاء الوجداني (العاطفي)**: فهم الانفعالات وإدارتها في النفس ومع الآخرين."],"pts":["**الوعي بالذات**: معرفة الفرد بانفعالاته.","**تنظيم الانفعالات**: التحكم فيها.","**الدافعية**: توجيه الانفعالات نحو الهدف.","**التعاطف**: فهم مشاعر الآخرين.","**المهارات الاجتماعية**: إدارة العلاقات."],"src":"Goleman, Emotional Intelligence (1995)"},"ar.l10.critical":{"k":"التفكير","t":["Critical, Reflective & Scientific Thinking","التفكير الناقد والتأملي والعلمي"],"body":["**التفكير الناقد**: فحص المعلومات والحجج و**تقويمها** بمعايير مع مراعاة وجهات نظر الآخرين؛ منطلقه **الشك المنهجي**."],"pts":["مهاراته (واطسون–جليسر): **الاستنتاج**، **التعرف على الافتراضات**، **الاستنباط**، **التفسير**، **تقويم الحجج**؛ ومنها **التمييز** بين الحقيقة والرأي والكشف عن **التحيز**.","أمثلة: تحليل وجهات نظر مختلفة، تقييم مواقع الإنترنت من حيث **دقة المعلومات ومصداقيتها**، تقديم **تفسيرات منطقية للنتائج**.","**التفكير التأملي** مراجعة الخبرة؛ و**حل المشكلات** (ديوي): الشعور بالمشكلة ← تحديدها ← فروض ← اختبار ← تعميم؛ و**اتخاذ القرار** مفاضلة بين بدائل.","**التفكير العلمي**: الإحساس بالمشكلة ← جمع البيانات ← الفروض ← اختبارها ← نتيجة قابلة للتحقق؛ و**الاستدلال** نتيجة من أدلة كافية.","تدريس التفكير **مباشر** (كورت) أو **مدمج** في المحتوى؛ مع أسئلة مفتوحة و**ينتظر 3–5 ثوانٍ**.","**KWL**: ماذا أعرف؟ ماذا أريد أن أعرف؟ ماذا تعلمت؟ تنمي **ما وراء المعرفة**؛ والدنيا في بلوم: التذكر والفهم والتطبيق."],"src":"Watson & Glaser؛ Dewey, How We Think؛ المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.3"},"ar.l10.creatools":{"k":"الإبداع","t":["Fluency, Flexibility & Idea Tools","أنواع الطلاقة والمرونة وأدوات التوليد"],"pts":["أنواع الطلاقة: **لفظية** (كلمات بحرف معين)، **فكرية/معاني** (حلول كثيرة)، **أشكال**، **تداعي** (كلمات بمعنى واحد).","**المرونة التكيفية** تغيير الوجهة بحسب الموقف، و**المرونة التلقائية** أفكار متنوعة من تلقاء النفس.","**الإثارة العشوائية**: علاقة بين مفهومين لا رابط بينهما («ما العلاقة بين المفتاح والمدير؟»)؛ و**التفكير الجانبي** (ديبونو) خروج من الأنماط المعتادة.","تنمية الإبداع: **أسئلة مفتوحة** («ماذا لو…»، نهاية جديدة لقصة)، **سكامبر**، الرحلة التخيلية، قبول غير المألوف.","**الكلمات المترابطة**: استراتيجية للتفكير الناقد يميز فيها الطالب المترابط من غير المترابط.","القاعدة الخاطئة في العصف: **فحص الأفكار ونقدها قبل طرحها**؛ و**إرجاء الحكم** و**الكم قبل الكيف** هما الصواب."],"ex":["«اذكر أكبر عدد من استخدامات القلم» = **طلاقة**؛ تنوعت الفئات = **مرونة**؛ إجابة لم يذكرها أحد = **أصالة**؛ شرح التفاصيل والرسم = **الإفاضة/التوسع**."],"src":"Guilford؛ Torrance؛ Osborn؛ de Bono"},"ar.l10.progs":{"k":"برامج التفكير","t":["Herrmann, 4MAT & Thinking Strategies","هيرمان ومكارثي واستراتيجيات التفكير"],"pts":["**هيرمان – السيطرة الدماغية**: **A** تحليلي منطقي، **B** منظم تخطيطي، **C** عاطفي اجتماعي، **D** تخيّلي كلي.","**مكارثي (4MAT)**: لماذا، ماذا، كيف، ماذا لو؛ و**كولب** دورة التعلم الخبراتي.","**التفكير التقاربي** إجابة واحدة، و**التباعدي** إجابات متعددة؛ والاختبارات الموضوعية تقيس التقاربي غالباً.","**برنامج كورت** ست وحدات: توسعة الإدراك، التنظيم، التفاعل، الإبداع، المعلومات والعواطف، الفعل؛ وأداته **PMI**.","استراتيجيات: الخرائط الذهنية (بوزان) والمفاهيمية (نوفاك)، الاستقصاء، المناظرة، لعب الأدوار، **الأسئلة السابرة**، حل المشكلات الإبداعي."],"src":"Herrmann, The Creative Brain؛ McCarthy, 4MAT؛ de Bono, CoRT"},"ar.l10.habits":{"k":"عادات العقل","t":["Costa & Kallick — Habits of Mind","عادات العقل"],"body":["مؤشرا 5.3 للممارس: **يبين عمليات بناء المتعلم للمعاني واكتساب مهارات التفكير الإبداعي والناقد والعادات العقلية**، و**يبين تأثير الاتجاهات والقيم لدى المتعلمين على تعلمهم وكيفية استخدامها لدعمه**."],"pts":["عادات العقل نمط من السلوكيات الذكية عند مشكلة **لا يعرف حلها فوراً**؛ فهي **ميل** لاستخدام المهارة.","الست عشرة: المثابرة، **التحكم بالتهور**، الإصغاء بتفهم وتعاطف، التفكير بمرونة، **التفكير حول التفكير**، **الكفاح من أجل الدقة**، التساؤل، تطبيق المعارف الماضية، التوصيل بوضوح، جمع البيانات بالحواس، الابتكار، الدهشة، المخاطرة المسؤولة، الدعابة، التفكير التبادلي، التعلم المستمر.","تمييز: لا يستسلم = **المثابرة**؛ يراجع حله = **الكفاح من أجل الدقة**؛ يقرأ السؤال كاملاً = **التحكم بالتهور**؛ يعيد صياغة كلام زميله = **الإصغاء بتفهم**؛ يصف كيف وصل = **التفكير حول التفكير**.","تنميتها: **تسميتها**، و**النمذجة**، ومشكلات مفتوحة، و**تعزيز** ظهورها، والتأمل الذاتي."],"src":"Costa & Kallick, Habits of Mind"},"ar.l10.attitude":{"k":"الاتجاهات والقيم","t":["Attitudes & Values","الاتجاهات والقيم والتعلم"],"body":["**الاتجاه** استعداد مكتسب ثابت نسبياً للاستجابة بالقبول أو الرفض نحو موضوع، ومكوناته **معرفي** (معتقدات) و**وجداني** (مشاعر) و**سلوكي** (ميل للفعل)."],"pts":["الاتجاه **الإيجابي** يرفع الانتباه والمثابرة، و**السلبي** يخفض الجهد ويصير نبوءة تحقق ذاتها.","تعديله: **خبرات نجاح** مبكرة، ربط المادة **بحياة الطالب وقيمه**، **القدوة**، بيئة لا تسخر من الخطأ، التعزيز، الحوار؛ لا الوعظ وحده ولا الإجبار.","**القيم** معايير يحكم بها المتعلم؛ وإذا رأى المحتوى **يتصل بقيمه** (الإتقان، خدمة المجتمع، الأمانة العلمية) زاد اندماجه."],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.3"},"ar.l11.other":{"k":"مداخل التدريس","t":["Teaching Models, Roles & Other Approaches","عائلات النماذج وأدوار المعلم ومداخل أخرى"],"body":["**نموذج التدريس** تصور نظري لخطوات التدريس تُشتق منه استراتيجيات، و**مهارة التدريس** أداء جزئي محدد كالتهيئة أو طرح الأسئلة أو الغلق."],"pts":["عائلات **جويس وويل**: **معالجة المعلومات** (الاستقراء، المنظم المتقدم، الاستقصاء، تكوين المفاهيم)، و**الاجتماعية** (التعاوني، لعب الأدوار، التقصي الجماعي).","و**السلوكية** (التعليم المبرمج، التعلم للإتقان، التعليم المباشر)، و**الشخصية** (التدريس غير الموجه).","أدوار المعلم: **المرشد** يوجه المتعلم، **الميسّر** يهيئ الظروف ويدعم عند الحاجة، **المفوّض** يفوض الطلاب مسؤولية تعلمهم ويراقب، **التقليدي** ملقن ناقل للمعلومة.","**المدخل المنطقي** يرتب المحتوى من البسيط إلى المعقد ومن القديم إلى الحديث (ومن المحسوس إلى المجرد)، و**المدخل السيكولوجي** وفق ميول المتعلم وحاجاته.","مداخل أخرى: **التاريخي** (تطور الفكر عبر العصور)، **النشاط** (ديوي)، **الضبط** (التحكم في السلوك)، **التكنولوجي**، **التكاملي** (ربط المادة بغيرها)، **البيئي**، **الديني**.","في المدخل المعرفي: **مدخل المادة الدراسية** يهتم بالمحتوى والكتاب المدرسي، و**مدخل بنية العلم** بمفاهيم العلم الكبرى وطرق بحثه."],"traps":["التدريس غير الموجه من العائلة **الشخصية**، والتعاوني من **الاجتماعية**."]},"ar.l11.lecture":{"k":"طرق العرض","t":["Lecture, Discussion & Dialogue","المحاضرة والمناقشة والحوار والقصة"],"body":["طرق يكون فيها المعلم أو المتحدث مصدر الخبرة الأساسي، وتختلف في قدر مشاركة الطالب."],"pts":["**المحاضرة (الإلقاء)**: اقتصادية في الوقت وتناسب الأعداد الكبيرة والمعلومات الكثيرة، لكن المتعلم فيها **متلقٍّ سلبي** وتهمل الفروق الفردية.","**المناقشة**: حوار موجه بين المعلم والطلاب أو بين الطلاب؛ مراحلها تهيئة ← مناقشة ← تقويم، وأبرز عيوبها **سيطرة بعض الطلاب**.","**الحوار السقراطي**: يقود المعلم الطالب بأسئلة متتابعة حتى يكتشف التناقض في رأيه ويصل إلى الصواب بنفسه.","**الندوة**: عدد من المتخصصين يعرضون جوانب موضوع واحد ثم يُفتح النقاش؛ و**المناظرة**: مجموعة مؤيدة وأخرى معارضة بمحكّمين.","**القصة**: تناسب المرحلة الابتدائية ومواد التاريخ والتربية الإسلامية، وتقدم القيم بأقل تجريد وتنمي الخيال."],"traps":["الندوة **متخصصون** يعرضون جوانب موضوع، والمناظرة **مؤيد ومعارض**."]},"ar.l11.demo":{"k":"طرق العرض","t":["Demonstration","العرض العملي (البيان)"],"body":["طريقة مباشرة يؤدي فيها المعلم المهارة أمام الطلاب خطوة خطوة مع **الشرح المتزامن** ثم يطبقونها؛ وتناسب المهارات الأدائية كالوضوء والتجارب، وهي الاختيار الأنسب للتجارب **الخطرة أو المكلفة** أو التي لا تتوفر أدواتها للجميع."],"pts":["الخطوات: **تجريب العرض مسبقاً** ← توضيح هدفه وما سيُلاحظ ← ترتيب المكان بحيث **يرى الجميع**.","ثم الأداء **خطوة خطوة ببطء** مع الشرح والأسئلة ← التأكيد على **قواعد السلامة** ← تطبيق الطلاب تحت الإشراف ← تلخيص وتغذية راجعة.","قصوره: الطالب **مشاهد** إن لم يُشرك، وقد لا يرى البعيدون التفاصيل.","العلاج: إشراك الطلاب في التوقع والملاحظة والتسجيل، والعرض المكبر.","مؤشر 7.2 يطلب **اختيار ما يتوافق منها مع متطلبات المنهج وخصائص نمو المتعلمين**."],"traps":["العرض العملي طريقة **مباشرة**، والتغيير المفاهيمي **بنائي**."]},"ar.l11.self":{"k":"التعلم الذاتي","t":["Self-directed & Individualized Learning","التعلم الذاتي وأدواته"],"body":["التعلم الذاتي يتحمل فيه المتعلم مسؤولية تعلمه بأنشطة ومصادر معدّة، والمعلم موجّه ومصمم؛ وهو مع التعليم المبرمج الطريقة التي تتيح لكل طالب التعلم **حسب سرعته وقدرته**."],"pts":["**الحقيبة التعليمية**: وحدة متكاملة متعددة الوسائط فيها أهداف واختبار قبلي وأنشطة بدائل واختبار بعدي.","**الموديول (الوحدة النسقية)**: وحدة صغيرة مستقلة من برنامج أكبر يدرسها الطالب ذاتياً ويُقوَّم بعدها.","**التعلم الذاتي** برغبة المتعلم لتنمية مهاراته، و**التعليم الفردي** مخطط يؤدي فيه كل طالب المهام نفسها منفرداً، و**التعليم التفريدي** مهام مختلفة وفق الميول.","أهداف **التعليم الفردي**: مراعاة الفروق، والتعلم للإتقان، والتعلم الموجه، وتنمية الاستقلالية والإبداع؛ ومن **وسائل التعلم الذاتي**: المبرمج، والحقائب والموديولات، والحاسوب، وعقود التعلم.","**التعلم الموصوف للفرد**: برنامج علاجي يُصمم لطالب بعينه بعد تشخيص مستواه.","**البرمجيات التعليمية**: تعليمية (تقديم مفهوم)، و**تدريب وممارسة**، و**محاكاة** (التجارب الخطرة)، و**ألعاب تعليمية**، وحل مشكلات، واستقصاء."],"traps":["الفردي **المهام نفسها**، والتفريدي **مهام مختلفة**."]},"ar.l11.social":{"k":"الاستراتيجيات الاجتماعية","t":["Brainstorming, Peers & Other Social Strategies","العصف الذهني والأقران واستراتيجيات اجتماعية أخرى"],"body":["العصف الذهني (أوزبورن) قواعده الأربع: إرجاء الحكم والنقد، وحرية التفكير، و**الكم قبل الكيف**، والبناء على أفكار الآخرين. ولاستمرار التجاوب يسأل المعلم «هل هناك فكرة أخرى؟» لا «هل هناك فكرة أفضل؟» لأنها حكم."],"pts":["رواد التعلم التعاوني: ديوي و**باركر** و**دويتش** وجونسون وجونسون؛ ومراحله: **التعرف** ← تحديد المهمة ← **الإنتاجية** ← **الإنهاء**.","**بيئات التعلم**: **تنافسية** (فوز طالب يعني خسارة آخر)، و**فردية** (كل طالب مستقل)، و**تعاونية** (نجاح المجموعة معاً).","أنواع **تدريس الأقران**: داخل الفصل، وعبر الصفوف (أعلى يعلّم أدنى)، وأقران المجموعة، وخارج الفصل للمنقطعين؛ والقرين المعلّم يرسخ فهمه.","**الكرسي الساخن**: أسئلة تُطرح على طالب معين لتنمية بناء الأسئلة وتبادل الأفكار؛ و**المائدة المستديرة**: إجابات بالتناوب داخل المجموعة.","**الألعاب التعليمية** نشاط موجه يتنافس فيه الطلاب بمتعة لتحقيق هدف الدرس؛ و**اللعب الموجه** يحدده المعلم و**غير الموجه** حر.","**التدريس التبادلي** حوار حول نص مقروء: **التنبؤ** ← **توليد الأسئلة** ← **التوضيح** ← **التلخيص**، وينمي ما وراء المعرفة."],"traps":["«هل هناك فكرة أفضل؟» تخالف قاعدة **إرجاء الحكم**."]},"ar.l11.dale":{"k":"الوسائل والخبرة","t":["Cone of Experience — Edgar Dale","مخروط الخبرة (إدجار ديل)"],"body":["رتّب إدجار ديل الخبرات التعليمية من الأكثر حسية في القاعدة إلى الأكثر تجريداً في القمة؛ كلما نزلنا زادت الحسية وقلّ التجريد، والعكس صحيح."],"pts":["1) **الخبرات المباشرة الهادفة** (يعمل الطالب بنفسه: زراعة، تجربة حقيقية) 2) **الخبرات المعدلة** (النماذج والمجسمات والعينات) 3) **الخبرات الممثلة** (الدراما ولعب الأدوار).","4) التوضيحات العملية 5) الرحلات الميدانية 6) المعارض 7) التلفاز والأفلام 8) الصور الثابتة والتسجيلات.","9) **الرموز البصرية** (الخرائط والرسوم البيانية) 10) **الرموز اللفظية** (الكلمات المسموعة والمقروءة) وهي الأكثر تجريداً.","المجسم الذي يحاكي جسم الإنسان خبرة **معدلة (شبه محسوسة)**، و**المحاكاة** خبرة بديلة للتجارب الخطرة أو المكلفة أو المستحيلة."],"traps":["قمة المخروط **الرموز اللفظية** لا البصرية.","الأصغر سناً يحتاج **قاعدة** المخروط أكثر."]},"ar.l12.levels":{"k":"الأهداف","t":["Levels of Objectives","مستويات الأهداف ومصادرها"],"body":["تتدرج الأهداف من العام البعيد إلى الخاص القريب: **الغايات** تعبر عن فلسفة المجتمع وبعيدة المدى، و**الأهداف العامة** لمرحلة أو مقرر، و**الأهداف الخاصة/السلوكية** لدرس واحد وقابلة للملاحظة."],"pts":["تُشتق الأهداف التربوية العامة من **فلسفة المجتمع** وحاجاته، وطبيعة المتعلم، وطبيعة المعرفة، ونتائج البحوث.","**الهدف السلوكي** عبارة تصف **سلوك المتعلم** المتوقع بعد التعلم، قابلاً للملاحظة والقياس.","شروطه: سلوك **المتعلم** لا المعلم، **ناتج تعلم واحد**، فعل **قابل للملاحظة**، يصف **الناتج** لا النشاط، واضح غير غامض.","أهداف قابلة للقياس: «أن يفسر الطالب الرموز على الخريطة»، «أن يؤدي الطالب الوضوء بصورة صحيحة»."],"ex":["الهدف العام «تدريب التلاميذ على أداء العبادات» يُشتق منه الهدف الخاص «أن يؤدي الطالب الوضوء بصورة صحيحة»."],"traps":["«يوضح المعلم مفهوم…» خطأ لأنه سلوك **المعلم**."]},"ar.l12.plan":{"k":"خطة الدرس","t":["Planning Levels & Lesson Plan","التخطيط ومستوياته وعناصر خطة الدرس"],"body":["التخطيط **طويل المدى** هو الخطة السنوية والفصلية (توزيع المقرر على الأسابيع)، و**قصير المدى** خطة الوحدة والخطة اليومية. ويشمل **التخطيط للوحدة** تحليل محتواها وترتيب خبراتها وأنشطتها وتوزيعها زمنياً على عدة حصص."],"pts":["أهميته: يوجه التنفيذ، ويضمن تحقيق الأهداف، ويحدد الزمن والوسائل، ويجنب العشوائية؛ وهو أساس **إدارة وقت الحصة**.","عناصر الخطة اليومية: الموضوع، **الأهداف**، المتطلبات السابقة، **التهيئة**، المحتوى والإجراءات، الاستراتيجيات، الوسائل، الأنشطة، **التقويم**، الغلق، الواجب، الزمن.","**الغلق** خطوة ختامية لتلخيص الأفكار الرئيسة وربطها وتثبيتها.","المهارات المعقدة تُخطط للتدرب عليها **مجزأة** ثم تُجمع، والتخطيط يراعي **الفروق الفردية** ومستوى التجريد لدى الطلاب."],"traps":["توزيع المقرر السنوي ليس من عناصر الخطة **اليومية**.","عند ضيق الوقت لا تُحوَّل الأنشطة كلها **واجبات**."]},"ar.l12.content":{"k":"التخطيط","t":["Content Analysis & Knowledge Pyramid","تحليل المحتوى وهرم المعرفة"],"body":["**تحليل المحتوى** تفكيك المادة إلى **حقائق ومفاهيم وتعميمات (مبادئ) ومهارات وقيم واتجاهات**؛ ويأتي بعد تحديد الأهداف وقبل اختيار الأنشطة."],"pts":["«الماء يغلي عند 100 درجة» **حقيقة**؛ «الضغط» **مفهوم**؛ «كلما زاد الضغط ارتفعت درجة الغليان» **تعميم**.","**هرم المعرفة**: الحقائق في القاعدة ← المفاهيم ← التعميمات (المبادئ) ← القوانين ← النظريات في القمة.","الانتقال من قاعدة الهرم إلى قمته **استقراء**، ومن الجزء إلى الكل."],"traps":["العلاقة بين مفهومين («كلما… ارتفع…») **تعميم** لا مفهوم."]},"ar.l12.homework":{"k":"التخطيط","t":["Homework","الواجبات المنزلية"],"body":["الواجب امتداد للدرس لا عقوبة: يرتبط بأهدافه، ويكون مناسب الكم، بتوجيهات واضحة، ويُصحح ويُعاد **بتغذية راجعة**."],"pts":["بعد جمع الواجبات: الإجراء الأنسب **الاطلاع عليها وتقديم تغذية راجعة**، لا رصد درجة فقط ولا تخزينها.","لا يُستخدم الواجب **عقاباً**."],"traps":["رصد الدرجة دون تعليق **لا يكفي**."]},"ar.l12.align":{"k":"المعايير ونواتج التعلم","t":["Standards, Outcomes & Alignment","معايير المنهج ونواتج التعلم والمحاذاة"],"body":["في الإطار الوطني لمعايير مناهج التعليم العام: **معايير المحتوى** وصف عام لما ينبغي أن يتعلمه المتعلم في كل مجال تعلم، و**معايير الأداء** تمثل **نواتج التعلم المتوقعة** في نهاية كل صف أو مستوى، أي ما يعرفه المتعلم ويفهمه ويستطيع أداءه."],"pts":["**نواتج التعلم** (لائحة تقويم الطالب 2025): ما يكتسبه الطالب من معارف ومهارات وقيم نتيجة مروره بخبرة تعليمية خلال دراسته مقرراً ما.","بنية المعايير: **البنية التخصصية** للمجال (البعد الرئيس)، ويدعمها **بعد المهارات** و**بعد القيم**.","مؤشر 10.1: يشتق من معايير المناهج أهداف تعلم وفق التصنيف المناسب والأبعاد المشتركة.","**التصميم العكسي** (ويغنز وماكتاي) يبدأ **بالنتائج المرغوبة** ← ثم **أدلة التقويم** ← ثم **خبرات التعلم**؛ عكس البدء بصفحات الكتاب.","التسلسل المنطقي يراعي **المتطلبات السابقة**، ومن البسيط إلى المركب، ومن المحسوس إلى المجرد، وبنية المادة؛ فلا يُقدَّم ناتج يعتمد على مهارة لم تُدرَّس."],"traps":["المحاذاة: الهدف والنشاط والتقويم تقيس **الشيء نفسه وبالمستوى المعرفي نفسه**."]},"ar.l12.resources":{"k":"مصادر التعلم","t":["Selecting Learning Resources","شروط اختيار مصادر التعلم الرقمية وغير الرقمية"],"body":["مؤشر 8.1 للممارس: **يضمّن خطة الدرس مجموعة متنوعة من أدوات ومصادر التعلم الرقمية وغير الرقمية تحقق شروط اختيار المصادر التعليمية**."],"pts":["الشروط: **الارتباط بالهدف** أولاً ← **المناسبة لخصائص المتعلمين** ← **الدقة العلمية والحداثة** ← **الوضوح وجودة الإخراج** ← **التوافق مع القيم والثقافة**.","ثم **الأمان** ← **تكلفة ووقت وجهد** يتناسب مع ما يحققه ← **الإتاحة وسهولة الوصول للجميع** بمن فيهم ذوو الإعاقة ← **احترام الملكية الفكرية**.","المصدر الرقمي يُقوَّم أيضاً بموثوقية الجهة الناشرة، وتاريخ التحديث، وخلوه من الإعلانات والمحتوى غير المناسب، وعمله على أجهزة المدرسة وشبكتها.","**يجرب المعلم المصدر قبل الحصة**، ويعد **بديلاً** عند تعطل التقنية.","**التنوع** (مطبوع، مجسم، فيديو، محاكاة، منصة رقمية، بيئة محلية) يراعي أنماط المتعلمين، دون تكديس مصادر كثيرة تشتت الانتباه."],"traps":["المعيار تحقيق الهدف بأقل جهد وكلفة، لا **الأحدث أو الأغلى**."]},"ar.l13.active":{"k":"التعلم النشط","t":["Interactive Classroom Strategies","استراتيجيات صفية تفاعلية"],"body":["مبادئ التعلم النشط: مشاركة فاعلة، وربط بالواقع، وتعاون، وتفكير عليا، وتغذية راجعة، ومراعاة الفروق، وتحمل الطالب مسؤولية تعلمه. وهذه استراتيجيات قصيرة تطبقها."],"pts":["**مراكز التعلم**: محطات في الصف أو الصالة تمر عليها المجموعات بالتناوب، والمعلم فيها **الميسّر** الذي يقدم الدعم عند الحاجة.","**الرؤوس المرقمة**: يُرقَّم أعضاء كل مجموعة ويُستدعى رقم عشوائي ليجيب عنها فيستعد الجميع؛ و**الأعواد** (أعواد الآيسكريم) سحب اسم طالب عشوائياً.","**حوض السمك**: دائرة داخلية تناقش (المشاركون) وخارجية تراقب وتدوّن (الملاحظون) ثم تتبادلان.","**نموذج فراير**: بطاقة رباعية للمفهوم (التعريف، الخصائص، أمثلة، لا أمثلة)؛ و**RAFT (رافت)**: كتابة يحدد فيها الطالب **الدور** و**الجمهور** و**الصيغة** و**الموضوع**.","**الكرسي الساخن**: أسئلة لطالب معين لتنمية بناء الأسئلة؛ و**شبكة الأسئلة**: جمع أسئلة الطلاب نهاية الحصة ومناقشتها لتصحيح المفاهيم البديلة."],"traps":["في الرؤوس المرقمة يجيب رقم **عشوائي** عن المجموعة، فيلتزم الجميع بالاستعداد."]},"ar.l13.models":{"k":"النماذج البنائية","t":["Constructivist & Metacognitive Models","نماذج بنائية وما وراء معرفية"],"body":["نماذج تشترك في أن الطالب يبني المعنى بنفسه أو مع زملائه، وكثير منها ينمي **ما وراء المعرفة**: وعي الطالب بتفكيره."],"pts":["**جدول التعلم KWL** ينشط المعرفة السابقة وينمي التفكير **ما وراء المعرفي**؛ و**التساؤل الذاتي**: ماذا أعرف؟ ما الذي لا أعرفه؟ كيف أتابع؟","**التعلم المنظم ذاتياً**: الطالب يخطط ويراقب ويقوّم تعلمه؛ وطلب وصف العمليات والصعوبات نهاية الدرس ينمي **التأمل والتوجيه الذاتي**.","**تنال القمر**: فهم قرائي بخمس خطوات: التنبؤ ← التنظيم ← البحث ← التلخيص ← المقارنة (تشبه التدريس التبادلي).","**التعليم التوليدي**: بنائي اجتماعي بأربعة أطوار: التمهيدي ← التركيزي ← **التحدي** ← التطبيق.","**نموذج التعلم البنائي الاجتماعي**: تمهيد ← اكتشاف ثنائي ← أنشطة تعاونية ← إتاحة الفرص ← **تقويم ذاتي**؛ يبدأ ثنائياً وينتهي فردياً بخلاف فكر‑زاوج‑شارك.","**نموذج بوسنر للتغير المفاهيمي** يعالج **التصورات البديلة (الخاطئة)**، والتغير نوعان: **تطوري** للخطأ البسيط، و**ثوري** حين يُستبدل المفهوم كله."],"traps":["فكر‑زاوج‑شارك يبدأ **فردياً**، والبنائي الاجتماعي يبدأ **ثنائياً**."]},"ar.l13.maps":{"k":"الخرائط","t":["Concept Maps vs Mind Maps","خريطة المفاهيم والخريطة الذهنية وأشكال فن"],"body":["**خريطة المفاهيم** (نوفاك) **هرمية** من العام في **القمة** إلى الخاص، مع **كلمات ربط** على الأسهم تكوّن جملاً ذات معنى، وتستند إلى نظرية **أوزوبل** في التعلم ذي المعنى. و**الخريطة الذهنية** (بوزان) فكرة مركزية وفروع شعاعية بألوان وصور تشبه الخلية العصبية."],"pts":["الذهنية: كلمات الربط لا تُشترط غالباً، وأساسها التفكير البصري والتذكر، وأنسب استخدام لها العصف والتلخيص.","المفاهيم: أنسب استخدام لها كشف العلاقات وتقويم الفهم.","**أشكال فن**: للمقارنة بين مفهومين؛ أوجه الشبه في التقاطع والاختلاف في الجانبين."],"traps":["الهرمية وكلمات الربط = **خريطة مفاهيم** (نوفاك)؛ الفروع الشعاعية الملونة = **ذهنية** (بوزان)."]},"ar.l13.platforms":{"k":"التقنية في التعليم","t":["Ministry Platforms","منصات الوزارة وأنظمة إدارة التعلم"],"body":["**نظام إدارة التعلم** منصة بدروس مسجلة وواجبات وتواصل يدخلها الطالب بحساب وكلمة مرور. ولكل منصة رسمية وظيفة تميزها في الأسئلة."],"pts":["**مدرستي**: المنصة الرسمية للتعليم الإلكتروني منذ 1442هـ؛ فصول افتراضية عبر تيمز، وواجبات واختبارات إلكترونية، وإثراءات.","**عين**: بوابة التعليم الوطنية بدروس ومحتوى رقمي للمناهج وقنوات عين الفضائية.","**نور**: نظام الإدارة التربوية للدرجات والغياب والشهادات وأولياء الأمور.","**روافد**: مستودع المصادر الرقمية؛ و**منظومة التعليم الموحد**: منصة التعلم عن بعد التي سبقت مدرستي."],"traps":["الدرجات والغياب في **نور**، والفصول الافتراضية في **مدرستي**."]},"ar.l13.mayer":{"k":"الوسائط المتعددة","t":["Mayer's Multimedia Principles","مبادئ ماير للوسائط المتعددة"],"body":["مبادئ لتصميم العروض والفيديو التعليمي تخفف العبء على ذاكرة المتعلم."],"pts":["التقارب **المكاني** (النص قرب الصورة) و**الزماني** (الصوت مع الصورة في الوقت نفسه).","**الاتساق**: حذف المشتتات والزخارف غير اللازمة.","**الصيغة**: تعليق صوتي مع الرسوم أفضل من نص مكتوب.","**التكرار الزائد**: لا يُعرض نص مكتوب مطابق للصوت نفسه.","**التجزئة**: تقسيم العرض إلى أجزاء يتحكم المتعلم في تتابعها؛ و**الشخصنة**: أسلوب حواري قريب."],"traps":["قراءة الشرائح نصاً بالصوت نفسه تخالف مبدأ **التكرار الزائد**."]},"ar.l13.design":{"k":"التقنية في التعليم","t":["Instructional Design & Learning Resources","التصميم التعليمي وتقنيات التعليم ومصادر التعلم"],"body":["**التصميم التعليمي** مدخل منظم لتخطيط التعليم وتطويره وتقويمه، وأشهر نماذجه **ADDIE**: تحليل ← تصميم ← تطوير ← تنفيذ ← تقويم."],"pts":["**تقنيات التعليم**: منظومة متكاملة من الإنسان والأجهزة والطرق لتحقيق الأهداف.","**مصادر التعلم**: كل ما يتفاعل معه المتعلم من أنظمة وقنوات وموارد بشرية وغير بشرية لاكتساب الخبرة.","**التعلم المتنقل**: عبر **الأجهزة المحمولة** دون قيد مكان أو زمان."],"traps":["ADDIE يبدأ **بالتحليل** وينتهي **بالتقويم**."]},"ar.l13.tools":{"k":"التقنية في التعليم","t":["Web Tools, Apps & Digital Citizenship","أدوات الويب والتطبيقات والمواطنة الرقمية"],"body":["التقنية تُقاس بما تضيفه إلى التعلم لا بحداثتها. ومن مميزات الحاسب في التعليم: السرعة الذاتية، والاعتماد على النفس، والجمع بين الترفيه والتعليم."],"pts":["**الرحلات المعرفية (ويب كويست)**: بحث جماعي في **مصادر يحددها المعلم مسبقاً**؛ بنيتها مقدمة، مهمة، عملية، مصادر، تقويم، خاتمة.","**الحوسبة السحابية**: تخزين الملفات والتطبيقات على الإنترنت والوصول إليها من أي جهاز (قوقل درايف، ون درايف، دروب بوكس)؛ تناسب **دمج ملفات** ومستندات مشتركة.","**المدونة** للنشر والتعليق، و**الويكي** يحررها عدة مستخدمين، و**البودكاست** صوتي، و**الفيديو التفاعلي** للتعلم الفردي، و**الواقع المعزز** يضيف عناصر رقمية إلى الواقع.","**إكسل** للجداول والرسوم والإحصاء البسيط و**SPSS** للتحليل الإحصائي، و**أكسس** لقواعد البيانات، و**كانفا** للتصميم، و**بوبلت** للخرائط المعرفية، و**كاهوت** للألعاب التفاعلية.","**المواطنة الرقمية** (**الثقافة الرقمية**): قواعد توجه نحو منافع التقنية والحماية من أخطارها، والاستخدام الآمن والأخلاقي وتقويم مصداقية المصادر.","معايير **ISTE** دولية لتوظيف التقنية (للطلاب والمعلمين والقادة)، و**الذكاء الاصطناعي** للتعلم التكيفي والتغذية الراجعة الآلية مع تحقق المعلم من دقته."],"traps":["الويب كويست مصادره **محددة مسبقاً** لا بحث حر."]},"ar.l13.currorg":{"k":"المنهج","t":["Curriculum Organization & Design Models","تنظيمات المنهج ونماذج بنائه"],"body":["**المنهج بمفهومه التقليدي** المقرر والكتاب وحفظ المعلومات وإهمال الفروق، و**بمفهومه الحديث** جميع الخبرات التي تهيئها المدرسة داخلها وخارجها وتراعي المتعلم. و**المقرر** موضوعات مادة معينة، و**الكتاب المدرسي** وعاء المحتوى والوسائل والأنشطة، و**المحتوى** المعارف والمفاهيم والمهارات والقيم."],"pts":["التنظيمات: **المواد المنفصلة**، **المترابطة** (تنسيق بين مادتين مع بقائهما)، **المندمجة** (الاجتماعيات)، **المجالات الواسعة** (العلوم العامة)، **المحوري** (محور مشترك ومواد اختيارية).","و**النشاط** (ديوي: ميول الطلاب وحل المشكلات)، و**الوحدات**، و**الحلزوني** (برونر: المفاهيم تعود بتعمق)، و**المنهج التكنولوجي** (تقنية تنظم الخبرات ويعتمد على **الخطو الذاتي**).","**التنظيم المنطقي**: من البسيط (السهل) إلى المعقد، ومن القديم إلى الحديث، ومن المحسوس إلى المجرد؛ و**التنظيم السيكولوجي**: وفق خصائص المتعلم وحاجاته وميوله.","**نموذج تايلر** (1949) أربعة أسئلة: ما الأهداف؟ ما الخبرات؟ كيف تُنظم؟ كيف نقوّم؟ وهو أيضاً صاحب نموذج **تقويم المنهج**.","**نموذج تابا** استقرائي يبدأ **من المعلم**: تشخيص حاجات الطلاب ← صياغة الأهداف ← اختيار المحتوى وتنظيمه ← الخبرات ← التقويم.","**المنهج كنظام**: **مدخلات** (أهداف ومحتوى) ← **عمليات** (طرق وأنشطة ووسائل) ← **مخرجات** (نواتج التعلم) ← **تغذية راجعة** (تقويم)."],"traps":["تايلر يبدأ **بالأهداف**، وتابا **من المعلم** بتشخيص الحاجات."]},"ar.l14.styles":{"k":"إدارة الصف","t":["Management Styles, Rules & Time","أنماط الإدارة والقواعد الصفية وإدارة الوقت"],"body":["إدارة الصف الفعالة تهيئ الفرص للطلاب ليصبحوا **متعلمين مدى الحياة** في تعلم تعاوني يسوده **الاحترام والتشجيع**. والنمط **الديمقراطي** (حوار، مشاركة، أمن نفسي، انضباط ذاتي) هو الأنسب، و**التسلطي** يولد الخوف والطاعة التامة والاتكالية والدافعية الخارجية، و**الفوضوي/المتساهل** ضعف شخصية بلا ضوابط وضياع للوقت."],"pts":["**القواعد الصفية**: قليلة (3–5)، واضحة، إيجابية الصياغة، توضع **مع الطلاب في بداية العام**، تُراجع عند الحاجة، و**متسقة مع قواعد الانضباط التي أقرتها الوزارة**.","**اشرح للطلاب فوائدها** واتفق عليها معهم حتى يطبقوها **ذاتياً**؛ فالانضباط (تنظيم ذاتي) أعلى من النظام (مصدره خارجي)، وهذه **الإدارة الذاتية للصف**.","**الوقت الأكاديمي**: إجراءات روتينية لبدء الحصة وإنهائها، و**انتقالات** سلسة، وتهيئة قصيرة؛ تقل المشكلات حين **ينهمك الطلاب في النجاح**.","**التنظيم الفيزيائي**: المقاعد حسب **نوع النشاط** (صفوف للعرض، مجموعات للتعاون، حرف U للنقاش)، والمعلم **يرى جميع الطلاب** ويتحرك بينهم.","المجموعات: 4–6 أعضاء بأدوار (قائد، مقرر، ضابط وقت، متحدث)، مسؤولية فردية مع اعتماد إيجابي متبادل؛ والمعلم **ميسّر** ومرشد لا ملقّن ولا متفرج.","**الأزمة الصفية**: **الهدوء**، وفصل المتسببين، وشغل البقية بنشاط، ثم المعالجة الفردية بعد الحصة؛ وعند الملل تغيير أسلوب العرض مع التحرك والإيماءات."],"traps":["الود الزائد حتى تضيع الضوابط = **الفوضوي** لا الديمقراطي.","لا تترك الصف بلا قواعد ولا تجعل لكل طالب قواعده الخاصة."]},"ar.l14.othermod":{"k":"تعديل السلوك","t":["Other Behavior-Change Techniques","أساليب أخرى في تعديل السلوك"],"body":["إلى جانب التعزيز والعقاب أساليب يميزها تفصيل واحد في السؤال: هل نزيل الأثر؟ هل نغير المكان؟ هل نساعد الطالب بتلميح؟"],"pts":["**التصحيح البسيط**: إزالة أثر الخطأ فقط (تنظيف ما سكبه)؛ **التصحيح الزائد**: إزالة الأثر مع أعمال إضافية (اعتذار وإحضار مقعد جديد، تنظيف بقية الفصل).","**التلقين**: تلميح لفظي أو إيمائي أو جسدي (الإمساك بيد الطفل ليرسم الحرف)؛ و**السحب التدريجي/التلاشي**: تدرج في المثير أو المساعدة؛ و**التسلسل**: تعزيز كل حلقة في سلسلة سلوكية.","**ضبط المثير**: تغيير البيئة أو المكان (نقل الطالب الثرثار)؛ و**النمذجة** مثل نقل الطالب بجوار قرين متفوق محبوب.","**التحصين التدريجي** للخجول خطوة خطوة مقابل **الغمر** دفعة واحدة؛ و**الكف المتبادل**: إحلال عادة مقبولة محل أخرى؛ و**الإشباع**: تقديم المثير بكميات كبيرة حتى يفقد جاذبيته.","**ضبط الذات** (تقييد النفس كالحمية)، و**السلوك التوكيدي** (تعليمات تبني ثقة الطالب بنفسه)، و**الإرشاد بالواقع** (توظيف القراءة والأنشطة الواقعية)؛ و**العقد السلوكي** اتفاق مكتوب بالسلوك والمكافأة.","**النشاط التعزيزي** نشاط إضافي لمن أتقن لتثبيت التعلم وتعميقه، و**النشاط العلاجي** لمن لم يتقن."],"traps":["إزالة الأثر مع عمل إضافي = **تصحيح زائد**.","نقل الطالب الثرثار من مكانه = **ضبط المثير**."]},"ar.l14.cases":{"k":"بيئة آمنة","t":["Handling Student Cases","التعامل مع فئات الطلاب والمشكلات السلوكية"],"body":["لكل حالة خطوة أولى تعالج سببها لا مظهرها، دون إحراج علني."],"pts":["**العنف** لأول مرة: تنبيه المعتدين بأن السلوك مرفوض وله عواقب تأديبية إن تكرر؛ تبليغ الإدارة والأهل خطوة لاحقة، وتعليم المهارات الاجتماعية إجراء عام لا يعالج الموقف الحاضر.","**المعتدى عليه** (في التنمر): بناء ثقته وتعليمه مهارات اجتماعية وضمان حمايته؛ لا لومه ولا مواجهته مع المتنمر أمام الصف، ولا يُعالج التنمر بطلب النقل أو التجاهل.","**الخجول**: علاقة ثقة أولاً، ثم مهام سهلة ناجحة، وتواصل **غير لفظي** مشجع، وتحصين تدريجي؛ والخطأ **تجنب سؤاله** أو الزج به أمام الجميع أو تحويله فوراً للمرشد.","**كثير الحركة**: مقعد قريب من المعلم، ومهام فيها حركة مشروعة، وأنشطة قصيرة متنوعة؛ لا حرمانه من الحركة كلياً ولا من الفسحة.","**المشاغب أو المتحدي**: لقاء فردي بود وحزم لفهم السبب، لا مواجهة علنية، ثم اتفاق سلوكي وعواقب ثابتة؛ و**المحبط قليل الدافعية**: استكشف سبب إحجامه، ثم مهام متدرجة ونجاح مبكر وتعزيز الجهد.","أنجز ثم أساء: «حلك صحيح، وضرب زميلك خطأ يستحق العقاب»؛ لا تلغِ أحدهما بالآخر ولا تصفه بصفة سلبية. و**التدخين** ليس تجاهلاً ولا توبيخاً علنياً ولا اتصالاً انفعالياً بالوالد؛ يُبلّغ **المرشد الطلابي والإدارة**."],"traps":["الخطوة الأولى مع الخجول **بناء الثقة** لا تحويله للمرشد.","الطالب المعتدى عليه **لا يُلام**."]},"ar.l14.comm":{"k":"التواصل","t":["Classroom Communication","الاتصال الصفي ولغاته ومعوقاته"],"body":["عناصر الاتصال التعليمي: **مرسل، رسالة، قناة، مستقبل، تغذية راجعة**. والاتصال **اللفظي** بالكلام أو الكتابة، و**غير اللفظي** ثلاث لغات: **لغة الجسد** (تعبيرات وتواصل بصري)، و**اللغة التقاربية** (المسافة والقرب من الطالب)، و**اللغة الموازية** (نبرة الصوت وسرعته)."],"pts":["أنماطه: **وحيد الاتجاه** (محاضرة)، **ثنائي** (معلم وطالب)، **متعدد/مفتوح** (تفاعل الجميع بتوجيه المعلم) وهو الأفضل.","الأسئلة الصفية: **مغلقة** (إجابة واحدة)، **مفتوحة** (تفكير متباعد)، **سابرة** (تبني على إجابة الطالب)، **تجميعية** (تجمع عدة أفكار).","معوقات التفاعل و**معوقات الاتصال**: **خوف الطلاب من الخطأ**، والتعزيز غير المناسب، ومقاطعة المعلم، والتوقعات المنخفضة، وشرود الذهن، والضجيج، وغموض الرسالة؛ والعلاج تنويع المثيرات والأسئلة.","**الإنصات النشط**: إيماء وإعادة صياغة وعدم مقاطعة في جو **دافئ متقبل** يحقق الأمن النفسي؛ والمتحدث الجيد: **ضبط الانفعال**، ووضوح، ونبرة متنوعة، ولا استطراد.","وظائف التغذية الراجعة: **تعزيزية**، و**إخبارية**، و**دافعية**، وتقويمية؛ وصفاتها: فورية، محددة، وصفية، للأداء لا للشخص، مستمرة؛ و**التخطيط باللونين**: الوردي لما حقق المعايير والأصفر لما يحتاج تحسيناً.","**احترام التنوع**: إشراك كل طالب وتحيته باسمه، ولا تجميع حسب الخلفيات؛ والتواصل الرقمي بمجموعات افتراضية **تحت إشراف المعلم وتوجيهه**."],"traps":["الأنسب للتنبيه دون إحراج **غير اللفظي**.","الإجابة الخاطئة لا تُنقل فوراً لطالب آخر."]},"ar.l14.choose":{"k":"مواقف المعيار التاسع","t":["Choosing the Best Option","قواعد اختيار البديل في المواقف الصفية"],"body":["منطق الهيئة: السلوك البسيط **أول مرة** يعالجه المعلم بنفسه (تجاهل مقصود أو تنبيه هادئ على انفراد مع توضيح العواقب)، و**المتكرر** عواقب اللائحة وإشراك المرشد، و**الخطر** المرشد والإدارة فوراً."],"pts":["سلم التصعيد: **أول حادثة** ← المعلم؛ **متكررة أو خطرة** ← المرشد والإدارة وولي الأمر؛ **خارج صلاحية المعلم** (طبي، نفسي، قانوني، ولي أمر بحالة غير طبيعية) ← الإدارة.","الإجراء العام (نموذج سلوك للجميع) أو الوقائي (تعليم مهارات) أو التصعيدي (تبليغ) خطوات لاحقة لا أولى.","البديل الذي يركز على **أثر الإجراء في الطالب** يسبق ما يركز على راحة المعلم أو سير الدرس.","أي بديل فيه إهانة أو عقاب جماعي أو طرد خطأ دائماً.","البيئة الإيجابية تبدأ **بالعلاقة** (تحية، أسماء، احترام) قبل الأدوات والعقوبات.","قاعدة التوقيت: التعزيز والتغذية الراجعة **فورية**، والتصحيح المحرج **مؤجل وخاص**؛ ومع ولي الأمر لا تبدأ بشرح وجهة نظرك ولا بمراجعة القوانين."],"traps":["تعليم الصف كله مهارات اجتماعية إجراء **عام** لا خطوة أولى."]},"ar.l14.ethics":{"k":"القدوة والعلاقة المهنية","t":["Role Model & Professional Boundaries","القدوة وحدود العلاقة المهنية والتراجع عن الخطأ"],"body":["مؤشر 9.2 للممارس: **يظهر القدوة الحسنة في السلوك، ويبقي علاقته مع المتعلمين ضمن حدود العلاقات المهنية، ويتراجع عن الخطأ ويصححه عند حدوثه**. وتمنع القواعد الإيذاء والسخرية و**تكليفه بنسخ الواجب عدة مرات عقاباً** وإقصاءه خارج الصف."],"pts":["**القدوة**: اتساق ما يطلبه المعلم مع ما يفعله (الالتزام بالوقت، ضبط الانفعال، احترام الطلاب، الأمانة)؛ فالطلاب يتعلمون بالملاحظة أكثر من التوجيه اللفظي.","**حدود العلاقة المهنية**: علاقة ودودة **عادلة** قائمة على الاحترام، دون محاباة أو تمييز، ودون تواصل شخصي خارج القنوات المعتمدة، ودون إفشاء أسرار الطلاب أو مزاح يمس الكرامة.","**التراجع عن الخطأ**: إذا أخطأ في معلومة أو حكم أو درجة **يعترف ويصحح** في أقرب وقت أمام من وصلهم الخطأ؛ وإذا أساء إلى طالب أمام زملائه فالأنسب **الاعتذار** بما يحفظ كرامته.","دوره في قواعد 1447: **تمثيل القدوة الحسنة للسلوك الإيجابي في القول والفعل**، وتعزيز الانضباط الذاتي، وتوضيح القواعد، وتعديل السلوك بالاستفادة من التوجيه الطلابي.","ومن دوره: توثيق مشكلات الانضباط في سجلات خاصة، و**رصد الحضور في كل حصة**، و**تمكين الطالب من فرص التعويض**، وطلب المشورة من لجنة التوجيه الطلابي.","**يرصد المعلم مشكلات الدرجة الثانية فأعلى** التي باشرها ويسلم الأسماء للإدارة، ومثالها الدخول أو الخروج من الفصل دون استئذان؛ أما التأخر في دخول الحصة والنوم في الفصل فمن الدرجة الأولى."],"traps":["الإجراءات الثلاثة الأولى: تنبيه شفهي ← تنبيه ثانٍ مع حصر الأسباب ← تدوين وتوقيع وإشعار ولي الأمر وحسم تنفذه الإدارة."],"src":"قواعد السلوك والمواظبة لطلبة التعليم العام (الإصدار الخامس 1447هـ)؛ المعايير التربوية العامة."},"ar.l14.safety":{"k":"الأمن والسلامة","t":["Classroom Safety & Emergencies","السلامة في الصف والمختبر والطوارئ"],"body":["مؤشرا 9.3 للممارس: **يتأكد من جاهزية مصادر التعلم وإمكانية وصول جميع المتعلمين إليها بما في ذلك التقنية الرقمية وتقنية المعلومات**، و**يهيئ البيئة التعليمية بطريقة تحقق عوامل الأمن والسلامة**."],"pts":["**الجاهزية** و**إتاحة الوصول للجميع**: عدد كافٍ من الأدوات أو **تناوب عادل**؛ وموقع يرى منه الجميع، وخط مكبر لضعيف البصر، ونص مرافق للفيديو لضعيف السمع، وممرات خالية للكرسي المتحرك، وبدائل لمن لا يملك جهازاً.","**السلامة في الصف**: ممرات واسعة، ومخارج غير مسدودة، وأثاث ثابت، وتوصيلات آمنة، وتهوية وإضاءة مناسبتان، وأدوات خطرة محفوظة.","**الإخلاء**: معرفة المسار ونقطة التجمع وتدريب دوري؛ وعند الإنذار **الهدوء** وإخراج الطلاب بانتظام **دون أخذ الحقائب** ثم **التحقق من العدد**.","**المختبر**: تعليمات قبل التجربة، و**نظارات وقفازات واقية**، ولا أكل ولا شرب ولا تذوق ولا شم مباشر، ومواد **موسومة**، ومعرفة مكان **طفاية الحريق** و**حقيبة الإسعافات الأولية**، و**إشراف دائم**.","عند **الإصابة أو الخطر**: **إيقاف الخطر وحماية الطلاب أولاً**، ثم الإسعاف في حدود التدريب، ثم إبلاغ الإدارة وولي الأمر والتوثيق، و**استدعاء الهلال الأحمر** عند الحاجة؛ ومعرفة **الحالات الصحية** (ربو، حساسية، سكري، صرع) بالتنسيق مع الموجه الصحي.","**محاولة إيذاء الذات** (المادة 30): الهدوء وأخذ كلامه بجدية، وتجنب كثرة الأسئلة، ومكان آمن و**عدم تركه بمفرده**، وحفظ خصوصيته، والتبليغ فوراً (إدارة التعليم، الجهات الأمنية، الحماية من العنف الأسري وحماية الطفل 1919، وزارة الصحة)."],"traps":["عند الحريق لا تُؤخذ **الحقائب**.","أول إجراء عند الإصابة **إيقاف الخطر** لا الاتصال بولي الأمر."],"src":"قواعد السلوك والمواظبة لطلبة التعليم العام (الإصدار الخامس 1447هـ)؛ المعايير التربوية العامة."},"ar.l15.eval":{"k":"مفاهيم التقويم","t":["Educational Evaluation: Qualities & Functions","التقويم التربوي: خصائصه ووظائفه"],"body":["التقويم التربوي يشمل تقويم المتعلم والمعلم والمنهج والإدارة والمبنى، والتقويم التعليمي جزء إجرائي منه. والحكم على درجات الطلاب في ضوء معيار الوزارة ثم كتابة وسائل تعزز مستواهم = **تقويم تربوي** (حكم + علاج)، لا قياس ولا تقييم فقط."],"pts":["خصائص التقويم الجيد: مستمر، شامل لجوانب المتعلم، تعاوني، علمي (صادق وثابت وموضوعي)، اقتصادي، وليس نشاطاً ختامياً فقط.","**مواصفات الاختبار الجيد**: الصدق، الثبات، الموضوعية، **التمييز**، **الشمول** (تغطية المحتوى وفق جدول المواصفات)، والتقنين، وسهولة التطبيق والتصحيح.","**وظائف التقويم**: تشخيص الضعف، وتوجيه التعلم، والحكم على الأهداف، وتطوير المناهج وطرق التدريس، ودعم القرارات الإدارية."],"traps":["الحكم مع وسائل علاجية = **تقويم** لا تقييم."]},"ar.l15.tools":{"k":"أدوات التقويم","t":["Other Assessment Tools","أدوات تقويم أخرى: السجلات والملاحظة والمقابلة والتقارير الذاتية"],"body":["كل أداة تكشف جانباً لا يكشفه الاختبار الورقي؛ فاختر الأداة بحسب ما تريد قياسه."],"pts":["**السجل القصصي**: وصف دقيق مؤرخ لسلوك طالب في موقف محدد كما حدث؛ من عيوبه الوقت الطويل وتأثره بذاتية الملاحِظ. و**سجل سير التعلم (اليوميات)** يكتب فيه الطالب تأملاته.","**الملاحظة** أنسب لتقويم المهارات العملية والسلوك، بسيطة أو منظمة بأداة (بطاقة ملاحظة)؛ و**المقابلة / المؤتمر** تواصل وجهاً لوجه حول أعمال الطالب وتفكيره.","**تقويم الأقران** يعتمد على نشاطين رئيسيين: **الملاحظة** و**التواصل**، وهو مكمل للتقويم الذاتي.","**التقارير الذاتية** للنواتج **الوجدانية**: مقاييس **الاتجاهات** (ليكرت الخماسي)، ومقاييس **الميول** (سترونج وكودر)، والاختبارات الإسقاطية، والمقابلة المقيدة أو المفتوحة.","**الاختبارات الشفوية**: أنسب للصفوف الأولية ومواد كالقرآن الكريم، ينعدم فيها الغش وتكشف التعبير، لكنها تستغرق وقتاً وتتأثر بذاتية المعلم وخوف الطالب."],"traps":["الاتجاهات والميول تُقاس **بالتقارير الذاتية** لا بالاختبار التحصيلي."]},"ar.l15.essay":{"k":"أنواع الأسئلة","t":["Essay Questions","الأسئلة المقالية"],"body":["**المقالية** نوعان: **المقيدة** تحدد المطلوب ونطاق الإجابة، و**الحرة (المفتوحة)**. تقيس تنظيم الأفكار والتعبير والتكامل والتفكير العليا، وهي سهلة الإعداد ولا تخمين فيها، لكن تصحيحها ذاتي فينخفض ثباتها، وتغطي محتوى محدوداً."],"pts":["تقييد السؤال («اذكر ثلاثة أسباب») يرفع موضوعية التصحيح؛ والسؤال المفتوح بلا تحديد يصعب تصحيحه.","الموضوعية في المقابل تغطي المحتوى وسهلة التصحيح، لكنها تحتاج وقتاً في الإعداد ولا تقيس التعبير والتنظيم."],"traps":["الموضوعية: الاختيار من متعدد، والصواب والخطأ، والمطابقة، و**الإكمال (التكملة)** فقط."]},"ar.l15.build":{"k":"بناء الاختبار","t":["Building an Achievement Test","خطوات بناء الاختبار التحصيلي وتصحيحه"],"body":["الخطوات بالترتيب: **تحديد الأهداف** ← تحليل المحتوى ← جدول المواصفات ← صياغة الفقرات ← التعليمات ← التجريب والتحليل. والخطوة الأولى دائماً **تحديد الأهداف التعليمية المراد قياسها**، لا كتابة الأسئلة ولا تحليل المحتوى."],"pts":["التعليمات تتضمن الزمن، وطريقة الإجابة ومكانها، ودرجة كل سؤال، وتنبيهات التخمين.","تصحيح المقالي: نموذج إجابة ومحكات تصحيح (قواعد كلية أو تحليلية بوزن لكل محك) تُعد قبل التصحيح، وتصحيح السؤال الواحد لكل الطلاب قبل غيره، وإخفاء الأسماء.","التصحيح بمعيار واحد للجميع؛ وظرف الطالب الشخصي يُعالج بطرق تربوية أخرى لا برفع درجته.","اختبار المعلم هو الأنسب لقياس تمكن طلابه من محتوى درسوه في فترة محددة، والمقنن لمقارنات أوسع.","ترتيب الفقرات من السهل إلى الصعب يشجع متدني التحصيل على الاستمرار ويقلل القلق."],"ex":["معلمة وجدت أن اختبارها الماضي فيه 15 سؤالاً من الدرس الأول و3 فقط من بقية الوحدة: خلل في صدق المحتوى، وعلاجه بناء جدول مواصفات بأوزان الدروس قبل كتابة الأسئلة."],"traps":["الخطوة الأولى **تحديد الأهداف** لا الجدول ولا الأسئلة."]},"ar.l15.intl":{"k":"الاختبارات الوطنية والدولية","t":["National & International Assessments","نافس والاختبارات الدولية"],"body":["**نافس** الاختبارات الوطنية التي تنفذها هيئة تقويم التعليم والتدريب لقياس مخرجات التعلم في القراءة والرياضيات والعلوم للصفوف 3 و6 و9؛ غرضها تشخيص المستوى الوطني وتحسين التعليم لا ترتيب الطالب أو نجاحه."],"pts":["**PISA** (بيزا) من منظمة OECD، لعمر 15 سنة، كل 3 سنوات، يقيس تطبيق المعرفة في القراءة والرياضيات والعلوم في مواقف حياتية.","**TIMSS** (تيمس) من IEA، للصفين الرابع والثامن (الثاني متوسط)، كل 4 سنوات، في الرياضيات والعلوم.","**PIRLS** (بيرلز) للصف الرابع، كل 5 سنوات، في مهارات القراءة والاستيعاب.","**TALIS** مسح دولي عن المعلمين وبيئات التدريس وليس اختباراً للطلاب."],"traps":["PISA بالعمر (15 سنة)، وTIMSS وPIRLS **بالصف**."]},"ar.l15.formal":{"k":"خطة التقويم","t":["Formal & Informal Assessment, Assessment Cycles","التقويم الرسمي وغير الرسمي ودورتا التقويم"],"body":["مؤشر 10.1 للممارس: **يعد خطة تقويم وفقاً للمبادئ الصحيحة توضح ما سيقوم به لتمثيل أساليب التقويم الرسمي والاعتيادي، ولتحقيق أغراض التقويم الأساسية خلال دورتي التقويم الطويلة والقصيرة المدى**."],"pts":["**الرسمي**: مخطط له، **منظم وموثق**، بشروط وزمن ودرجة (اختبار قصير، اختبار نهاية الفترة، مشروع بسلم تقدير)؛ تُرصد نتائجه ويُبنى عليه حكم.","**غير الرسمي (الاعتيادي)**: يجري **تلقائياً أثناء التدريس** دون إعلان أو درجة غالباً (الملاحظة، الأسئلة الشفهية، بطاقة الخروج، الإشارات، السبورات الصغيرة)؛ غرضه **تعديل التدريس فوراً**.","**قصيرة المدى**: داخل الحصة أو بين حصة وأخرى، دليل سريع يعقبه تعديل أو تغذية راجعة؛ و**طويلة المدى**: الوحدة والفترة والعام، تقيس تحقق النواتج وتوجه الخطط العلاجية والإثرائية والتقارير.","**خطة التقويم** تحدد لكل ناتج تعلم: ماذا يُقوَّم، وبأي أداة، ومتى، وكيف يُصحح، وكيف تُوظف النتائج، مع **توزيع الدرجات**.","لائحة 2025: **التقويم القبلي (التشخيصي)** في بداية العام أو الفترة أو الوحدة أو الدرس، و**التكويني** عمليات مستمرة لتجويد التعلم، و**الختامي** في ختام فترات التعلم للحكم على المستوى.","**النسبة الشرطية لا تُطبق على اختبار الدور الثاني**، ويستمر تحسين درجات أدوات التقويم التكوينية حتى بدء اختبارات نهاية الفترة."],"traps":["الخطة الجيدة **تجمع بين الرسمي وغير الرسمي** ولا تعتمد على الاختبار وحده."],"src":"المعايير التربوية العامة؛ لائحة تقويم الطالب 2025 وإجراءاتها التنفيذية."},"ar.l15.access":{"k":"تقويم ذوي الإعاقة","t":["Test Accommodations","تسهيلات الاختبار وتقويم الطلاب ذوي الإعاقة"],"body":["**التسهيلات (المواءمات)** تغيّر **طريقة** تقديم الاختبار أو الاستجابة أو المكان أو الزمن، ويبقى المستوى المقيس كما هو؛ أما **التعديل** فيغيّر محتوى التقويم أو مستواه وفق **الخطة التربوية الفردية**."],"pts":["عامة: **الزمن الكافي** المناسب لقدرات الطالب، و**مكان مناسب** فردي أو جماعي، و**مرونة المواعيد** بالتنسيق مع الإدارة، و**تجزئة** المادة أو الاختبار.","**البصرية**: برايل، أو الشفهي، أو التسجيل الصوتي، أو **قارئ كاتب مبصر**، و**الطباعة المكبرة والعدسات** لضعاف البصر، وتكييف الصور والرسوم أو بديل لها.","**السمعية**: أسئلة **موضوعية مباشرة واضحة** بدل المقالية والمركبة، وترجمة بلغة الإشارة، و**عدم محاسبة الأصم على الأخطاء الإملائية والنحوية**، واستبدال مهارات الاستماع بنصوص أو صور.","**صعوبات التعلم**: قراءة الأسئلة بصوت عال، والإجابة **شفهياً** أو كتابتها عنه أو تسجيلها، و**فترات راحة**، وتقويم فردي بعيد عن المشتتات؛ و**فرط الحركة**: **فترات قصيرة**، والسماح **بالتوقف والتحرك**، والاختبار في **ركن خاص بعيد عن المشتتات**.","**الجسمية**: الأجهزة التعويضية، وإجابة شفهية يكتبها أحد منسوبي المدرسة الموثوقين بتكليف من المدير، وإعفاء من التقويمات العملية والرسم الكتابي؛ و**اضطرابات النطق**: لا يُحاسب على أخطائها، ويمكن استبدال الشفهي بالتحريري.","يتولى **معلم التربية الخاصة** الإشراف بالتعاون مع معلم التعليم العام وتُعد الأسئلة بالتشاور؛ ومن لم يستفد من الفصل العام **يُقوَّم في محتوى خطته الفردية**؛ ومن مرتكزات اللائحة **توافر فرص متكافئة لجميع الطلاب في أساليب التقويم وأدواته وظروف تطبيقه**."],"ex":["طالب ذو صعوبة في القراءة يُختبر في الرياضيات: يقرأ له المعلم الأسئلة في غرفة هادئة مع وقت إضافي، والمسائل نفسها لم تتغير؛ هذا تسهيل لا تعديل. أما أسئلة من محتوى خطته الفردية فتعديل."],"traps":["التسهيل لا يخفض **المستوى المقيس**؛ تغيير المحتوى **تعديل**."],"src":"لائحة تقويم الطالب 2025 وإجراءاتها التنفيذية؛ المعايير التربوية العامة (مؤشر 10.2)."},"ar.l16.corr":{"k":"الإحصاء","t":["Correlation Coefficient","معامل الارتباط"],"body":["**معامل الارتباط** يصف العلاقة بين متغيرين، ويتراوح بين −1 و+1: الإشارة تحدد الاتجاه (طردي / عكسي)، والقيمة المطلقة تحدد القوة."],"pts":["أقل من 0.3 ضعيف، و0.3 إلى 0.7 متوسط، وفوق 0.7 قوي.","يُستخدم في الثبات (ارتباط التطبيقين أو النصفين) وفي صدق المحك (ارتباط الاختبار بالمحك).","**الارتباط لا يعني السببية**: ارتباط قوي بين الحضور والتحصيل لا يثبت أن أحدهما سبب للآخر."],"traps":["ارتباط −0.8 **أقوى** من +0.5؛ الإشارة للاتجاه فقط."]},"ar.l16.use":{"k":"توظيف النتائج","t":["Using Assessment Results","توظيف نتائج التقويم والتقارير"],"body":["التغذية الراجعة الفعالة محددة ووصفية، تركز على المهمة لا على شخص الطالب، تذكر نقاط القوة ثم ما يُحسَّن، بلغة بسيطة موجزة، ولا تقتصر على الثناء العام ولا على نقاط الضعف."],"pts":["**خصائص التغذية الراجعة** الجيدة: الفورية، و**الدوام والاستمرارية**، و**الشمولية** لجوانب الأداء، والتحديد، والتركيز على المهمة لا الشخص.","يُفضل تقديمها **في الحصة التالية للاختبار** مباشرة لا في نهاية الفصل؛ والأقرب زمنياً أفضل عموماً.","تقرير ولي الأمر يوضح مستوى الطالب وتقدمه ونقاط قوته وما يحتاجه من دعم، بلغة واضحة بعيداً عن المقارنة بالآخرين.","تُستخدم النتائج لتعديل الخطة والتدريس وتصنيف الطلاب وتوجيههم وإعداد التقارير، ولا تُستخدم أداة عقاب.","تحليل الاختبار بالجداول الإلكترونية يسرّع حساب الصعوبة والتمييز والمتوسطات ويكشف الفقرات الضعيفة لتحسين الاختبارات القادمة."],"traps":["الإجراء الأول عند تدني نتائج الصف **تحليل النتائج** لا إعادة الاختبار."]},"ar.l16.records":{"k":"سجلات الرصد","t":["Record-keeping & Data Analysis","سجلات الرصد وتحليل النتائج ببرامج الجداول"],"body":["مؤشر 10.3 للممارس: **يعد نماذج رصد إنجازات المتعلمين ونتائجهم التراكمية ومدى تقدمهم خلال الفصل أو العام، ويستخدم بعض البرامج التقنية لتحليل البيانات واستخلاص المؤشرات الأساسية للأداء**."],"pts":["الصفان الأول والثاني: يُقوَّم الطالب **من بداية الفترة**، ويدوّن المعلم تقويمه **بشكل يومي في سجل متابعة تقويم الطالب**، ويرصد الخلاصة في النظام الرقمي نهاية الفترة موثقة في **ملف إنجاز الطالب** (جمع منظم وهادف لشواهد تعلمه).","نموذج الرصد الجيد: صف لكل طالب، وأعمدة **بالمعايير أو نواتج التعلم** والأداة والتاريخ، ومستوى الإتقان أو الدرجة، وعمود للملحوظات والإجراء العلاجي؛ و**الرصد التراكمي** يُظهر **مسار تقدم** الطالب (قبلي ← تكويني ← ختامي).","بالجداول: المتوسط والوسيط والانحراف، و**نسبة الإتقان لكل معيار** = عدد المتقنين ÷ عدد الطلاب، و**نسبة التحسن** بين القبلي والبعدي، و**التنسيق الشرطي** لتلوين غير المتقنين، و**الرسوم البيانية** للمقارنة.","**المؤشرات الأساسية للأداء**: نسبة الإتقان في كل معيار، وتوزيع الطلاب على المستويات، وأضعف المعايير وأقواها، والطلاب المحتاجون لعلاج أو إثراء، وتطور الأداء عبر الفترات.","اللائحة: **يحلل المعلم نتائج طلابه** لتحديد مواطن القوة والضعف وأسبابها وبناء خطة علاجية، وتحلل **لجنة التحصيل الدراسي** النتائج على مستوى المدرسة.","حساب النسبة المئوية لتحصيل الصف يحتاج عدد الطلاب ودرجاتهم والدرجة الكلية، ولا يحتاج عدد الفصول."],"ex":["في فصل من 30 طالبة أتقنت 12 معيار «حساب المساحة» (40%)، فتعيد المعلمة تدريسه للصف كله؛ وأتقنت 27 معيار «المحيط» (90%)، فتضع للثلاث الباقيات خطة علاجية في مجموعة صغيرة."],"traps":["نتيجة الطالب **سرية** تخصه وولي أمره والقائمين على تعليمه."],"src":"لائحة تقويم الطالب 2025 وإجراءاتها التنفيذية؛ المعايير التربوية العامة (مؤشر 10.3)."},"ar.l01.identity":{"k":"الهوية الوطنية","t":["Vision 2030 & National Identity","رؤية 2030 وتعزيز الهوية الوطنية"],"aka":["برنامج تنمية القدرات البشرية","رؤية 2030"],"body":["الهوية الوطنية تُبنى بشواهد يراها الطالب: خدمة الحرمين، ومنجزات رؤية 2030، والمشاريع الوطنية، لا بالوعظ المجرد. ومن واجبات المعلم في الميثاق أنه **أمين على كيان الوطن ووحدته**، يعمل لتسود المحبة بين المواطنين وبينهم وبين ولاة الأمر."],"pts":["**رؤية 2030** في التعليم: رفع جودة المخرجات، تنمية الشراكة المجتمعية، سد الفجوة بين التعليم وسوق العمل، التعلم مدى الحياة.","**برنامج تنمية القدرات البشرية** أحد برامج رؤية 2030، ويستهدف بناء المواطن بالقيم والمهارات من الطفولة المبكرة حتى التعلم مدى الحياة.","سؤال «الأمة أم الوطن؟» يُجاب بحوار هادئ: حب الوطن لا يتعارض مع الانتماء للأمة، ولا يُسكت الطالب ولا يُسخر منه.","ربط الدرس بشواهد علاقات المملكة الدولية وجهودها (خدمة الحرمين والحجاج) ينمي **المواطنة الصالحة** أفضل من الطلب العام بالمطالعة."],"traps":["تعليق الأعلام والمظاهر **وسيلة** لا غاية؛ البداية غرس مفهوم حب الوطن والمواطنة."],"src":"رؤية المملكة 2030 (برنامج تنمية القدرات البشرية)؛ ميثاق أخلاقيات مهنة التعليم 1427هـ"},"ar.l01.heritage":{"k":"مؤشر 1.2","t":["National Heritage in the Lesson","التراث الوطني والمناسبات في الدرس"],"aka":["التراث المادي","التراث غير المادي"],"body":["مؤشر الممارس 1.2 يطلب أن **يوظف المعلم خبرات ومواقف وأنشطة تعليمية** تدعم الاعتزاز بالهوية الوطنية السعودية **وبالتراث الثقافي الوطني**؛ أي أن يدخل التراث في الدرس والنشاط نفسه، لا أن يبقى مناسبة عابرة."],"pts":["**التراث المادي**: المباني التاريخية والمواقع الأثرية والحِرف والأدوات والأزياء.","**التراث غير المادي**: العادات والتقاليد والأمثال والشعر والفنون الشعبية كالعرضة وآداب الضيافة.","**التوظيف داخل المادة**: مسألة رياضية عن مساحة مبنى تراثي، نص قرائي عن الضيافة، مشروع عن حرفة من منطقة الطالب، مقابلة كبار السن، زيارة متحف أو موقع تراثي.","**المناسبات**: يوم التأسيس (22 فبراير) ذكرى تأسيس الدولة السعودية الأولى على يد الإمام محمد بن سعود عام 1139هـ (1727م)؛ اليوم الوطني (23 سبتمبر) ذكرى توحيد المملكة على يد الملك عبدالعزيز عام 1351هـ (1932م)؛ يوم العلم (11 مارس).","الاحتفاء يكون **بأنشطة هادفة** يشارك فيها الطلاب (بحث، معرض، عرض تاريخي، مسابقة معرفية) مرتبطة بالقيم، لا بالمظاهر الشكلية وحدها."],"traps":["يوم التأسيس = الدولة السعودية **الأولى** (1139هـ)؛ اليوم الوطني = **توحيد المملكة** (1351هـ)."],"src":"المعايير المهنية للمعلمين، هيئة تقويم التعليم والتدريب (1.2)؛ قواعد السلوك والمواظبة لطلبة التعليم العام، الإصدار الخامس 1447هـ (السلوك المتميز)"},"ar.l02.policy":{"k":"وثيقة 1390","t":["Education Policy Document (1390 AH)","وثيقة سياسة التعليم 1390هـ"],"aka":["سياسة التعليم","الأسس العامة","مصادر الأهداف"],"body":["صدرت بقرار مجلس الوزراء رقم **779** وتاريخ **1389/9/16هـ** في **236 مادة**، وهي «الخطوط العامة التي تقوم عليها عملية التربية والتعليم». وتشتهر باسم «سياسة التعليم 1390هـ»: إن سُئلت عن سنة الوثيقة فالمعتمد 1390هـ، وإن سُئلت عن تاريخ القرار نفسه فهو 1389هـ.","وقد ألغاها [[قرار مجلس الوزراء 103|ar.law.repeal]] (1448هـ) المصاحب لنظام التعليم العام، مع بقاء أحكامها سارية حتى يصدر البديل."],"pts":["**الأسس العامة** تبدأ بالإيمان بالله رباً وبالإسلام ديناً وبمحمد ﷺ نبياً ورسولاً، والتصور الإسلامي للكون والحياة والإنسان.","**الغاية** من التعليم: فهم الإسلام فهماً صحيحاً متكاملاً، وغرس العقيدة ونشرها، وتزويد الطالب بالقيم والمعارف والمهارات.","**مصادر الأهداف**: العقيدة الإسلامية، الأوضاع الاجتماعية والاقتصادية ومطالب التنمية، اتجاهات العصر، حاجات المواطن.","**من مبادئها**: التربية المتكاملة (إعداد المواطن المؤمن إعداداً سليماً متوازناً)، طلب العلم فريضة، حق الفتاة في التعليم، توجيه العلوم توجيهاً إسلامياً.","**المراحل**: ابتدائي 6 سنوات، متوسط 3، ثانوي 3 (السلم 12 صفاً)؛ ولذوي الاحتياجات الخاصة توضع **سياسة شاملة لرعايتهم**؛ وتأسست وزارة المعارف عام **1373هـ**، والتعليم حق لكل مواطن تكفله الدولة.","**سن القبول** في الصف الأول: من أكمل **ست سنوات هجرية** في اليوم الأول من الدراسة أو قبله، ويجوز قبول من يقل عمره بما لا يزيد على 90 يوماً بعد قبول من أتم السادسة؛ وهذه من **قواعد القبول** في الوزارة لا من نص الوثيقة، وفي النظام الجديد يحدد سنَّ القبول المجلس (المادة 8)."],"traps":["**اللجنة العليا لسياسة التعليم** تختص بإقرار الخطة التعليمية ورسم السياسة، لا بإعداد المعلمين ولا بناء المقررات؛ أما نص الوثيقة فيذكر «مجلساً أعلى للتعليم» (م231).","سنة الوثيقة **1390هـ**، وتاريخ قرارها **1389هـ**."],"src":"سياسة التعليم في المملكة العربية السعودية (قرار مجلس الوزراء 779 وتاريخ 1389/9/16هـ)؛ قواعد القبول في وزارة التعليم؛ قرار مجلس الوزراء 103 (1448هـ)"},"ar.l02.jobsmore":{"k":"لائحة","t":["Education Jobs Regulation: Details","لائحة الوظائف: الترقية والأداء والإجازات"],"aka":["الأنشطة اللاصفية","الفاقد التعليمي","إجازات المعلم"],"body":["تفاصيل من لائحة الوظائف التعليمية تتكرر في الأسئلة بعد الرتب والرخصة."],"pts":["**الترقية**: رخصة سارية بالمستوى المطلوب + تقويم أداء **جيد جداً فأعلى** آخر ثلاث سنوات + إكمال سنوات الرتبة (6 بكالوريوس / 5 ماجستير / 4 دكتوراه).","**الأنشطة اللاصفية**: الحصص غير التدريسية كالتخطيط والتقويم وإدارة الأنشطة والمشاركة في التطوير المهني والأعمال الإدارية.","**تقويم الأداء** يُعدّ سنوياً ويحق للموظف التظلم منه؛ ومن **حقوق** المعلم الاطلاع عليه، أما حضور الاجتماعات والمشاركة في النشاط ودراسة المناهج فـ**واجبات**.","**إجازات المعلم**: الصيفية مع نهاية العام الدراسي، والمرضية والاضطرارية بضوابط نظام الخدمة المدنية؛ و**الاضطرارية** لا تتجاوز خمسة أيام في السنة ولا تُخصم من الصيفية.","**تعديل 1446**: الرخصة إلزامية لمزاولة التعليم اعتباراً من فبراير 2026 مع إعفاء من بلغ الخمسين قبله، وأُلغي ربط العلاوة بالرخصة.","**الفاقد التعليمي** مصطلح يرد مع هذا الباب: ما يخسره النظام التعليمي بسبب **الرسوب والتسرب**، وله آثار تربوية واجتماعية واقتصادية."],"traps":["الاطلاع على تقويم الأداء **حق**؛ حضور الاجتماعات والنشاط **واجب**."],"src":"لائحة الوظائف التعليمية بتعديلات 1446هـ"},"ar.l02.grades":{"k":"قواعد 1447","t":["Behavior & Attendance Grades","درجات السلوك والمواظبة في قواعد 1447"],"aka":["درجة السلوك","درجات الحسم","المواظبة"],"body":["صدر **الإصدار الخامس** من قواعد السلوك والمواظبة لطلبة التعليم العام عام **1447هـ (2025م)** وألغى ما سبقه. وللطالب درجتان منفصلتان: **السلوك 100** و**المواظبة 100**."],"pts":["**السلوك**: **80 للسلوك الإيجابي** يستحقها تلقائياً بداية كل فصل وتُحسم عند المخالفة، و**20 للسلوك المتميز** تُكتسب بممارسات تعكس القيم الإسلامية والهوية الوطنية (الانضباط، التسامح، الأمانة، العزيمة، التعاون، الانتماء الوطني).","**الحسم** حسب درجة المشكلة: 1، 2، 3، 10، 15؛ وللطالب **فرص تعويض** للمحسوم بممارسات السلوك المتميز، والتعويض **لا يعفيه** من بقية الإجراءات.","**الضمانات**: **مناسبة الإجراء للمرحلة العمرية** والظروف، و**سرية** معلومات الطالب المخالف، وتزويده **بنوع المشكلات** التي حُسمت بسببها درجاته إذا طلب.","**المواظبة** من الثالث الابتدائي إلى الثالث الثانوي (وتقدير كيفي في الصفين الأول والثاني): تُحسم **درجة واحدة عن كل يوم غياب بدون عذر**؛ والعذر المقبول في وقته لا يؤثر فيها.","**تجاوز الغياب بدون عذر 10%** من أيام العام يحرم الطالب من الانتقال: الابتدائية والمتوسطة إلى العام التالي، والثانوية إلى الفصل التالي.","تكرار الغياب بدون عذر: تحويل إلى **الموجه الطلابي** ← إحالة إلى **لجنة التوجيه الطلابي** ← مخاطبة **الجهات المختصة** وفق نظامي حماية الطفل والحماية من الإيذاء، مع استمرار الخدمات التعليمية واستكمال الغائب خطة التعلم بعذر أو بدونه."],"traps":["الموجه الطلابي **لا يحسم** درجات السلوك ولا المواظبة؛ دوره دراسة الحالة وعلاجها."],"src":"قواعد السلوك والمواظبة لطلبة التعليم العام، الإصدار الخامس 1447هـ"},"ar.l04.parenttools":{"k":"أولياء الأمور","t":["Parent Communication Channels","قنوات التواصل مع الأسرة"],"aka":["الخطاب الإداري","تقنيات التواصل"],"body":["التواصل الفاعل مع ولي الأمر منتظم ومتنوع القنوات، ولا يقتصر على المشكلات."],"pts":["تقنيات التواصل تُطلع أولياء الأمور على **خطط المعلم التدريسية وتعلم الطلاب**.","تطبيقات مثل **ClassDojo** و**Remind** تتيح التواصل المنتظم وإطلاع أولياء الأمور على التقدم دون استدعاء.","**School Circle**: مشاركة الملفات ومساحة افتراضية للنقاش بين المعلم والطلاب وأولياء الأمور؛ و**TeacherApp**: رصد الحضور والغياب والتقييم.","العلاقة الفاعلة تُظهر **الجانب الإيجابي** وتدعو ولي الأمر للفعاليات والتكريم، وولي الأمر المتعاون يُمنح عضوية **مجلس المدرسة**.","**الخطاب الإداري** لمدير المدرسة أو جهة رسمية: عنوان، تحية، موضوع واضح، خاتمة، توقيع؛ لا رسالة ودية ولا شفهية.","الميثاق: المعلم **شريك الوالدين**، ويحفظ **سرية** الاجتماعات، ولا يتحدث عن الطالب أمامه مدحاً أو ذماً."],"src":"مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ (المادة 9)؛ ميثاق أخلاقيات مهنة التعليم 1427هـ"}};
